// Generated by scripts/build_curriculum.py - do not edit by hand.
window.CURRICULUM = {"goalDays": 120, "subjects": [{"id": "the-science", "title": "How Learning Really Works", "order": 1, "lesson": "the-science.html", "days": [{"focus": "Studying Is Not Learning", "review": "Studying is the activity — reading, highlighting, rewriting. Learning is the outcome: knowledge actually in your head *and usable*. Hours measure studying, not learning. Today's practice closes that gap by testing what stuck.", "task": {"do": "Open one topic you studied yesterday (notes, lecture, or chapter). Close all materials. Write from memory, in 3–5 sentences, what you can now explain or do that you couldn't before. Do not peek.", "capture": "Paste your 3–5 sentence from-memory explanation (or note if the page was nearly blank).", "minutes": 8}, "check": [{"q": "Looking at your from-memory write-up (or nearly blank page), what does that outcome tell you about studying versus learning for this topic — and why?", "rubric": "correct: Distinguishes studying (activity/time) from learning (knowledge in head and usable); ties judgment to their blank or solid recall. mostly_correct: Names the studying-vs-learning gap but weakly links to their attempt. incorrect: Blames talent/hours only, or treats blank recall as irrelevant.", "exemplar": "A nearly blank page means I spent time studying without converting it into learning — the ideas aren't in my head in usable form. Solid recall would mean that session actually produced learning, not just desk time. Hours don't measure learning; what I can explain without peeking does."}, {"q": "In your own words, how would you judge whether today's closed-book attempt showed learning, not just studying?", "rubric": "correct: Uses ability to explain/use from memory as the criterion; references their capture. mostly_correct: Mentions recall but omits usability or their result. incorrect: Equates neat notes, page count, or feeling busy with learning.", "exemplar": "Learning showed up if I could explain the ideas from memory in clear sentences and could imagine using them. If I only recognized notes when looking, that was studying activity without learning. My capture is the evidence either way."}, {"q": "Based on how today's attempt went, what is the strongest next study move for this same topic — and why that move?", "rubric": "correct: Proposes a process that forces producing ideas then retesting closed-book; justified by today's result. mostly_correct: Suggests restudy without naming production/retest. incorrect: Highlights more, copies notes, or delays until the exam.", "exemplar": "I should restudy with a method that makes me generate the ideas myself, then close the book and retest. Passiveing or copying won't fix a blank page. The next move is change the process, then check again without peeking."}]}, {"focus": "Retention × Mastery", "review": "Serious goals need *both* retention (knowledge that stays) and mastery (you can apply, analyze, judge — not only regurgitate). Perfect recall of isolated facts you can't use fails the goal. Aim for deep, usable knowledge that sticks.", "task": {"do": "Pick one concept from your current course. Rate it 1–5 for retention (how well it sticks without notes) and 1–5 for mastery (how well you can apply or judge with it). Write one concrete example of using it — or admit you can't.", "capture": "Concept name; retention score; mastery score; your use-example or 'cannot use yet'.", "minutes": 8}, "check": [{"q": "Using your retention and mastery scores (and whether you could invent a use-example), what does that pattern say about how ready this concept is for a serious goal?", "rubric": "correct: Applies retention × mastery; notes that high recall without use (or use without lasting retention) is incomplete. mostly_correct: Mentions one half only. incorrect: Treats high retention alone as full readiness.", "exemplar": "If retention is high but mastery is low and I can't invent a use-example, I have recall without usable mastery — incomplete for serious goals. If I can apply it but forget within a week, retention is failing. I need both lasting knowledge and the ability to use it."}, {"q": "Which half — retention or mastery — is weaker for the concept you rated, and what in your capture shows that?", "rubric": "correct: Picks the weaker half with evidence from scores/use-example. mostly_correct: Picks a half without clear evidence. incorrect: Contradicts their own scores or invents unrelated criteria.", "exemplar": "Mastery is weaker: I scored it low and couldn't write a concrete use-example, even if the definition sticks. That means I can regurgitate without applying or judging. Fixing mastery means practicing use, not more familiarity with the wording."}, {"q": "What specific practice would raise the weaker half for this concept next session, and why would that work better than rereading the definition?", "rubric": "correct: Names apply/analyze/judge practice for mastery or spaced retrieval for retention; contrasts with passive reread. mostly_correct: Names a reasonable practice without clear contrast. incorrect: Only more passive familiarity.", "exemplar": "I'd put the concept on a real problem from my course and force a judgment or application — that builds mastery. Rereading the definition only increases familiarity. If retention is the weak half, I'd explain it closed-book after a delay instead of another passive pass."}]}, {"focus": "Spot Isolated Knowledge", "review": "Isolated knowledge sits in a silo — one fact memorized alone. The brain treats it as irrelevant and forgets it fast. Real problems aren't isolated, so siloed facts are hard to use. First skill: notice isolation in your own notes.", "task": {"do": "Scan one page of your own notes or a textbook section. Circle or list 3 facts/definitions that stand alone with almost no links to other ideas. For each, write one missing connection you *could* make.", "capture": "Three isolated items + the connection you would add for each.", "minutes": 8}, "check": [{"q": "Why are the three standalone facts you listed risky for memory and use, according to how isolation works?", "rubric": "correct: Isolated info looks irrelevant, is forgotten quickly, and is hard to use on real (non-isolated) problems; cites their items. mostly_correct: Says isolation is bad without mechanism. incorrect: Claims isolation helps mastery or only length/order matters.", "exemplar": "Those three definitions have almost no links, so the brain treats them as irrelevant and drops them fast. Real problems aren't isolated, so siloed facts stay hard to use. Isolation — not sentence length — is what makes them fragile."}, {"q": "Which of your three items looks most isolated, and what missing connection would you add first?", "rubric": "correct: Picks the weakest-linked item and proposes a concrete connection. mostly_correct: Picks an item but vague connection. incorrect: Uses order/length or says no fix needed.", "exemplar": "The loneliest item is the one with no clear link to anything else I know. I'd connect it to a neighboring concept on the page — how it causes, contrasts with, or belongs under that idea — so it stops sitting in a silo."}, {"q": "Describe the strongest fix for one isolated fact from today's list, and why rewriting or highlighting alone wouldn't be enough.", "rubric": "correct: Integration/connection to related knowledge; rejects rewrite/highlight as sufficient. mostly_correct: Mentions connecting without rejecting passive fixes. incorrect: Only rewrite, highlight, or delete.", "exemplar": "I'd deliberately link the fact to a related idea I already know or another concept on the page. Rewriting or neon highlighting leaves it isolated. Integration is what makes it relevant and usable."}]}, {"focus": "Build Integrated Links", "review": "Integrated knowledge is connected: you compare ideas, find similarities and differences, and see relationships. Connected info looks relevant, so the brain holds it. Higher-order learning connects information so retention follows.", "task": {"do": "Choose two related concepts from your current topic. Without copying notes, write: (1) how they are similar, (2) how they differ, (3) when you would use one vs the other.", "capture": "The two concepts + similarity + difference + when-to-use-each.", "minutes": 8}, "check": [{"q": "If your capture had only separate definitions and no compare/contrast, what learning work did you skip — and how would you rewrite one pair to fix it?", "rubric": "correct: Names integration (relating ideas); gives similarity/difference/when-to-use. mostly_correct: Mentions linking vaguely. incorrect: Says definitions alone equal deep learning.", "exemplar": "I skipped integration — the linking that makes knowledge relevant. I'd rewrite: how A and B are similar, how they differ, and when I'd use one versus the other. Separate definitions leave the ideas isolated."}, {"q": "Looking at what you wrote for similarity, difference, and when-to-use, what makes that a strong (or weak) integration attempt?", "rubric": "correct: Evaluates whether compare/contrast and decision rule are present and meaningful. mostly_correct: Describes capture without clear quality criteria. incorrect: Praises copied sentences or vague 'related somehow'.", "exemplar": "Strong integration has a clear similarity, a real difference, and a decision rule for when each applies. Copied textbook lines or 'they seem related' are weak. My capture works to the extent those three pieces are specific."}, {"q": "After linking these two ideas, what is the best immediate follow-up to grow the network further — and why?", "rubric": "correct: Add another concept and relate it to the pair; justifies schema growth. mostly_correct: Mentions more practice without network growth. incorrect: Passive reread, definition-only cards, or switching subjects to avoid thinking.", "exemplar": "I'd pull in a third concept and ask how it relates to the pair. Growing deliberate relationships builds an integrated schema. Stopping at two isolated definitions or more highlighting doesn't expand the network."}]}, {"focus": "Schemas: Knowledge as a Network", "review": "Your brain stores knowledge in schemas — networks of connected ideas. Experts don't hold ordered lists; they navigate a web from any entry point. That network is what lets them solve complex problems.", "task": {"do": "For one chapter or lecture, sketch a mini-schema: put the core idea in the center, then add 4–6 related ideas as connected nodes (lines between related ones). Use your own material; no linear outline.", "capture": "Describe your center node and list each connected node with one link reason (why it connects).", "minutes": 10}, "check": [{"q": "If your sketch was mostly a numbered list with few cross-links, what schema quality is missing — and how would you change the sketch?", "rubric": "correct: Network structure / multiple navigable relationships; proposes cross-links. mostly_correct: Says 'needs more connections' vaguely. incorrect: Focuses on handwriting, more bullets, or a glossary.", "exemplar": "What's missing is network structure — relationships I can enter from more than one point. I'd redraw with a center idea and explicit lines stating why nodes connect, not a linear outline. Schemas are webs, not ordered lists."}, {"q": "Can you enter your mini-schema from a side node and still reach the center? What does that (or failure to) show about how usable the schema is?", "rubric": "correct: Multiple entry points = usable integrated schema; failure = list-like or fragile. mostly_correct: Mentions navigation without clear judgment. incorrect: Treats page order memorization as schema quality.", "exemplar": "If I can start from a side node and still explain the path to the center, I have a usable schema with multiple entry points. If I can only recite top-to-bottom, I mostly memorized order. Experts navigate a web, not a list."}, {"q": "Pick your weakest node. What repair would strengthen it, and why wouldn't writing the definition again be enough?", "rubric": "correct: Add meaningful link(s) to other nodes; rejects more isolation/definition drills. mostly_correct: Mentions linking weakly. incorrect: More definitions, remove links, or flashcard-only.", "exemplar": "I'd add at least one meaningful link from that weak node to another idea already on the map. Writing the definition again keeps it isolated. Schema strength comes from relevant connections."}]}, {"focus": "Process Builds Schema Quality", "review": "The process you use while studying determines the schema you build — and that schema drives both retention and mastery. Memory is almost a side effect of good schema-building. Audit *how* you study, not only *what*.", "task": {"do": "Replay your last study block on one topic. List the exact activities (e.g., reread, highlight, quiz, map). Mark each as schema-building (connect/compare/organize) or silo-building (copy/isolate/memorize alone). Pick one silo habit to replace next session.", "capture": "Activity list with marks + the one habit you will replace and with what.", "minutes": 8}, "check": [{"q": "Looking at your activity list, what does the mix of schema-building vs silo-building activities imply about the quality of schema you were building?", "rubric": "correct: Ties process to schema quality; notes that highlight/rewrite-alone likely builds weak isolation. mostly_correct: Lists activities without clear implication. incorrect: Claims any writing builds expert networks or process doesn't matter.", "exemplar": "If most activities were highlight and rewrite definitions, my process likely built weak, isolated schemas. Schema-building means connect, compare, organize. Process determines schema quality — and thus retention and mastery."}, {"q": "Explain the habit you chose to replace and what you will do instead. Why does that swap upgrade schema quality?", "rubric": "correct: Names a silo habit and a connect/compare/map replacement with clear rationale. mostly_correct: Names swap without schema rationale. incorrect: More colors, neater same linear notes, or faster passive intake.", "exemplar": "I'll swap one reread for compare/contrast or mapping how ideas fit. That forces relationships during study, which raises schema quality. Neater linear notes or more highlighter colors keep the same silo process."}, {"q": "Why prioritize changing process over simply adding more study hours after today's audit?", "rubric": "correct: Better process → better schemas; more hours of weak process still fail. mostly_correct: Mentions process vaguely. incorrect: Hours never matter, or schemas only form in sleep.", "exemplar": "Hours of weak process still produce fragile schemas. Changing how I study builds better networks, which drive retention and mastery. More time doing isolation-friendly habits won't fix the audit."}]}, {"focus": "The Snowball Effect", "review": "The more connected knowledge you have, the easier new learning becomes. Integrated learners accelerate; isolated learners get more overwhelmed. Today's practice uses what you already know as hooks for new material.", "task": {"do": "Open brand-new material from your course (a section you haven't studied yet). Before reading deeply, list 3 things you already know that might connect. After a short read, write how each new idea hooks to one prior idea — or mark 'no hook yet'.", "capture": "Prior hooks (3) + new ideas and their hooks (or 'no hook yet').", "minutes": 10}, "check": [{"q": "Looking at your prior hooks and 'no hook yet' marks, what does that pattern signal about isolation risk and the snowball effect?", "rubric": "correct: No hooks = isolation/overload risk; easy hooks = existing schema helping (snowball). mostly_correct: Mentions connections without snowball/isolation. incorrect: Says hooks are optional or memorize-first forever.", "exemplar": "If every new idea got 'no hook yet,' I'm at risk of isolation and overload — I need to force connections or simplify the frame. When links come easily, my existing schema is helping: the snowball effect. Integrated learners accelerate; isolated ones get overwhelmed."}, {"q": "Describe one successful hook you made today. Why does linking new material to prior knowledge make the next learning easier?", "rubric": "correct: Concrete hook + snowball/schema explanation. mostly_correct: Describes hook without why it helps. incorrect: Linking means skip review forever or prior knowledge blocks learning.", "exemplar": "I hooked the new idea to a related concept I already mapped, which made it feel relevant immediately. Connected prior knowledge gives new ideas places to attach, so learning gets easier over time — the snowball. Without hooks, each piece starts from zero."}, {"q": "For one unhooked new idea, what is the strongest next move — and why not put it on a flashcard with no relationships?", "rubric": "correct: Relate to mapped knowledge or place under a bigger purpose; rejects relationship-free cards as primary fix. mostly_correct: Mentions connecting vaguely. incorrect: Ignore until final, or flashcard-only with no links.", "exemplar": "I'd ask how it relates to something already on my map; if nothing fits, I'd place it under a clearer bigger purpose. A relationship-free flashcard keeps it isolated. Deliberate relating turns intake into schema growth."}]}, {"focus": "Neuroplasticity Needs Pressure", "review": "Learning rewires the brain with effortful, repeated practice. Change needs sustained pressure — like the gym. A new method feeling hard after one try isn't failure; it isn't a habit yet. Potential isn't fixed: good memory is mostly trainable process.", "task": {"do": "Choose one harder learning habit from this subject (e.g., closed-book explain, compare/contrast, schema mapping). Do one 5-minute rep on your real material. Then write: (1) what felt hard, (2) whether you'd quit based on that feeling, (3) one reason to continue for another week.", "capture": "Habit chosen + difficulty note + quit-or-not + reason to continue.", "minutes": 8}, "check": [{"q": "The new habit felt awkward and slow. What does that difficulty mean for neuroplasticity and habit change — not for whether the method 'failed' today?", "rubric": "correct: Expected rewiring pressure; early difficulty ≠ failure or fixed low capacity. mostly_correct: Says keep going without mechanism. incorrect: Abandon because hard, or only easy methods rewire.", "exemplar": "Awkwardness is expected — rewiring needs sustained effort before a habit feels natural. One hard rep isn't failure or proof of fixed low memory. Potential is trainable through process; difficulty is the pressure that drives change."}, {"q": "You may have felt like quitting. What mindset matches the course, and how will you treat that hard feeling in the next week?", "rubric": "correct: Difficulty as training signal; schedule more short reps; process trainable. mostly_correct: Persist vaguely. incorrect: Switch to easiest forever or assume fixed talent.", "exemplar": "I'll treat the hard feeling as a training signal and schedule more short reps this week. Quitting at first friction blocks the wiring. Good memory is mostly trainable process, not fixed talent."}, {"q": "After today's single hard rep, what concrete practice plan for the rest of the week best turns the technique into a habit?", "rubric": "correct: Repeated short reps of the same habit on real material across the week. mostly_correct: Vague 'practice more'. incorrect: Never repeat, only easy habits, or read about plasticity instead of practicing.", "exemplar": "I'll repeat the same habit — closed-book explain, compare/contrast, or mapping — on new material several times this week. Sustained repeated effort turns a technique into a habit. One special attempt isn't enough."}]}, {"focus": "Full Application: Session Audit", "review": "Pull the threads together: learning ≠ studying; aim for retention × mastery; replace isolation with integration and schema-building process. Use your own study material for a full mini-session audit.", "task": {"do": "Study one real topic for ~8 minutes using integration on purpose: closed-book dump what you know, add 3 links between ideas, then write one way you could *use* the knowledge. No passive reread-only.", "capture": "Topic; from-memory dump; three links; one use-case.", "minutes": 10}, "check": [{"q": "Your application needed a from-memory dump, links, and a use-case. If any piece was missing or thin, what does that say relative to retention × mastery?", "rubric": "correct: Maps missing dump/links/use to retention vs mastery / studying-vs-learning. mostly_correct: Notes something missing without the goal frame. incorrect: Treats longer neat notes as enough.", "exemplar": "No use-case means missing mastery evidence — can I actually use the knowledge? Thin dump means weak retention in my head. Links without use still fall short of retention × mastery. Learning is usable knowledge that sticks, not just connected notes on the page."}, {"q": "What in today's capture best shows that studying converted into learning — or that it didn't yet?", "rubric": "correct: Cites recall of links/use without peeking vs page count/busyness. mostly_correct: Mentions recall vaguely. incorrect: Equates coverage, neatness, or feeling busy with learning.", "exemplar": "Learning showed if I explained links and a use from memory without much peeking. Covering more pages or neater notes only shows studying activity. Busyness isn't evidence that knowledge is in my head and usable."}, {"q": "If some links felt forced or shallow, what would you change in the next pass — and why not retreat to memorizing definitions alone?", "rubric": "correct: Rebuild with better compare/contrast and clearer central schema; rejects isolation retreat. mostly_correct: Mentions better links vaguely. incorrect: Abandon connections, more highlighting, or 'can't integrate'.", "exemplar": "I'd rebuild around a clearer center and real compare/contrast, not forced lines. Shallow links mean schema quality is weak, not that integration is impossible. Retreating to definition-only memorizing recreates isolation."}]}, {"focus": "Checkpoint: Hardest Moves", "review": "Checkpoint day: re-test the hardest practice moves — diagnosing studying-without-learning, spotting isolation, and choosing schema-building next steps — on fresh scenarios from your own work.", "task": {"do": "Pick a different topic than day 9. In 8 minutes: (1) closed-book 3-sentence explain, (2) mark one isolated vs one integrated idea in your notes, (3) write one process change for tomorrow. No rereading first.", "capture": "Explain attempt; isolated vs integrated examples; tomorrow's process change.", "minutes": 10}, "check": [{"q": "Your explain may be thin while notes look dense. Fresh judgment: what does that gap say about notes versus learning?", "rubric": "correct: Notes ≠ learning; need process that puts usable knowledge in head; cites their gap. mostly_correct: Mentions recall gap vaguely. incorrect: Dense notes prove mastery regardless of recall.", "exemplar": "Dense notes with a thin explain means the artifacts of studying aren't the same as learning. I still need a process that puts usable knowledge in my head. Checkpoint: studying-without-learning shows up exactly as this gap."}, {"q": "You marked one isolated and one integrated idea. Explain how you told them apart — and what would be wrong about swapping those labels.", "rubric": "correct: Isolation = lone/unlinked; integration = relationships/compare; swapping labels is wrong. mostly_correct: Partial definitions. incorrect: Says labels arbitrary or only diagrams integrate.", "exemplar": "Isolated means a lone definition with no links; integrated means deliberate relationships like compare/contrast. Swapping those labels is wrong — connections integrate; solitary facts isolate. Labels aren't arbitrary."}, {"q": "If yesterday was mostly reread and highlight, write the process change you chose for tomorrow and why it improves schema quality.", "rubric": "correct: Replace part of reread with closed-book explain and deliberate linking; process→schema rationale. mostly_correct: Mentions change without rationale. incorrect: Faster highlighting, outsource thinking, or only easy topics.", "exemplar": "I'll replace part of rereading with a closed-book explain and deliberate linking between ideas. That process builds schema instead of silos. Highlighting faster or outsourcing thinking won't raise schema quality."}]}]}, {"id": "myths-mindset", "title": "Myths & the Misinterpreted-Effort Trap", "order": 2, "lesson": "myths-mindset.html", "days": [{"focus": "Misinterpreted Effort", "review": "Effective learning feels effortful because your brain must work. The misinterpreted-effort trap flips that signal: hard feels like 'not working,' so people quit the methods that help. Today's practice catches that trap in your own study.", "task": {"do": "During (or right after) a real study block on your material, list 2 moments that felt effortful/frustrating and 2 that felt smooth/easy. For each, guess: was that effort a learning signal or an avoidance cue?", "capture": "Two hard moments + two easy moments, each with your guess (learning signal vs avoidance).", "minutes": 8}, "check": [{"q": "Using the hard and easy moments you logged, where might you have fallen into the misinterpreted-effort trap — and what would a better reading of that difficulty be?", "rubric": "correct: Hard generative work misread as 'not working'; difficulty as learning signal; easy passive work as suspicious. mostly_correct: Mentions trap without tying to their moments. incorrect: Hard always means broken method; maximize ease.", "exemplar": "When generating answers felt harder than rereading and I almost quit, I was misreading productive effort as failure. That difficulty is a learning signal. Smooth passive scanning that felt easy should make me suspicious — little struggle often means little learning."}, {"q": "For one 'easy' moment you marked, explain why the course would tell you to be suspicious of that smoothness.", "rubric": "correct: Smooth ease often = little learning; active learning costs effort; cites their moment. mostly_correct: Ease is bad vaguely. incorrect: Ease proves deep encoding.", "exemplar": "My easy moment was passive scanning with no struggle. The course says if learning feels smooth and easy, be suspicious. Active learning costs effort; comfort often means the brain isn't doing the work."}, {"q": "What is the strongest next move after spotting the trap today, and how will you treat difficulty in the next session?", "rubric": "correct: Keep an effortful method; treat difficulty as data not failure. mostly_correct: Persist vaguely. incorrect: Switch to highlight-only or wait for effortless study.", "exemplar": "I'll keep one effortful generative method and treat difficulty as data, not a quit signal. Replacing hard methods with highlight-only recreates the trap. Welcome difficulty from active methods."}]}, {"focus": "Don't Outsource the Thinking", "review": "Removing effort entirely — AI-made notes, borrowed summaries — treats the product as magic and skips the thinking that builds skill. Like paying someone to lift your weights: the bar moves, you don't get stronger.", "task": {"do": "Take one page of your own notes OR a summary you usually rely on (classmate/AI/outline). Cover it. Reconstruct the 3 most important ideas in your own words from memory, then uncover and mark what you missed.", "capture": "Your 3 reconstructed ideas + what you missed when you checked.", "minutes": 8}, "check": [{"q": "You tried to reconstruct ideas without the summary. What did the gaps (or lack of gaps) imply about outsourcing the thinking?", "rubric": "correct: Relying on the product skips thinking that builds learning; cites reconstruction result. mostly_correct: Mentions gaps without outsourcing link. incorrect: Summaries install mastery automatically.", "exemplar": "If I couldn't reconstruct much, relying on the summary skipped the thinking that builds learning — like paying someone to lift my weights. The magic is in the processing, not possessing notes. Gaps prove the product isn't the skill."}, {"q": "How should you use AI or borrowed notes going forward so you don't remove the effort that builds skill?", "rubric": "correct: Generate structure yourself; tools only to check gaps — not replace thinking. mostly_correct: Limit tools vaguely. incorrect: Full AI summary as only study.", "exemplar": "I should generate the structure and links myself, then use AI or outlines only to check gaps. Pasting a full summary and never thinking the links is outsourcing. Effortful processing has to stay mine."}, {"q": "After seeing what you missed, what follow-up closes those gaps in a way that still keeps the thinking yours?", "rubric": "correct: Restudy by generating connections, then retest closed-book. mostly_correct: Restudy without generation/retest. incorrect: Longer AI summary and stop practicing.", "exemplar": "I'll restudy the missed ideas by generating connections myself, then retest closed-book. A longer AI summary without practice just rebuilds dependence. Closing gaps requires my generative effort."}]}, {"focus": "Learning Styles Are a Myth", "review": "Decades of research find no fixed 'visual' or 'read/write' learning style you must cater to. Preferences and school-trained habits exist — but locking into one style handicaps you when information arrives in other formats.", "task": {"do": "Pick one concept from your course. Encode it three ways in ~2 minutes each: (1) a quick sketch/diagram, (2) a short written explanation, (3) say it aloud (or write what you'd say). Note which felt most comfortable vs which revealed gaps.", "capture": "Concept; what each format produced; comfort vs gaps for each.", "minutes": 10}, "check": [{"q": "If you skipped a format because of a 'learning style' label, what myth were you following — and what did today's three-format try show instead?", "rubric": "correct: Styles as fixed wiring are a myth; preferences ≠ destiny; multimodal revealed gaps/flexibility. mostly_correct: Mentions myth without evidence from try. incorrect: Defends fixed style lock-in.", "exemplar": "Skipping a sketch because 'I'm not visual' treats preference as fixed wiring — a myth. Encoding three ways showed preferences aren't destiny and uncomfortable formats can reveal gaps. Omni-learning beats style lock-in."}, {"q": "Which format felt uncomfortable but exposed a gap, and what should you do with that format next — and why?", "rubric": "correct: Use uncomfortable format more because it diagnosed weakness. mostly_correct: Mentions gap without plan. incorrect: Avoid uncomfortable formats forever.", "exemplar": "The sketch felt awkward but showed I couldn't structure the idea spatially — a gap my comfortable notes hid. I should use that format more for diagnosis and flexibility. Avoiding it protects the myth, not learning."}, {"q": "What takeaway from today's three-format practice will you apply when information arrives in a format you dislike?", "rubric": "correct: Practice extracting learning across formats; preferences aren't destiny. mostly_correct: Be flexible vaguely. incorrect: Pick one style forever.", "exemplar": "I'll practice extracting learning from whatever format arrives instead of labeling myself and refusing. Preferences are habits, not destiny. Becoming an omni-learner matters more than catering to a mythic style."}]}, {"focus": "Become an Omni-Learner", "review": "Almost every brain processes visual information faster than text, and many people have strong read/write habits from school. Those are habits, not destiny. Train yourself to learn from lectures, labs, diagrams, and text alike.", "task": {"do": "Take material you usually meet in only one format (e.g., text notes). Convert the same ideas into a second format you avoid (diagram from text, or verbal outline from a figure). Study from the new format for 5 minutes and note one insight you missed before.", "capture": "Original format → new format; insight the conversion revealed.", "minutes": 8}, "check": [{"q": "Conversion to a second format felt clumsy but may have surfaced a new relationship. What does that say about omni-learning versus style lock-in?", "rubric": "correct: Format change forced new processing; clumsiness ≠ reason to retreat. mostly_correct: Mentions insight without omni-learning. incorrect: Clumsiness means return to one style only.", "exemplar": "The clumsy conversion forced new processing and revealed a relationship linear notes hid — omni-learning paying off. Clumsiness isn't a signal to lock into one style. Extracting learning from multiple formats builds flexibility."}, {"q": "Your courses mix lectures, labs, readings, and diagrams. What is the worst response to that mix, and what will you practice instead?", "rubric": "correct: Worst = refuse non-preferred formats; instead pull structure from whatever arrives. mostly_correct: Mentions flexibility vaguely. incorrect: Defend refusing formats.", "exemplar": "Worst response is refusing any format outside my preferred 'style.' I'll practice pulling structure from whatever arrives and translating awkward formats into a working representation. Academic life delivers information every way."}, {"q": "What recurring practice will you schedule to train omni-learning on real coursework?", "rubric": "correct: Regular forced format switch on real topics. mostly_correct: Vague practice. incorrect: Never leave comfort format or buy 'style' products.", "exemplar": "Once a week I'll force a format switch on a real topic — diagram from text or verbal outline from a figure. Habits change with deliberate cross-format practice. That's how omni-learning is trained."}]}, {"focus": "Don't Just Copy Top Students", "review": "Copying a top student's visible technique can still fail you. The real work is invisible deep processing in their head. Many high achievers use mediocre techniques with excellent processing — and processing is trainable.", "task": {"do": "Name one technique you copied from a 'good student' (or study influencer). On your own material, use it for 5 minutes while narrating the thinking: what you're comparing, prioritizing, or questioning. Then write whether the value was the tool or the thinking.", "capture": "Technique; thinking you actually did; tool vs thinking verdict.", "minutes": 8}, "check": [{"q": "When you used the copied technique, was the value in the tool or in the thinking? Use what you narrated during the 5 minutes to justify your verdict.", "rubric": "correct: Deep processing (compare/prioritize/question) matters more than surface technique; cites narration. mostly_correct: Mentions thinking without evidence. incorrect: Tool/template alone guarantees results.", "exemplar": "If I only copied mind-map shapes with no comparing or prioritizing, I had technique without deep processing — likely weak results. The value is the invisible thinking. Processing is trainable and more decisive than mimicking a template."}, {"q": "What evidence in your capture shows you understood that processing quality beats copying visible technique?", "rubric": "correct: Cites judgment that thinking > template; or admits empty copying. mostly_correct: Vague agreement. incorrect: Tools alone create mastery; processing can't be trained.", "exemplar": "My verdict that thinking quality mattered more than which template I used shows I got the lesson. If the technique felt empty, that evidence also counts — surface copying without processing. High achievers' invisible work is the real target."}, {"q": "If the copied technique felt empty, what upgrade raises the thinking level without chasing more aesthetics?", "rubric": "correct: Keep simple tool; raise compare/evaluate/organize demands. mostly_correct: Mentions thinking vaguely. incorrect: More stationery, abandon structure, or more influencer copying.", "exemplar": "I'll keep a simple tool but raise the thinking — compare, evaluate, organize — while I use it. Collecting prettier templates won't fix empty processing. Upgrade the invisible work, not the aesthetics."}]}, {"focus": "Metacognition: Mechanic of Your Brain", "review": "If you don't know how your learning 'engine' works, you guess and hope when results tank — that's stressful. Metacognition means thinking about your own thinking: knowing what's working, why you're stuck, and how to adjust.", "task": {"do": "After studying one real topic, answer in writing: (1) What exactly did I do? (2) What stuck vs didn't? (3) Why do I think that happened? (4) One adjustment for next time. Be specific to this material.", "capture": "Your four answers tied to today's topic.", "minutes": 8}, "check": [{"q": "Rate the quality of your four metacognitive answers. What made them strong or vague, and what skill does that reflect?", "rubric": "correct: Metacognition = monitoring process, outcomes, causes, adjustments; judges specificity. mostly_correct: Mentions reflection vaguely. incorrect: Equates metacognition with memorizing the word.", "exemplar": "Vague answers like 'I studied / idk' show missing metacognition — I'm not clearly monitoring process, what stuck, why, and how to adjust. Specific cause-and-tweak answers mean I can fix the engine instead of guessing. That's thinking about my own thinking."}, {"q": "If you named a cause and an adjustment, why is that more useful than hoping results improve on their own?", "rubric": "correct: Known cause + planned change beats guessing/hoping; mechanic of learning. mostly_correct: Says reflection helps vaguely. incorrect: Causes don't matter; never change methods.", "exemplar": "Naming 'I only reread' and adjusting to 'closed-book explain' lets me fix the engine instead of guessing and hoping. Higher metacognition means even when struggling, I know why and how to improve. Blind hope isn't a strategy."}, {"q": "How will you use today's reflection tomorrow so metacognition actually changes outcomes?", "rubric": "correct: Run the planned adjustment and re-check what stuck. mostly_correct: Remembers reflection vaguely. incorrect: Ignore, blame talent, or reflect yearly only.", "exemplar": "Tomorrow I'll run the planned adjustment and re-check what stuck. Metacognition pays off only when it drives concrete, tested changes. Ignoring the reflection returns me to guessing."}]}, {"focus": "Know Your Learner Type", "review": "Unlike learning styles, learner type is real: your current habits, strengths, and time-wasters. Improvement accelerates when you make those explicit — which techniques actually help vs which only feel productive — then upgrade one at a time.", "task": {"do": "List 3 study habits you used this week on real coursework. Mark each: actually helps learning / only feels productive / unclear. For one 'feels productive' habit, write a replacement you'll try once.", "capture": "Three habits with marks + one replacement plan.", "minutes": 8}, "check": [{"q": "For a habit you marked 'feels productive,' what evidence from recall or use supports that mark — and what should you do next?", "rubric": "correct: If closed-book doesn't improve, treat as time-waster candidate and trial replacement. mostly_correct: Skeptical without plan. incorrect: Double the feel-good habit; call it fixed style.", "exemplar": "Neat rewriting felt productive but didn't improve what I could recall — so it's a time-waster candidate. I'll trial a replacement once and re-measure. Learner type means spotting false productivity, not protecting comfort."}, {"q": "Why upgrade only one habit at a time after today's list, and which one will you change first?", "rubric": "correct: Focused change is evaluable; names one replacement; not identical to learning styles. mostly_correct: One change without why. incorrect: Change everything or never change.", "exemplar": "Focused change is faster to evaluate than changing everything at once. I'll replace one 'feels productive' habit first and check closed-book results. Learner type is real habits — not the learning-styles myth."}, {"q": "If closed-book checks fail after a habit, how should you mark that habit — and what does honesty here protect you from?", "rubric": "correct: Mark feels-productive/unclear; honesty protects against false productivity. mostly_correct: Mark lower without rationale. incorrect: Mark as helping despite failed recall.", "exemplar": "I'd mark it 'only feels productive.' Honesty protects me from sinking hours into habits that don't improve what I can explain or use. Calling it 'helps' without evidence locks in a weak learner type."}]}, {"focus": "Mistakes as Data", "review": "Across many learners, fast improvement tracked with willingness to make mistakes: try, get feedback, correct often. Slow improvers wait for the 'perfect method' and barely practice. Treat errors as data.", "task": {"do": "Do a short closed-book quiz on your own material (3 questions you invent from a lecture/chapter). Score yourself. For each miss, write what the error teaches you about a gap or process flaw — no self-scolding.", "capture": "Your 3 questions, results, and data-note for each miss (or 'no misses' + one stretch question).", "minutes": 10}, "check": [{"q": "You may have missed some self-test questions. What response treats those mistakes as data rather than as a reason to quit or wait for a perfect method?", "rubric": "correct: Feedback → correct within cycle; mistakes diagnostic; contrasts slow-improver waiting. mostly_correct: Learn from mistakes vaguely. incorrect: Quit, hide errors, or wait for perfect system.", "exemplar": "I'll use the misses as feedback and correct within this study cycle. Fast improvers try, get feedback, and correct often. Waiting for a perfect method before practicing is the slow-improver pattern."}, {"q": "Write a high-quality data-note for one miss (or stretch item): what gap or process flaw does it reveal, and what will you change?", "rubric": "correct: Specific causal note + actionable fix (not self-insult). mostly_correct: Vague gap. incorrect: 'I'm bad,' tests unfair, avoid topic.", "exemplar": "I confused X with Y because I never compared them — next I'll contrast them side by side, then retest. That turns the error into a process upgrade. 'I'm bad at this' isn't data; it's a dead end."}, {"q": "How does delaying practice while hunting for the 'right system' fit the slow-improver pattern — and what will you do instead this week?", "rubric": "correct: Waiting ≈ barely practicing; instead iterate with feedback soon. mostly_correct: Practice more vaguely. incorrect: Waiting is required before mistakes allowed.", "exemplar": "Delaying practice for the perfect system is the slow-improver pattern — little iteration, little feedback. This week I'll run short attempts, log misses as data, and correct quickly. Mistakes while practicing beat perfect plans unused."}]}, {"focus": "Full Application: Mindset Audit", "review": "Combine the myths: welcome effort, don't outsource thinking, drop style lock-in, prioritize processing and metacognition, treat mistakes as data. Run a full audit on a real study block.", "task": {"do": "Study one topic for ~8 minutes with: one effortful generative step, no full outsourcing of notes, one format stretch, and a 3-line metacognitive close (what worked / what didn't / next tweak).", "capture": "What you generated; format used; metacognitive close.", "minutes": 10}, "check": [{"q": "Audit today's session against the mindset goals (effortful generation, no full outsourcing, format stretch, metacognitive close). Where did you succeed or slip — and what does a slip imply?", "rubric": "correct: Concrete audit; slips like easy highlighting+AI = effort-removal/weak learning. mostly_correct: Partial audit. incorrect: Claims easy outsourcing matches the course.", "exemplar": "If the session was easy highlighting plus an AI summary with no generative step, I fell into effort-removal and likely weak learning. A strong session had generation I did myself, a format stretch, and a cause-and-tweak close. Application means living the myths' opposite."}, {"q": "Why does a metacognitive close that names a cause and a tweak matter more than a vague pep talk?", "rubric": "correct: Mechanic of learning — known cause and testable change. mostly_correct: Reflection helps vaguely. incorrect: Reflection replaces practice; never test tweaks.", "exemplar": "Naming a cause and a tweak means I'm the mechanic of my learning, not guessing blindly. Pep talks without causes don't steer the next session. The tweak still has to be tested in practice."}, {"q": "What in today's work shows you treated a miss or gap as data — or what would you add next time to make that true?", "rubric": "correct: Noted gap + scheduled correction (not comfort-only or wait-for-perfect). mostly_correct: Mentions a gap without correction plan. incorrect: Avoided testing to stay comfortable.", "exemplar": "I noted a gap and scheduled a correction, not only a pep talk — that's mistakes-as-data. If I avoided self-testing to stay comfortable, next time I'll invent questions, log misses, and fix them the same day. Willingness to err and correct predicts faster improvement."}]}, {"focus": "Checkpoint: Hardest Mindset Moves", "review": "Checkpoint: re-test misinterpreted effort, false productivity, and mistake-as-data decisions on fresh scenarios from your coursework.", "task": {"do": "On a new topic: (1) do one hard generative task for 5 minutes, (2) list one habit that only feels productive, (3) invent and answer 2 self-questions, logging misses as data.", "capture": "Generative task result; feels-productive habit; quiz outcomes + data notes.", "minutes": 10}, "check": [{"q": "The generative task felt worse than rereading. Fresh call: is that a quit signal or misinterpreted effort — and what will you do?", "rubric": "correct: Likely misinterpreted effort; stay with productive difficulty. mostly_correct: Persist vaguely. incorrect: Abandon hard methods; ease = effectiveness.", "exemplar": "Feeling worse than rereading is likely misinterpreted effort, not proof the method failed. I'll stay with productive difficulty. Ease is a poor effectiveness signal for active learning."}, {"q": "You listed a habit that only feels productive. What evidence would convince you to replace it next session, and how will you re-measure?", "rubric": "correct: Failed closed-book/use → replace and re-measure recall. mostly_correct: Replace without measurement. incorrect: Protect comfort habit as style.", "exemplar": "If it never improves closed-book results, I'll replace it next session and re-measure recall. Comfort isn't evidence. Upgrading time-wasters one at a time with evidence is learner-type work."}, {"q": "If you missed self-questions, what is the highest-value response in the next hour or two?", "rubric": "correct: Extract specific gap lessons and correct soon. mostly_correct: Review vaguely. incorrect: Stop until perfect; delete questions; only reread.", "exemplar": "I'll extract specific gap lessons and correct within the next hour or two. Fast improvers correct frequently. Stopping until I feel perfect, or only rereading, wastes the diagnostic value of the misses."}]}]}, {"id": "effort-struggle", "title": "The Effort–Time Exchange", "order": 3, "lesson": "effort-struggle.html", "days": [{"focus": "Spend Effort to Buy Time", "review": "Making learning easier per session often delays learning and costs more time later relearning. The real exchange: spend more effort up front so memory and understanding form sooner — buying time back overall.", "task": {"do": "Estimate last week: hours spent first-learning a topic vs hours re-studying what didn't stick. Then redesign tomorrow's plan for one topic: what higher-effort activity will you add to reduce relearning?", "capture": "Rough hours first-pass vs relearn; tomorrow's higher-effort swap.", "minutes": 8}, "check": [{"q": "Using your first-pass vs relearn hour estimates, what does the effort–time exchange imply about how you spent last week?", "rubric": "correct: Low effort up front delayed learning and created rework; cites estimates. mostly_correct: Mentions relearning without exchange. incorrect: Relearning proves easy methods optimal.", "exemplar": "Many relearn hours imply low effort up front delayed learning and created rework. The exchange says spend more effort early so understanding forms sooner. Passive hours don't buy time — they often spend it twice."}, {"q": "Explain tomorrow's higher-effort swap. Why is that plan more aligned with the lesson than covering more pages passively?", "rubric": "correct: Generate structure/answers under struggle; fewer pages but deeper; contrasts passive coverage. mostly_correct: Mentions effort without contrast. incorrect: Faster video, highlight-only, skip practice.", "exemplar": "I'll do fewer pages but generate structure and answers myself under real struggle. That effortful thinking strengthens memory and cuts later re-study. Covering more with zero digestion feels fast today and slow overall."}, {"q": "You may fear higher effort will slow you. Reframe that fear using the effort–time exchange.", "rubric": "correct: Higher effort per hour can reduce total time by cutting relearning. mostly_correct: Effort helps vaguely. incorrect: Speed only from zero effort; relearning is free.", "exemplar": "Higher effort per hour can make me faster overall by cutting relearning. Easy sessions that don't stick maximize total time. The exchange is spend effort now to buy time back later."}]}, {"focus": "Generation Effect", "review": "Actively generating answers, connections, and structure beats passively receiving them — the generation effect. Today's practice forces generation on your own material instead of intake-only.", "task": {"do": "Open one lecture/section. Before rereading, write from memory (or educated guess) the main claims and how they connect. Then check the source and mark what you generated correctly vs what you only recognized.", "capture": "Generated structure; correct vs recognize-only items.", "minutes": 8}, "check": [{"q": "You recognized a lot when peeking but may have generated little beforehand. What does that gap say about recognition versus the generation effect?", "rubric": "correct: Recognition ≠ generation; skipped stronger process; cites capture. mostly_correct: Mentions generation vaguely. incorrect: Recognition equals generating structure.", "exemplar": "Recognizing everything after peeking while generating little beforehand means I skipped the stronger process. The generation effect favors producing answers and structure, not passive receiving. Familiarity isn't production."}, {"q": "Which part of your capture best used the generation effect, and why does that part matter more than what you highlighted after looking?", "rubric": "correct: Pre-check production is the boost; post-look highlighting isn't generation. mostly_correct: Mentions generating without contrast. incorrect: Copied lines after looking count as generation.", "exemplar": "The ideas I produced before checking the source used the generation effect. Highlights and copied sentences after looking are recognition/cleanup. The learning boost comes from actively generating first."}, {"q": "For items you only recognized, what next move turns them into generation — and why isn't another passive reread enough?", "rubric": "correct: Hide source and regenerate until produceable. mostly_correct: Practice more vaguely. incorrect: Assume recognition enough; delete items.", "exemplar": "I'll hide the source and regenerate those items until I can produce them. Another passive reread keeps me in recognition. Turning recognize-only into generation is the point of the effect."}]}, {"focus": "Struggle Check: Reading", "review": "Ask while studying: am I at the right level of struggle? Passive reading — eyes scanning — is no struggle and little learning. Instead, actively decide which ideas matter and how they fit together.", "task": {"do": "Read 2–3 pages of your material with a struggle rule: after each half-page, look away and write the most important idea and how it fits the section. No continuous scanning without pauses.", "capture": "Your pause notes (important idea + fit) for each chunk.", "minutes": 10}, "check": [{"q": "If your pause notes were thin or empty after 'reading,' what failed the struggle check — and what does that mean for learning?", "rubric": "correct: Passive scanning / no struggle → little learning; cites notes. mostly_correct: Says reading was passive vaguely. incorrect: Empty notes mean efficiency.", "exemplar": "Empty pause notes mean I scanned in neutral — no struggle check passed. Passive reading with no selecting or relating is little learning. The engine was off even if pages got finished."}, {"q": "Pick your strongest pause note. What about it shows the right level of struggle for reading?", "rubric": "correct: Key idea + how it fits section structure. mostly_correct: Notes an idea without fit. incorrect: Only page numbers, copied sentences, or tiredness.", "exemplar": "My best note names an important idea and places it in the section's structure. That's selecting what matters and relating it — productive struggle. 'Read page 12' or a copied sentence without selection isn't struggle."}, {"q": "If reading felt too easy today, how will you raise generative struggle next time without just speeding up?", "rubric": "correct: More prioritize/relate pauses before moving on. mostly_correct: Slow down vaguely. incorrect: Remove pauses; skim with music; stop asking what matters.", "exemplar": "I'll increase generative pauses: prioritize and relate before moving on. Removing pauses to stay in flow drops struggle further. Ease while scanning is a warning, not a goal."}]}, {"focus": "Struggle Check: Notes", "review": "Note-taking like a human photocopier is no struggle. Real struggle means deciding what to write, how to phrase it, and what's important — generative choices, not transcription.", "task": {"do": "From one lecture/section, take notes with a constraint: max 8 lines, every line must be a decision (priority, relationship, or paraphrase in your words). No verbatim copying.", "capture": "Your 8-or-fewer lines + one sentence on what you chose to leave out and why.", "minutes": 8}, "check": [{"q": "Looking at your ≤8 lines, how much was decision-making versus photocopier transcription — and what does that say about struggle in note-taking?", "rubric": "correct: Struggle = decide priority/phrase/relationships; copying = low struggle. mostly_correct: Mentions copying vaguely. incorrect: Verbatim notes equal organization.", "exemplar": "If most lines are copied sentences, I was in photocopier mode — low struggle, weak processing. Real note struggle is deciding what to write, how to phrase it, and what matters. Transcription isn't generative choice."}, {"q": "Why did the task ask what you left out? What does that omission decision do for learning?", "rubric": "correct: Prioritizing is effortful processing that builds learning. mostly_correct: Mentions focus vaguely. incorrect: Never omit; omissions mean you weren't studying.", "exemplar": "Choosing what to leave out is prioritizing — effortful processing that builds learning. Omitting isn't failure; refusing to omit keeps me photocopying. Deciding importance is the struggle that turns notes into thinking."}, {"q": "If your notes still feel like a transcript, what constraint will you tighten next time and why?", "rubric": "correct: Force paraphrase + relationship labels; cut lines. mostly_correct: Shorter notes vaguely. incorrect: Type faster; record everything; more highlight colors.", "exemplar": "I'll force paraphrase and relationship labels and cut the line count again. Typing faster to capture every word increases photocopying. More decision-making in what I write is the right struggle."}]}, {"focus": "Struggle Check: Self-Testing", "review": "Self-testing by glancing then checking the answer is no struggle. Genuine struggle means trying to produce the answer before looking — productive frustration means the engine is running.", "task": {"do": "Create 4 questions from your own notes/lecture. Answer each on a blank page with materials closed. Only then check. Mark each: produced correctly / partial / looked too early / blank.", "capture": "Questions, your closed-book answers, and marks after checking.", "minutes": 10}, "check": [{"q": "Where did you peek early or avoid producing answers? What does that do to the self-testing struggle that makes testing work?", "rubric": "correct: Early peeking removes genuine production struggle. mostly_correct: Mentions peeking vaguely. incorrect: Peeking maximizes generation; blanks prove testing useless.", "exemplar": "Peeking midway because it felt uncomfortable avoided the struggle that makes self-testing work. Genuine production before looking is required. Glancing early turns testing into recognition practice."}, {"q": "A blank or partial answer you later fixed — how can that still be useful learning, not just failure?", "rubric": "correct: Productive frustration + feedback trains learning. mostly_correct: Mistakes help vaguely. incorrect: Only perfect first answers count; abandon topic.", "exemplar": "A blank I later fixed is productive frustration plus feedback — the engine running. Perfect first answers aren't required. The struggle of trying, then correcting, is what trains learning."}, {"q": "For items marked partial, what next move keeps genuine self-testing struggle instead of drifting into comfort peeking?", "rubric": "correct: Restudy gap then re-attempt closed-book without peeking. mostly_correct: Review vaguely. incorrect: Passive answer-key only; glance first next time.", "exemplar": "I'll restudy the gap, then re-attempt closed-book without peeking. Passive answer-key reading or peeking first removes the struggle. Keep genuine production attempts."}]}, {"focus": "Ask: How Can I Organize This?", "review": "The most powerful prompt for effortful processing is 'How can I organize this?' — not merely 'Do I understand this?' Organization time is learning time. Practice the prompt on real material.", "task": {"do": "Take one messy section of your notes or a dense textbook page. Spend 7 minutes only answering 'How can I organize this?' — regroup into categories, sequence, or a simple map. Don't add new highlighting.", "capture": "Before: one-line description of the mess. After: your organized structure.", "minutes": 8}, "check": [{"q": "You may have felt you 'understood' the section before organizing. What happened when you tried to regroup — and what does that say about understanding versus organized knowledge?", "rubric": "correct: Understanding without organization is shallow/weakly remembered; cites attempt. mostly_correct: Organization helps vaguely. incorrect: Understanding alone equals durable mastery.", "exemplar": "If I 'understood' it but couldn't regroup, that was shallow familiarity without organized knowledge. You can understand a messy room without organizing it — and memory stays weak. Organization time is learning time."}, {"q": "What in your 'after' structure shows the magic question 'How can I organize this?' actually worked?", "rubric": "correct: Ideas have clear places relative to each other. mostly_correct: Mentions cleaner notes vaguely. incorrect: More highlighter or longer quotes as success.", "exemplar": "Ideas now have a clear place relative to each other — categories, sequence, or map. More pink highlighter or longer copied quotes wouldn't show organization. The question worked if structure makes sense to me."}, {"q": "You spent most of the time organizing one section. Is that a worry or a win for learning time — and why?", "rubric": "correct: Often a win — time to organize is time to learn. mostly_correct: Organization matters vaguely. incorrect: Always waste vs covering more pages.", "exemplar": "It's often a win: how long it takes to organize something is how long it takes to learn it. Covering more pages without structure feels productive and forgets faster. Organization isn't optional neatness."}]}, {"focus": "Understanding ≠ Organized Knowledge", "review": "Understanding without organization feels like learning but slips away and fails problem-solving. Organized knowledge is structured so you can navigate and use it. Test the difference on your material.", "task": {"do": "Pick a topic you 'get' when reading. Without notes, try to teach a 60-second organized explanation with a clear order or structure. Then note where the explanation fell apart — those are organization gaps, not just 'memory' gaps.", "capture": "Your structured teach-back outline + where it fell apart.", "minutes": 8}, "check": [{"q": "Reading felt clear but your teach-back may have jumbled. What does that gap mean for understanding versus organized knowledge?", "rubric": "correct: Familiarity without organization — shallow for memory and use. mostly_correct: Mentions structure gap vaguely. incorrect: Clear reading means organization unnecessary.", "exemplar": "Clear reading with a jumbled teach-back means familiarity without organization — shallow knowledge. It feels learned but slips and fails problem-solving. The break points are organization gaps, not just 'bad memory'."}, {"q": "Where your teach-back fell apart, what repair should come before more rereading — and why?", "rubric": "correct: Rebuild structure (order/categories/relationships) first. mostly_correct: Review that part vaguely. incorrect: Passive reread until soothing; more isolated facts.", "exemplar": "I'll rebuild that part's structure — order, categories, relationships — before more rereading. Passive rereading restores the feeling of clarity without fixing navigation. Organization gaps need organization work."}, {"q": "What evidence in your capture would convince you that you now have organized knowledge, not just recognition?", "rubric": "correct: Structured teach-back you can navigate. mostly_correct: Mentions explanation vaguely. incorrect: Familiarity while scanning or unsorted highlights.", "exemplar": "A teach-back with clear structure I can navigate is evidence of organized knowledge. Feeling familiar while scanning or an unsorted highlight dump is recognition, not structure. Organized knowledge supports use."}]}, {"focus": "Active Reading as Organizing", "review": "Active reading isn't start-to-end coverage. Pick what's important, decide where it belongs, interrogate the source for answers you need, and rearrange ideas into something that makes sense to you.", "task": {"do": "Before reading a new section, write 3 questions you need answered. Read only to answer and place those answers into a simple structure (not linear copy). Stop when the structure holds, even if unread sentences remain.", "capture": "Your 3 questions; answers placed in your structure; what you skipped and why.", "minutes": 10}, "check": [{"q": "If you drifted into start-to-end coverage and ignored your questions, what active-reading moves did you skip?", "rubric": "correct: Interrogate for purpose, select, rearrange into your structure — not photocopy order. mostly_correct: Skimmed too much vaguely. incorrect: Coverage always equals organization.", "exemplar": "I skipped interrogating the source for my questions and rearranging answers into my structure. Active reading isn't start-to-end photocopying. Without those moves I consumed order, not organized knowledge."}, {"q": "You may have stopped with unread paragraphs once your structure answered your questions. Was that valid for active reading — why or why not?", "rubric": "correct: Valid if organization holds for purpose; learning needed layer ≠ every word. mostly_correct: Skipping OK vaguely. incorrect: Every word must be highlighted; never stop early.", "exemplar": "Yes — if the structure already answered my questions, I learned the needed layer. Endless coverage without structure isn't mastery. Skipping unread lines can be right when organization holds for my purpose."}, {"q": "What is the strongest sign today's reading was active rather than linear consumption?", "rubric": "correct: Ideas rearranged into question-driven structure. mostly_correct: Took notes vaguely. incorrect: Max speed finish; zero importance decisions; exact author order copy.", "exemplar": "Ideas rearranged into my structure driven by my questions is the strongest sign. Finishing every page at max speed with no importance decisions is consumption. Active reading = select, place, interrogate, rearrange."}]}, {"focus": "Full Application: Effort Session", "review": "Put the exchange together: raise struggle on purpose, generate before peeking, and organize as you go so you forget less and relearn less — especially under heavy workload.", "task": {"do": "One real topic, ~10 minutes: (1) generate a rough organization first, (2) read/notes only to improve that organization, (3) closed-book produce 3 answers, (4) note one relearning task you hopefully won't need later.", "capture": "Organization sketch; 3 closed-book answers; relearning note.", "minutes": 10}, "check": [{"q": "Did organizing first reduce rereading or closed-book failures still show up? What does your result say about the effort–time exchange?", "rubric": "correct: Ties result to effort buying time OR need to raise generation when ease misleads. mostly_correct: Mentions effort vaguely. incorrect: Organization increases relearning; trust reading ease.", "exemplar": "If organizing first cut rereading, effort up front bought time back. If closed-book still failed despite easy reading, I should raise generation — don't trust ease. Right struggle plus organization reduces rework under load."}, {"q": "If closed-book answers failed though reading felt fine, what next move raises the right struggle?", "rubric": "correct: Raise generation/struggle; don't trust reading ease. mostly_correct: Practice more vaguely. incorrect: Skip retrieval; only add passive hours.", "exemplar": "I'll raise generation and struggle — produce answers and structure — instead of trusting the reading feeling. Feeling of understanding without production is unreliable. More passive hours repeat the same mistake."}, {"q": "Under a heavy workload, which session pattern fits the lesson — and how does today's capture support choosing it?", "rubric": "correct: Higher effort per hour with organization to relearn less; cites session. mostly_correct: Work harder vaguely. incorrect: Easiest hours now; avoid all struggle.", "exemplar": "Higher effort per hour with organization so I relearn less later fits a heavy workload. Today's generate-organize-retrieve loop is that pattern. Easiest hours with maximum later relearning feel fast and cost more overall."}]}, {"focus": "Checkpoint: Struggle & Organize", "review": "Checkpoint: diagnose no-struggle habits, apply the organize prompt, and choose generation over recognition on fresh material.", "task": {"do": "New section: mark one no-struggle habit you were about to do; replace it for 8 minutes using 'How can I organize this?' + one closed-book generation round.", "capture": "Habit you replaced; organized result; generation outcome.", "minutes": 10}, "check": [{"q": "You almost fell into a no-struggle habit (e.g., photocopying). What replacement did you use, and why is that the right struggle?", "rubric": "correct: Decide priorities/structure instead of transcribing; decision-making = struggle. mostly_correct: Different habit vaguely. incorrect: Transcribe faster; avoid deciding importance.", "exemplar": "I replaced photocopying with deciding priorities and structure. Note-taking struggle is decision-making, not transcription speed. Highlighting a photocopy still skips the struggle."}, {"q": "If you organized well but peeked during generation, what struggle check still failed — and how will you fix it next time?", "rubric": "correct: Self-testing/generation requires produce-before-look. mostly_correct: Don't peek vaguely. incorrect: Peeking required for generation effect.", "exemplar": "Self-testing struggle was skipped — I must produce before looking. Organization doesn't replace retrieval production. Next time I'll finish the closed-book round before any peek."}, {"q": "Fresh scenario from today: reading felt easy but recall was weak. What call do you make about struggle level, and what will you switch to?", "rubric": "correct: Wrong struggle level → organize + generate. mostly_correct: Study differently vaguely. incorrect: Easy reading proves mastery; study less.", "exemplar": "Wrong struggle level — I was in neutral while reading. I'll switch to 'How can I organize this?' plus closed-book generation. Easy reading with weak recall means the engine wasn't running."}]}]}, {"id": "higher-order-thinking", "title": "The 6 Levels of Thinking", "order": 4, "lesson": "higher-order-thinking.html", "days": [{"focus": "Lower-Order: Remember & Understand", "review": "Levels 1–2 are lower-order: Remember (regurgitate — list, define, state) and Understand (explain). Necessary, but university and professional work rarely stop there. First, spot when your study is stuck at 1–2.", "task": {"do": "From one chapter/lecture, write 3 study questions you usually ask yourself. Label each Bloom level 1 (remember) or 2 (understand) or higher if it already is. Then rewrite any level-1 item into a level-2 'explain' question.", "capture": "Original questions with labels + rewritten explain versions.", "minutes": 8}, "check": [{"q": "Looking at your usual study questions and labels, what does the mix tell you about whether you're stuck at remember/understand?", "rubric": "correct: Many define/list = stuck at level 1; cites labels. mostly_correct: Mentions lower-order vaguely. incorrect: Define questions are already high-level.", "exemplar": "If most questions were 'What is… / Define…,' my practice is stuck at remember — regurgitation. Level 2 explain questions are a step up but still lower-order. University work rarely stops at 1–2, so I need to climb."}, {"q": "Take one rewrite you made from remember → understand. Why does that stem demand a higher thinking level than the original?", "rubric": "correct: Explain how/why in own words vs list/define. mostly_correct: Says harder vaguely. incorrect: Synonyms or faster recite as understand.", "exemplar": "Changing 'Define X' to 'Explain how X works in your own words' unlocks understand — making sense, not stating. Listing synonyms stays at remember. The rewrite demands sense-making."}, {"q": "After labeling today's questions, what is the strongest next move for your question mix across the coming sessions?", "rubric": "correct: Keep some 1–2 but add higher-level questions. mostly_correct: Add harder questions vaguely. incorrect: Only level 1 forever; labeling alone raises thinking.", "exemplar": "I'll keep a few level 1–2 checks for foundations but add higher-level questions next sessions. Awareness of level is step one; climbing toward analyze/evaluate is the goal. Labeling alone doesn't raise thinking."}]}, {"focus": "Level 3: Apply", "review": "Apply means use a concept to solve a problem — typically one concept → one problem. It is higher-order than explaining, but still below the analyze/evaluate work that separates good from great.", "task": {"do": "Pick one concept from your material. Invent or find one concrete problem/case where you must use it (not define it). Solve it with materials mostly closed; note where you needed to peek.", "capture": "Concept; problem/case; your solution attempt; peek points.", "minutes": 8}, "check": [{"q": "Did you solve a case with the concept or mostly restate the definition? What Bloom level did you actually practice, and why?", "rubric": "correct: Apply = use on a problem; restating = remember/understand. mostly_correct: Mentions apply vaguely. incorrect: Restating counts as evaluate/create.", "exemplar": "If I restated the definition instead of solving a case, I practiced remember/understand — not apply. Apply means one concept used on a problem to produce an answer. Definitions aren't application."}, {"q": "Describe how your case used the concept to produce an answer. What makes that level-3 apply practice?", "rubric": "correct: Concept → problem → solution attempt; simple problem solving. mostly_correct: Mentions a problem vaguely. incorrect: Calls any typing apply or jumps to evaluate automatically.", "exemplar": "I used the concept on a concrete case to produce a solution — classic level-3 apply. It's higher than explaining but still below analyze/evaluate. One concept → one problem is the apply pattern."}, {"q": "If you peeked for much of the solution, what fix rebuilds apply skill instead of only viewing worked answers?", "rubric": "correct: Retry similar case closed-book after brief structured review. mostly_correct: Try again vaguely. incorrect: Never attempt apply; memorize solutions only.", "exemplar": "I'll do a brief structured review, then retry a similar case closed-book. Application grows by producing solutions, not only viewing them. Staying on flashcards alone won't build apply."}]}, {"focus": "Level 4: Analyze", "review": "Analyze means compare and contrast, find relationships — unlocking comparison. This is where many courses begin to separate students. Practice relationship-finding on your own content.", "task": {"do": "Choose two related ideas from your course. Write a structured comparison: shared features, key differences, and one relationship (cause, category, trade-off, sequence, etc.).", "capture": "Pair; similarities; differences; relationship type + sentence.", "minutes": 8}, "check": [{"q": "If your write-up was two separate definitions with weak links, what level were you actually at — and what would analysis require instead?", "rubric": "correct: Still lower-order isolation; analyze needs compare/relationships. mostly_correct: Needs more linking vaguely. incorrect: Parallel definitions = full analyze.", "exemplar": "Two separate definitions with no links is still lower-order isolation — not analyze. Analysis requires compare/contrast and an explicit relationship. Parallel regurgitation isn't level 4."}, {"q": "What in your capture best shows analysis (or fails to), and what relationship type did you name?", "rubric": "correct: Contrast + explicit relationship (cause/category/trade-off/etc.). mostly_correct: Mentions comparison vaguely. incorrect: Longer quotes or 'both important' without comparison.", "exemplar": "Clear similarities, differences, and an explicit relationship (e.g., trade-off) show analysis. Longer copied quotes or 'both are important' fail. Comparison and relationships unlock level 4."}, {"q": "After a solid compare/contrast, what stretch moves you toward evaluate — and why?", "rubric": "correct: Ask which difference matters more for a decision and why. mostly_correct: Go deeper vaguely. incorrect: Stop at definitions; avoid relationships.", "exemplar": "I'd ask which difference matters more for a real decision and justify it — moving toward evaluate. Analyze feeds evaluate. Stopping at definitions retreats down the ladder."}]}, {"focus": "Level 5: Evaluate (The Target)", "review": "Evaluate means judge, prioritize, justify — 'so what?' Form and defend conclusions. For most learners, level 5 is the target; senior academic and professional work tests here. Create (6) is rarer.", "task": {"do": "From your material, pick 3 ideas in one topic. Rank them by importance for understanding the topic or for a realistic exam/clinical decision. Write a justification for #1 vs #3 — not 'because teacher said.'", "capture": "Ranked list + justification for top vs bottom.", "minutes": 8}, "check": [{"q": "Your ranking needed a justification for #1 vs #3. If justification was thin, what evaluate work was missing?", "rubric": "correct: Judge/prioritize/defend 'so what?'; order without reasons isn't evaluate. mostly_correct: Needs reasons vaguely. incorrect: Order alone is evaluate.", "exemplar": "Without justification I only ordered items — I didn't evaluate. Evaluate means judge, prioritize, and defend conclusions — 'so what?' Reasons, not teacher authority alone, make it level 5."}, {"q": "Why does the course treat level 5 as the practical target for most learners, given what exams and professional work demand?", "rubric": "correct: Uni/professional roles test mostly analyze–evaluate; create rarer. mostly_correct: Higher levels matter vaguely. incorrect: Level 5 easier than remember; evaluate replaces understanding.", "exemplar": "University and professional work mostly test at analyze–evaluate. Level 5 is the practical target; create (6) is rarer and for the highest tiers. That's why prioritize-and-justify practice matters."}, {"q": "Write one evaluate question stem for your topic tomorrow and explain why it sits at level 5 rather than remember.", "rubric": "correct: Importance + why / justify stem; contrasts with define/list. mostly_correct: Somewhat judgmental stem. incorrect: Define/list/highlight stems labeled as evaluate.", "exemplar": "'Which is more important for X, and why?' is evaluate — it demands judgment and defense. 'What is the definition of X?' is remember. The stem must force prioritizing, not regurgitating."}]}, {"focus": "Level 6 Awareness: Create", "review": "Create means synthesize something new — hypothesize. It matters at the highest levels; most students should prioritize evaluate first. Still, practice a light create move so you recognize the top of the ladder.", "task": {"do": "Using two+ ideas from your current topic, invent one small hypothesis, study question, or mini-example that isn't copied from the text — a new combination or prediction you could test against the material.", "capture": "Your created item + which source ideas you combined.", "minutes": 8}, "check": [{"q": "Was your created item truly new synthesis or a copied example? What does create require that copying doesn't?", "rubric": "correct: Create = synthesize something new from combined ideas; copying ≠ level 6. mostly_correct: Mentions originality vaguely. incorrect: Any writing is level 6.", "exemplar": "If I copied a textbook example, that wasn't create. Create synthesizes something new — a hypothesis, question, or mini-example from combining ideas. Copying stays lower-order even if handwritten."}, {"q": "Given limited study time, where should most practice sit after tasting level 6 — and why?", "rubric": "correct: Primarily analyze–evaluate (4–5), occasional create. mostly_correct: Focus on higher levels vaguely. incorrect: Only level 6 every session or only definitions.", "exemplar": "Most practice should sit at analyze–evaluate, with occasional create. For most learners level 5 is the target; level 6 is rarer. Living only at definitions wastes the ladder."}, {"q": "How will you use today's hypothesis or invented example next — still anchored to the material?", "rubric": "correct: Check against notes/lecture and refine. mostly_correct: Revisit vaguely. incorrect: Never check; brainstorm only forever.", "exemplar": "I'll check it against my notes/lecture and refine — thinking up the ladder while anchored to the course. Unchecked brainstorming drifts. Create still connects to real concepts through testing."}]}, {"focus": "Thinking Level ≠ Technique", "review": "Two people can use the same technique — reading or mind mapping — at totally different levels. One crams (level 1); another evaluates and prioritizes (level 5). Intention sets the result.", "task": {"do": "Choose one technique you already use (reading, flashcards, mapping, outlining). Do it twice for 3 minutes on the same topic: (A) with level-1 intention, (B) with level-5 intention (judge/prioritize). Capture what differed in your thinking.", "capture": "Technique; what you did in A vs B; difference in thinking.", "minutes": 8}, "check": [{"q": "Same technique, two intentions (level 1 vs 5). What differed in your thinking, and what does that show about technique versus thinking level?", "rubric": "correct: Intention sets level; same tool can be remember or evaluate. mostly_correct: Mentions difference vaguely. incorrect: Tool name fixes level.", "exemplar": "In B I forced ranking and justification while the map shape looked similar — intention changed the thinking level. Technique isn't the level; cognitive demand is. Same action, different learning."}, {"q": "If both rounds stayed at 'define this term,' what failed to rise — and how would you rewrite the intention?", "rubric": "correct: Intention never rose; change demand to judge/prioritize. mostly_correct: Make harder vaguely. incorrect: Flashcards automatically evaluate.", "exemplar": "Intention never rose — the technique stayed at remember. I'd rewrite cards to 'Which matters more and why?' or compare two terms. Raising level means changing thinking demand, not repeating the same tool."}, {"q": "What intention upgrade will you bring to reading tomorrow so it targets evaluate rather than page-finishing?", "rubric": "correct: Read to judge what matters most and why. mostly_correct: Read more carefully vaguely. incorrect: Memorize phrasing only; avoid prioritizing.", "exemplar": "I'll read to judge what matters most and why — not to finish pages. Level-5 reading aims at evaluate/prioritize. Matching highlighter colors or memorizing phrasing keeps intention at the bottom."}]}, {"focus": "Why People Retreat Downward", "review": "Moving from level 3 to 4–5 feels harder and slower, so the misinterpreted-effort trap pulls people back to easy lower levels. That extra effort is deeper memory forming. Notice retreat in yourself.", "task": {"do": "Attempt one level 4–5 task on your material for 5 minutes (compare or prioritize with justification). Then write: when you felt like switching to rereading/flashcard definitions, and whether that urge was comfort-seeking.", "capture": "Your 4–5 attempt + retreat urge note + your decision.", "minutes": 8}, "check": [{"q": "When analyze/evaluate felt slow, did you want to retreat to rereading or definitions? What does the course say that urge usually is?", "rubric": "correct: Misinterpreted effort / retreat to easier levels; deeper effort builds memory. mostly_correct: Hard means keep going vaguely. incorrect: Higher levels never help; rereading is higher-order.", "exemplar": "Wanting to bail to rereading is classic retreat to easier levels — often misinterpreted effort. The slower feel is deeper memory forming. The urge is comfort-seeking, not proof higher-order failed."}, {"q": "If you stayed with the hard compare despite discomfort, how should you interpret that discomfort?", "rubric": "correct: Effort cost that strengthens deeper encoding. mostly_correct: Good to persist vaguely. incorrect: Discomfort means wrong subject; higher-order should feel effortless.", "exemplar": "That discomfort is the effort cost that strengthens deeper encoding. Higher-order work shouldn't feel effortless immediately. Staying with it pays for stronger memory."}, {"q": "Write an anti-retreat rule you'll use next session when level 4–5 gets hard.", "rubric": "correct: Stay longer at analyze/evaluate before dropping; expect harder feel. mostly_correct: Don't quit vaguely. incorrect: At friction return to definitions only.", "exemplar": "When it feels harder, I'll stay five more minutes at analyze/evaluate before dropping. Ease isn't the success metric. Expect the harder feel and don't obey the trap's quit signal."}]}, {"focus": "Study Top-Down", "review": "Bottom-up (remember → … → evaluate) is slow; lower levels decay while you climb. Top-down: start at evaluate — lower levels fill in as a side effect because memory forms more strongly at level 5 than at level 1. Don't begin by trying only to remember.", "task": {"do": "Open a new or weakly learned section. First action: write evaluate questions only (Why does this matter? Which part is most important and why? How does A compare to B?). Study for 7 minutes solely to answer those — not to memorize lists.", "capture": "Your evaluate questions + answers you reached + any lower-level facts that appeared as side effects.", "minutes": 10}, "check": [{"q": "If you started with definition flashcards 'to build a base,' how does that conflict with studying top-down?", "rubric": "correct: Don't start by trying only to remember; start at evaluate. mostly_correct: Start higher vaguely. incorrect: Bottom-up is recommended default.", "exemplar": "Starting with definitions-only conflicts with top-down: the lesson says don't begin by trying only to remember. Start at evaluate questions; lower levels fill in along the way. Bottom-up is slow and decay-prone."}, {"q": "While aiming at importance/comparison, did lower-level understanding appear as a side effect? What does that show about top-down?", "rubric": "correct: Lower levels fill in when aiming high. mostly_correct: Learned extra vaguely. incorrect: Evaluate prevents understanding.", "exemplar": "While judging importance I suddenly could explain a mechanism — lower levels filling in as a side effect. Aiming at level 5 forces understand/analyze along the way. That's why top-down works."}, {"q": "Why is memorizing first and hoping evaluate appears later a weaker strategy than starting at evaluate?", "rubric": "correct: Memorizing doesn't produce evaluate ability; lower levels decay while climbing slowly. mostly_correct: Top-down better vaguely. incorrect: Memorizing unlocks level 5 automatically.", "exemplar": "Memorizing doesn't make me able to evaluate, and lower levels decay while I climb slowly. Starting at evaluate builds stronger memory and pulls lower levels along. Reverse order hopes for a skill it never practices."}]}, {"focus": "Full Application: Ladder Workout", "review": "Turn study questions up the ladder and generate level 4–5 practice — the same kinds of questions that separate good from great on exams.", "task": {"do": "For one exam-relevant topic, write 6 questions: two explain (2), two compare (4), two prioritize/justify (5). Answer the four higher ones closed-book first; only then touch notes.", "capture": "Your 6 questions + answers to the four level 4–5 items.", "minutes": 10}, "check": [{"q": "Audit your six questions: did any 'level 5' stems still only ask for definitions? What failure mode is that, and how would you fix one stem?", "rubric": "correct: Labels lied if stems lack judge/prioritize; rewrite to importance+why. mostly_correct: Some too easy vaguely. incorrect: Define is always evaluate.", "exemplar": "If a 'level 5' question was still 'define X,' the label lied — the stem didn't require judging. I'd rewrite to 'Which approach is better for Y, and why?' Evaluate demands defense, not definitions."}, {"q": "How did closed-book answers to your compare/prioritize items go, and what does that signal about readiness for serious assessment?", "rubric": "correct: Strong 4–5 answers ≈ closer to advanced exam demands; weak ≈ need more higher-order practice. mostly_correct: Mentions performance vaguely. incorrect: Success means stop; retreat to only level 1.", "exemplar": "Answering compare/prioritize well without notes signals higher-order practice landing — closer to what separates good from great on exams. Weak answers mean I need more level 4–5 reps, not a retreat to definitions only."}, {"q": "After you've written and attempted your own stems, what is an appropriate use of an AI helper — and what would be outsourcing the thinking?", "rubric": "correct: More level 2–5 variants after your attempt; not replace thinking/answers. mostly_correct: Use AI carefully vaguely. incorrect: Let AI do all thinking.", "exemplar": "After I've attempted my own stems, I can ask AI for more level 2–5 variants on my topic. Letting AI replace my answers outsources the thinking. My attempt first keeps the learning mine."}]}, {"focus": "Checkpoint: Top-Down & Levels", "review": "Checkpoint: classify thinking level, resist retreat, and start from evaluate on fresh material.", "task": {"do": "New topic: (1) write one level-1, one level-3, one level-5 question, (2) answer only the level-5 first with justification, (3) note one moment you wanted to retreat and what you did.", "capture": "Three questions; level-5 answer; retreat note.", "minutes": 10}, "check": [{"q": "If you answered level 1 first 'to warm up' and delayed evaluate, what top-down rule did you break — and what will you do differently?", "rubric": "correct: Bottom-up drift; start attention on evaluate. mostly_correct: Should start higher vaguely. incorrect: Level 1 first is ideal top-down.", "exemplar": "That's bottom-up drift — I avoided top-down. Next time I answer the level-5 question first with justification. Warming up with definitions-only isn't the method."}, {"q": "Evaluate your level-5 answer: does it rank/judge and defend? What would make it stronger?", "rubric": "correct: Prioritize + justify = evaluate; suggests sharper criteria if thin. mostly_correct: Mentions reasons vaguely. incorrect: Needs definition list to be valid.", "exemplar": "If I ranked approaches and defended one, that's strong evaluate evidence. To strengthen it I'd make the criterion explicit and contrast against the weaker option. A definition list isn't what makes it level 5."}, {"q": "A hard compare made you crave flashcards. What response resists retreat downward, and why is the difficulty expected?", "rubric": "correct: Stay with higher-order briefly; difficulty expected; deeper effort builds memory. mostly_correct: Persist vaguely. incorrect: Drop to recognition; difficulty proves failure.", "exemplar": "I'll stay with the higher-order task a bit longer — difficulty is expected when climbing. Immediately dropping to easy recognition is the trap. Deeper effort at 4–5 builds stronger memory."}]}]}, {"id": "pacer", "title": "The PACER Method", "order": 5, "lesson": "pacer.html", "days": [{"focus": "Consume vs Digest", "review": "Reading has consumption (intake) and digestion (processing so it stays). People obsess over consuming more, but learning depends on what remains. Up to ~90% of unread-digested material is forgotten. Sort your time: digest what you take in.", "task": {"do": "For yesterday's study on one subject, estimate minutes spent consuming (reading/watching/highlighting) vs digesting (organizing, practicing, mapping, rehearsing). Then adjust today's plan for one section toward more digestion.", "capture": "Consume vs digest estimate + today's digestion-heavy plan.", "minutes": 8}, "check": [{"q": "Using your consume vs digest time estimate, what risk does that ratio create for what will stay in memory?", "rubric": "correct: Heavy consume/light digest → most intake forgotten; cites estimate. mostly_correct: Need more digest vaguely. incorrect: Higher consume always maximizes retention.", "exemplar": "A 90/10 consume-to-digest split means most intake won't stay — over-consuming without digestion. Learning depends on what remains after processing. Highlighting and watching aren't digestion by themselves."}, {"q": "Explain today's digestion-heavy plan. Why does consuming less with more processing beat bingeing more pages?", "rubric": "correct: If no time to digest, consume less; learning = what stays. mostly_correct: Process more vaguely. incorrect: Faster playback; skip processing.", "exemplar": "I'll take fewer pages/videos and deliberately process what I take in. If I lack time to digest, I must consume less. Bingeing more undigested content maximizes forgetting, not learning."}, {"q": "For the material you chose, what digestion activity will you use — and why isn't another high-speed reread enough?", "rubric": "correct: Targeted processing (PACER-appropriate); reread ≠ digestion. mostly_correct: Mentions processing vaguely. incorrect: Highlight every sentence; another summary video only.", "exemplar": "I'll process it with a method matched to its type — practice, map, critique analogy, or store-and-rehearse — not another speed reread. Digestion is targeted processing. More raw intake isn't digestion."}]}, {"focus": "The Balance Rule", "review": "Everything you consume must be digested. No time to digest? Consume less. Over-consuming without digesting is like overeating — you 'vomit it back up' by forgetting. Practice saying no to excess intake.", "task": {"do": "Choose one upcoming reading/lecture block. Cut the planned consume volume by ~30–50%. Write exactly how you will digest what remains (method + minutes). Then start that shorter consume+digest loop on real material for 8 minutes.", "capture": "What you cut; digestion method; what you actually processed in the loop.", "minutes": 8}, "check": [{"q": "You may have resisted cutting volume because 'there's too much content.' What does the balance rule say you should do anyway — and why?", "rubric": "correct: Consume only what you can digest; unread beats forgotten. mostly_correct: Cut some vaguely. incorrect: Consume everything undigested to feel complete.", "exemplar": "I should still consume less than I can digest — unread pages beat forgotten pages. Coverage theater without digestion is like overeating. Balance means matched consume and digest, not infinite intake."}, {"q": "Did your shorter consume+digest loop leave you able to explain the chunk? What does that say about the balance rule?", "rubric": "correct: Less consume, more stay = balance working; cites result. mostly_correct: Felt better vaguely. incorrect: Failure if syllabus unfinished today.", "exemplar": "If I digested a smaller chunk and can explain it, balance is working — less consume, more stays. Not finishing the syllabus today isn't failure if what I took in remains. Learning tracks what stays."}, {"q": "What pattern in a study plan would signal you broke the balance rule?", "rubric": "correct: Large intake with almost no processing time. mostly_correct: Too much reading vaguely. incorrect: Matched blocks or stopping when digestion done as 'broken'.", "exemplar": "Large intake with almost no processing time attached breaks the balance rule — the overeating pattern. Matched consume/digest blocks follow the rule. Stopping when digestion is done is healthy, not a failure."}]}, {"focus": "P — Procedural", "review": "Procedural information is how to *do* something (techniques, coding, languages, protocols). Digest it by practice — apply it in real life as early as possible. Don't only reread the steps.", "task": {"do": "Find one procedural item in your coursework (a method, problem type, lab step, workflow). Practice doing it once now on a real or realistic example — not rereading the steps. Note where you stumbled.", "capture": "Procedural item; what you practiced; stumble notes.", "minutes": 10}, "check": [{"q": "Did you practice the procedural item or only highlight steps? What does PACER say procedural digestion requires?", "rubric": "correct: Practice/application as early as possible; highlighting ≠ doing. mostly_correct: Practice more vaguely. incorrect: Highlighting equals doing; only flashcards.", "exemplar": "If I only highlighted steps, that wasn't digestion. Procedural information is digested by practice — applying it in a realistic example early. Rereading steps alone won't install how-to skill."}, {"q": "Where you stumbled in practice, what is the best next move — and why not retreat to silent rereading only?", "rubric": "correct: Retry sooner using stumble as feedback. mostly_correct: Practice again vaguely. incorrect: Reread forever; stumbles prove practice fails.", "exemplar": "I'll retry the procedure sooner, using the stumble as feedback. Silent rereading forever avoids the digestion method for P. Early practice with corrections is the point."}, {"q": "Why was the item you chose Procedural rather than a definition or isolated statistic — and how did that label change what you did?", "rubric": "correct: How-to/process you must perform → practice; contrasts non-P. mostly_correct: It's a skill vaguely. incorrect: Treats trivia/definition as procedural.", "exemplar": "It's a how-to process I must perform, not a one-off statistic or pure definition. That PACER label meant I had to practice doing it, not only memorize wording. Wrong label would have sent me to the wrong digestion."}]}, {"focus": "A — Analogous", "review": "Analogous information relates to something you already know. Digest it by critiquing the analogy: where it holds, where it breaks, whether it can be improved. Don't just smile at a metaphor and move on.", "task": {"do": "Find an analogy in your notes/lecture/textbook (or invent one linking a new idea to something you know). Critique it in writing: holds / breaks / one improvement.", "capture": "Analogy; holds; breaks; improvement.", "minutes": 8}, "check": [{"q": "If your analogy note was basically 'nice analogy' with no critique, what digestion for Analogous information did you skip?", "rubric": "correct: Critique holds/breaks/improvements. mostly_correct: Think deeper vaguely. incorrect: Liking an analogy fully digests it.", "exemplar": "I skipped critiquing where it holds, where it breaks, and how to improve it. Analogous information is digested by testing the analogy, not smiling at a metaphor. 'Nice analogy' isn't digestion."}, {"q": "Your critique may have found a break. Why is spotting breaks useful for understanding the real idea?", "rubric": "correct: Limits deepen understanding of the target concept. mostly_correct: Critique helps vaguely. incorrect: Breaks mean delete all analogies forever.", "exemplar": "Spotting where the analogy breaks deepens understanding of the real idea — I see what the metaphor doesn't cover. Breaks aren't a reason to ban analogies. Critique including limits is the A digestion process."}, {"q": "After a weak analogy, what next step strengthens encoding of the target idea?", "rubric": "correct: Improve or replace with tighter analogy tied to prior knowledge. mostly_correct: Find a better analogy vaguely. incorrect: Ignore prior knowledge; treat every analogy as perfect.", "exemplar": "I'll improve it or replace it with a tighter analogy tied to something I already know. Knowing limits and building a better bridge strengthens encoding. Stopping all relating to prior knowledge blocks A digestion."}]}, {"focus": "C — Conceptual", "review": "Conceptual information is the *what*: facts, theories, relationships — most of science. Digest by mapping: non-linear, network-based notes (mind mapping), not endless linear lists alone.", "task": {"do": "Take one conceptual cluster from your subject. Draw a non-linear map (center + branches/links). Include at least 5 nodes and 3 explicit relationships. Use your real material.", "capture": "Describe center, nodes, and the key links (or photo description of the map).", "minutes": 10}, "check": [{"q": "Was your map a true network or mostly a linear list? What does conceptual digestion require instead of sequence-only notes?", "rubric": "correct: Non-linear network with relationships; lists ≠ maps for C. mostly_correct: Needs structure vaguely. incorrect: Lists identical to maps; relationships optional.", "exemplar": "A linear bullet list isn't a map. Conceptual digestion wants network structure — nodes and links showing how ideas relate — not only sequence. Theories need relationships, not isolated definition columns."}, {"q": "Which links on your map best show conceptual digestion, and what relationship do they capture?", "rubric": "correct: Visible relational links (cause, part-of, contrast, etc.). mostly_correct: Mentions links vaguely. incorrect: Page numbers or copied paragraph order as digestion.", "exemplar": "Links that show how ideas relate — cause, contrast, category — match conceptual digestion. Page numbers or copied paragraphs in order don't. Mapping emphasizes the conceptual network."}, {"q": "What follow-up would enrich today's map without turning everything into Reference flashcards?", "rubric": "correct: Add a helpful analogy inside the map; keep network. mostly_correct: Add more connections vaguely. incorrect: Delete links for flashcards-only; never revisit.", "exemplar": "I'd add an analogy inside the map where it helps a concept click — A living inside C. Converting the whole web to Reference trivia cards is the wrong move. Keep and grow the network."}]}, {"focus": "E — Evidence", "review": "Evidence is specific facts, stats, or cases that prove a concept. Digest by store & rehearse: note it now, later practice *using* it to support the concept — don't freeze consumption to memorize every number on the spot.", "task": {"do": "From your material, pick 2 evidence items (stat, finding, case). Store them briefly under the concept they support. Then rehearse: without looking, state the concept and use each evidence item in one supporting sentence.", "capture": "Concept; two evidence items; your two supporting sentences from memory.", "minutes": 8}, "check": [{"q": "Did you burn first-pass time force-memorizing a statistic? What does PACER warn about Evidence during consumption?", "rubric": "correct: Store now, rehearse later; don't force-memorize on the spot during consume. mostly_correct: Memorize later vaguely. incorrect: Must memorize evidence before noting the concept.", "exemplar": "PACER warns: don't force-memorize Evidence on the spot during consumption — store it under the concept and rehearse later. On-the-spot memorizing steals foundation time. Using evidence in supporting sentences is the rehearsal."}, {"q": "How did your rehearsal use each evidence item to support the concept — and why is that better than highlighting alone?", "rubric": "correct: Used evidence in supporting sentences from memory; rehearse-by-using. mostly_correct: Recalled the stat vaguely. incorrect: Evidence may only be highlighted.", "exemplar": "I stated the concept and used each evidence item in a supporting sentence without looking — store & rehearse by using it. Highlighting alone isn't rehearsal. Evidence exists to support concepts in use."}, {"q": "If an evidence item had no parent concept in your notes, what fix comes before more memorizing?", "rubric": "correct: Attach under the concept it proves. mostly_correct: Organize better vaguely. incorrect: Keep as lone flashcard forever; delete concepts.", "exemplar": "I'd attach it under the concept it proves before more memorizing. Lone number flashcards orphan the evidence. Evidence is stored in relationship to what it supports."}]}, {"focus": "R — Reference", "review": "Reference is nitty-gritty detail you mainly need to recall. Digest with store & rehearse (flashcards + spacing/active recall). It is the easiest, least important category — most real knowledge is P, A, and C. Don't treat everything as R.", "task": {"do": "Scan one section of your notes. Tag items as R only if they are detail-for-recall. Make at most 5 flashcards for true Reference. Explicitly list 3 items you will NOT flashcard because they are P/A/C instead.", "capture": "Up to 5 R cards (prompts only is fine) + 3 non-R items with their letter tags.", "minutes": 8}, "check": [{"q": "If you turned a conceptual framework into a huge flashcard pile, what PACER mistake is that — and what digestion should replace most of those cards?", "rubric": "correct: Treating Conceptual as Reference; map instead. mostly_correct: Too many cards vaguely. incorrect: Ideal PACER for theories.", "exemplar": "That's treating Conceptual material as Reference — the worst offender pattern. Frameworks should be mapped as networks, not dumped onto dozens of cards. Most real knowledge is P, A, and C — not R."}, {"q": "Why did today's task cap R cards and force non-R tags? What does that protect time for?", "rubric": "correct: R is least important; protect P/A/C digestion time. mostly_correct: Prioritize important stuff vaguely. incorrect: R is the only knowledge that matters; PACER forbids flashcards.", "exemplar": "Reference is the easiest, least important category — capping R protects time for Procedural, Analogous, and Conceptual digestion. Flashcards are fine for true R, not for everything. Non-R tags keep the foundation funded."}, {"q": "For one true Reference detail you tagged, what digestion plan matches R — and what should you avoid during first consumption?", "rubric": "correct: Store now; spaced active recall later; avoid endless on-the-spot rereading during consume. mostly_correct: Flashcard later vaguely. incorrect: Reread twenty times during first consume only.", "exemplar": "Store it now and rehearse later with spaced active recall. I should avoid endless rereading during first consumption. R isn't practiced as a physical procedure when it isn't one."}]}, {"focus": "Two Biggest Mistakes", "review": "Mistake 1: memorizing on the spot for P/E/R during consumption. Mistake 2: treating everything as Reference. Both steal time from the foundation (P, A, C). Audit your habits against both.", "task": {"do": "Review your last study session's artifacts (notes/cards). Find one example of on-the-spot memorizing that should have been store/practice-later, and one example of over-flashcarding something that needed mapping/practice/analogy critique. Rewrite the plan for each.", "capture": "Mistake examples + corrected digestion plans.", "minutes": 8}, "check": [{"q": "From your audit, explain one on-the-spot memorizing mistake and the corrected digestion plan. Which PACER mistake is that?", "rubric": "correct: Identifies consume-time memorizing of P/E/R; correct = practice later or store&rehearse. mostly_correct: Memorized too early vaguely. incorrect: Claims on-the-spot memorizing is correct PACER for P.", "exemplar": "I memorized protocol steps during first reading instead of practicing later — on-the-spot memorizing of Procedural info during consume. Corrected plan: light store, then practice reps. That mistake starves foundation time."}, {"q": "Explain one over-flashcarding example from your artifacts and what digestion it should have received instead.", "rubric": "correct: Conceptual/theory as R → map (or P→practice, A→critique). mostly_correct: Too many cards vaguely. incorrect: Flashcards perfect for theory webs.", "exemplar": "I flashcarded a whole theory web — treating Conceptual knowledge as Reference. It should have been mapped. Dumping everything onto cards is the second big mistake."}, {"q": "After today's audit, what priority will protect P/A/C foundations in your next session?", "rubric": "correct: Protect time for P/A/C; store E/R for later rehearsal; avoid both mistakes. mostly_correct: Focus on important material vaguely. incorrect: Memorize everything immediately while reading.", "exemplar": "I'll protect time for practice, analogy critique, and mapping — and store Evidence/Reference for later rehearsal. No memorizing everything while reading, and no converting all P into R cards. Foundations first."}]}, {"focus": "Full Application: PACER Sort", "review": "Forced sorting feels unnatural — and that's why it works. Biological limits make endless intake overwhelming; sorting + right digestion keeps you under the limit. Do a full PACER pass on real pages.", "task": {"do": "Take 4–6 pages or one lecture. Tag each major chunk P/A/C/E/R. Digestion sprint: practice one P, critique one A, map one C cluster, store two E/R for later. Stop when time ends even if pages remain.", "capture": "Tags summary + what you did for P, A, C, and stored E/R.", "minutes": 10}, "check": [{"q": "Sorting felt awkward but you finished targeted digestion on less volume. How does PACER interpret that awkwardness and result?", "rubric": "correct: Forced process expected; keeps under overwhelm limits; less volume OK. mostly_correct: Sorting helps vaguely. incorrect: Awkwardness means abandon PACER; binge leftovers undigested.", "exemplar": "Awkward forced sorting is expected — and that's why it works. It kept me under cognitive overwhelm by matching digestion to types. Finishing targeted processing on less volume beats consuming every remaining page undigested."}, {"q": "If almost everything got tagged R, what error pattern is that — and how would you retag two items?", "rubric": "correct: Overusing Reference; retag toward P/A/C with reasons. mostly_correct: Too much R vaguely. incorrect: R should dominate science courses.", "exemplar": "Overusing Reference misses P/A/C foundations. I'd retag a how-to as P and a theory cluster as C, then practice and map. Most important knowledge isn't nitty-gritty recall detail."}, {"q": "For leftover unread pages, what next move respects the balance rule?", "rubric": "correct: Another consume+digest cycle; no binge without processing. mostly_correct: Come back later vaguely. incorrect: Speed-read all leftovers; flashcard every sentence; ignore balance when busy.", "exemplar": "I'll schedule another consume+digest cycle — not speed-read leftovers with zero digestion. The balance rule still holds when busy. Flashcarding every sentence recreates the everything-is-R mistake."}]}, {"focus": "Checkpoint: Sort & Digest", "review": "Checkpoint: classify information types, pick correct digestion, and catch the two big mistakes on fresh material.", "task": {"do": "New section: tag 5 items with PACER letters; digest two non-R items properly; write one temptation you felt toward on-the-spot memorizing or over-flashcarding and what you did instead.", "capture": "Five tags; two digestions; temptation + alternative.", "minutes": 10}, "check": [{"q": "If you tagged a how-to skill as R and only made flashcards, what checkpoint error is that — and what digestion should replace it?", "rubric": "correct: Mis-tagged Procedural as Reference; needs practice. mostly_correct: Wrong tag vaguely. incorrect: All skills are Reference; cards replace doing.", "exemplar": "That's mis-tagging Procedural as Reference. Digestion should be practice, not cards alone. Flashcards don't replace doing a how-to skill."}, {"q": "You mapped a theory cluster instead of carding every node. Why is that the correct Conceptual move?", "rubric": "correct: C → network map; relationships over R dump. mostly_correct: Mapping good vaguely. incorrect: Theories must be R only.", "exemplar": "Conceptual information is digested by non-linear mapping — showing relationships in the network. Carding every node treats C as R. Maps aren't only for procedural steps."}, {"q": "You felt an urge to memorize every number on first reading. What PACER response protects foundation time?", "rubric": "correct: Store E/R now; rehearse later; keep consume for P/A/C. mostly_correct: Memorize later vaguely. incorrect: Memorize all numbers immediately; convert chapter to R first.", "exemplar": "I'll store Evidence/Reference now and rehearse later — keeping consume time for P/A/C foundations. Memorizing every number immediately is the on-the-spot mistake. Skipping tags to binge more pages breaks balance."}]}]}, {"id": "encoding", "title": "Encoding: Build the Big Picture", "order": 6, "lesson": "encoding.html", "days": [{"focus": "Encoding Flattens Forgetting", "review": "Encoding is how information goes in the first time — the highest-leverage learning skill. Encode well and the forgetting curve flattens; you may keep most of what you learned after a single strong pass. That reduces endless review.", "task": {"do": "Pick a topic you studied in the last week. Without re-reading first, rate what % you still have usable grasp of, and list what encoding moves you used originally (reread, map, relate, none). Plan one encoding upgrade for a new section today.", "capture": "Topic; rough retained %; past encoding moves; upgrade plan.", "minutes": 8}, "check": [{"q": "Given your retained-% estimate and the encoding moves you listed, what does low retention after reread-heavy study imply about encoding versus endless review?", "rubric": "correct: Weak first-pass encoding; review can't fully replace better encoding; cites their data. mostly_correct: Need better encoding vaguely. incorrect: Reread-only flattens forgetting best.", "exemplar": "Low retention after many reread-only hours means the intake process was weak. More review can't fully replace better first-pass encoding. Strong encoding flattens forgetting; weak encoding leaves me relearning."}, {"q": "Explain your encoding upgrade plan for a new section. Why does it target encoding (how ideas enter) rather than only last-minute retrieval?", "rubric": "correct: Build big-picture structure/connections on the way in. mostly_correct: Study better vaguely. incorrect: Only more cramming; skip organization on entry.", "exemplar": "I'll build a clearer big-picture structure as ideas enter — relate and organize on intake. That's encoding skill, the highest leverage. Last-minute cramming without better entry process keeps the forgetting curve steep."}, {"q": "Encoding practice can feel slower at first. Why still prioritize it over only practicing retrieval tricks?", "rubric": "correct: Encoding skill takes longer to build but flattens forgetting and eventually eases learning. mostly_correct: Worth it vaguely. incorrect: Encoding is instant; retrieval replaces all encoding.", "exemplar": "Encoding skills take weeks to months to build, longer than retrieval tricks, but they flatten forgetting so I keep more after a strong pass. Eventually learning feels easier. Retrieval alone doesn't replace organizing on the way in."}]}, {"focus": "Relate to the Big Picture", "review": "Unifying principle: for every new piece, ask what its purpose is and where it fits relative to everything else. The brain keeps what it judges relevant — and relevant means connected. 'It's on the exam' isn't enough.", "task": {"do": "Take 5 new or recent facts/ideas from your material. For each, write: purpose (why it exists in the topic) + fit (where it sits relative to the big picture). No orphan one-liners.", "capture": "Five items each with purpose + fit.", "minutes": 8}, "check": [{"q": "If any of your five items only said 'might be on the test' as purpose, why is that a weak relevance signal for the brain?", "rubric": "correct: Exam threat isn't a connection; relevance = how it fits the big picture. mostly_correct: Need better reasons vaguely. incorrect: Exam reminders fully encode any fact.", "exemplar": "Telling my brain it's on the exam isn't a real connection — it doesn't create relevance. Relevance means purpose and fit relative to the big picture. Without that, the piece stays orphaned even if high-stakes."}, {"q": "Pick your strongest purpose+fit line. What makes it strong encoding intent compared with a copied definition?", "rubric": "correct: Clear purpose + specific structural link. mostly_correct: Mentions connection vaguely. incorrect: Highlight color or 'important' with no reason.", "exemplar": "A clear purpose plus a specific link to the topic's structure is strong encoding intent. A copied definition with no fit is intake without relevance. 'Important' without a reason doesn't place the piece."}, {"q": "For an orphan item with no fit, what will you do next — and why isn't memorizing it harder in isolation the fix?", "rubric": "correct: Hold aside until it belongs in the structure; isolation memorizing fails relevance. mostly_correct: Find a place vaguely. incorrect: Memorize harder in isolation; abandon big picture.", "exemplar": "I'll hold it aside until I find where it belongs in the structure. Memorizing orphans harder still leaves them irrelevant to the brain. Encoding requires placing pieces relative to the whole."}]}, {"focus": "Simplify First (Scaffold)", "review": "At the moment of learning, simplify ideas until they slot into a simple big picture. Find the simplest concepts and build the simplest whole first — scaffolding. You're not ready for every detail yet; your brain would drop them anyway.", "task": {"do": "Open a dense section. Write the simplest 4–7 idea skeleton that captures the whole — no rare details. Park details in a separate 'later' list. Stop when the skeleton is sayable in under a minute.", "capture": "Simple skeleton + parked details list.", "minutes": 8}, "check": [{"q": "Is your skeleton simple enough, or packed with exceptions? What does simplify-first scaffolding require at the moment of learning?", "rubric": "correct: Simplest whole first; park details; not every exception yet. mostly_correct: Keep it simple vaguely. incorrect: More detail always improves first-pass encoding.", "exemplar": "If the skeleton is packed with exceptions, I skipped simplify-first. Scaffolding means the simplest 4–7 ideas that capture the whole, details parked for later. The brain drops excess detail before a stable picture exists."}, {"q": "Can you say the skeleton in under a minute? What does that (or failure) tell you about whether a simple big picture is forming?", "rubric": "correct: Sayable skeleton = simple big picture forming; unspeakable dump = not simplified. mostly_correct: Mentions clarity vaguely. incorrect: Simple can't be academic; only full detail dumps encode.", "exemplar": "If I can say it in ~45 seconds, a simple big picture is forming. An unspeakable detail dump means I haven't simplified. Simplifying until the whole is graspable is the point of scaffolding."}, {"q": "How should you use the parked details list across the next sessions — and what order mistake would undo the scaffold?", "rubric": "correct: Add later in layers once skeleton holds; don't memorize parked list first. mostly_correct: Add later vaguely. incorrect: Memorize parked list before any skeleton; throw away skeleton.", "exemplar": "I'll add parked details later in layers once the skeleton holds. Memorizing the parked list before any skeleton undoes scaffolding. Mixing all details back in unordered recreates overwhelm."}]}, {"focus": "Learn in Layers", "review": "Once the simple skeleton is stable, add one layer of detail, fit it to the big picture, then another. In the study demo, early pages were slow; later pages accelerated because new detail snapped onto a framework.", "task": {"do": "Using yesterday's or today's skeleton for a real topic, add exactly one detail layer (a handful of specifics). For each add-on, write how it attaches to the skeleton. Do not add a second layer yet.", "capture": "Skeleton reminder; layer-1 details + attachment notes.", "minutes": 8}, "check": [{"q": "Do your layer-1 details attach to skeleton nodes? If some don't, what does that say about layered learning?", "rubric": "correct: Unattached details = layering failed; each add-on must fit the big picture. mostly_correct: Need connections vaguely. incorrect: Unattached details encode best.", "exemplar": "Details that don't attach to any skeleton node mean layering failed — I'm collecting orphans again. Each layer must fit the big picture. Unattached specifics aren't a successful layer."}, {"q": "Why did today's task allow only one detail layer before another — what stabilizes between layers?", "rubric": "correct: Stabilize fit before piling more detail. mostly_correct: Don't rush vaguely. incorrect: Only one fact exists; dump all detail at once for speed.", "exemplar": "I add one layer, see how it fits, then add another — layered learning. Stabilizing fit prevents an unsorted pile. Dumping all detail at once recreates the pre-scaffold mess."}, {"q": "If adding detail started to feel faster mid-topic, what likely cause matches the encoding demo pattern?", "rubric": "correct: Structure stabilizing — new detail snaps on quicker. mostly_correct: Getting used to it vaguely. incorrect: Speed means abandon skeleton.", "exemplar": "Structure is stabilizing — new detail attaches quicker once the framework holds. That's the demo pattern: early pages slow, later pages accelerate. Speeding up isn't a reason to abandon the skeleton."}]}, {"focus": "Organize on the Way In", "review": "Organize as knowledge arrives — like tidying a room as you go. Dumping everything to reorganize later (or never) is much harder. Practice placing each new idea correctly on entry.", "task": {"do": "Study a short new chunk. Rule: every new idea must be placed onto your map/skeleton before you take the next one. No 'inbox dump' list. If placement is unclear, pause and simplify.", "capture": "Chunk studied; placement decisions; any pause-to-simplify moments.", "minutes": 10}, "check": [{"q": "Did you dump ideas to 'organize tonight,' or place each on entry? How does that choice match organize-on-the-way-in?", "rubric": "correct: Place as knowledge arrives; dumping for later conflicts. mostly_correct: Organize sooner vaguely. incorrect: Dumping first is recommended encoding.", "exemplar": "A long unsorted capture to organize tonight conflicts with organizing on the way in. It's far easier to place knowledge correctly as it arrives than to dump and reorganize later. Tonight-organization rarely equals on-entry placement."}, {"q": "You may have paused when an idea wouldn't place. Why is that a good instinct for encoding?", "rubric": "correct: Unclear placement → simplify/organize before adding more. mostly_correct: Slow down vaguely. incorrect: Never pause; speed-read past confusion.", "exemplar": "Pausing when placement is unclear is right — unclear means simplify or fix structure before adding more. Speed-reading past confusion keeps dumping orphans. If it doesn't fit, fix the structure."}, {"q": "What evidence in your capture shows you organized on entry rather than promising to sort later?", "rubric": "correct: Each idea has a decided place now. mostly_correct: Somewhat organized vaguely. incorrect: Messy inbox or vow to reorganize on break week.", "exemplar": "Each idea having a decided place in the structure now is evidence of on-entry organization. A messy inbox or a vow to reorganize during break week is a dump. Highlights with no placement aren't organized."}]}, {"focus": "Iteration: Guess, Test, Refine", "review": "Don't study for weeks then test once. Effective learning loops hypothesis → feedback → refine. As each piece arrives, guess how it connects, then check. Wrong guesses early are cheap; wrong assumptions carried for weeks are expensive. Lightbulb moments are confirmed hypotheses.", "task": {"do": "For 3 incoming ideas in your material: before checking the source's framing, write a quick hypothesis of how each connects. Then check and mark confirm / adjust / reject. Refine one connection that was wrong.", "capture": "Three hypotheses; outcomes; one refinement.", "minutes": 8}, "check": [{"q": "Some hypotheses may have been wrong but caught quickly. What does that teach about iteration and the cost of early errors?", "rubric": "correct: Early wrong guesses are cheap; loop is the point. mostly_correct: Mistakes OK vaguely. incorrect: Wrong guesses mean stop hypothesizing.", "exemplar": "Wrong hypotheses caught in minutes show early errors are cheap — iteration working. The loop is guess → check → refine. Waiting weeks to test makes wrong assumptions expensive."}, {"q": "If you avoided guessing to 'not be wrong,' what cost does that create for encoding?", "rubric": "correct: Delays feedback; may carry silent wrong assumptions longer. mostly_correct: Less learning vaguely. incorrect: Avoiding hypotheses maximizes insight.", "exemplar": "Avoiding guesses delays feedback and may let silent wrong assumptions ride for weeks. Iteration needs testable hypotheses. Being wrong once in a micro-loop doesn't ruin encoding — hiding from error does."}, {"q": "After a rejected hypothesis, what micro-loop will you run next?", "rubric": "correct: Revised connection → re-check quickly. mostly_correct: Try again vaguely. incorrect: Wait weeks; memorize wrong version; stop relating.", "exemplar": "I'll write a revised connection and re-check quickly — hypothesis → feedback → refine. Waiting weeks before any test loses the iteration effect. Memorizing the wrong version harder makes it worse."}]}, {"focus": "Micro-Retrieval: Test to the Max", "review": "Practical iteration: right after learning a chunk, look away and try to reproduce or use it immediately. If you can't, encoding (or struggle level) needs work — and you just got instant feedback. Test to the max in tiny loops.", "task": {"do": "Learn one small chunk from your material (3–5 minutes). Close it. Reproduce the structure/use from memory for 2 minutes. Open, note gaps, fix encoding (relink/simplify), then micro-retrieve once more.", "capture": "First reproduction; gaps; fix; second reproduction result.", "minutes": 10}, "check": [{"q": "Your first micro-retrieval may have failed. How should you interpret that signal for encoding quality right now?", "rubric": "correct: Useful feedback — encoding or struggle needs work now; cheap to fix. mostly_correct: Need to restudy vaguely. incorrect: Never retrieve early; only end-of-month tests matter.", "exemplar": "A bad first reproduction is useful signal — encoding or struggle needs work now, while fixes are cheap. It doesn't mean abandon the topic or wait for a monthly test. Immediate failure is feedback on how ideas went in."}, {"q": "After you fixed links and tried again, what did the second retrieval tell you about the iteration loop?", "rubric": "correct: Improvement confirms fix; hypothesis/fix/refine in action. mostly_correct: Got better vaguely. incorrect: Skip second retrieval; retrieval harms encoding.", "exemplar": "If the second retrieval improved after relinking/simplifying, the iteration loop worked — form, refine, test again. Micro-retrieval confirms whether encoding improved. Skipping the second try leaves the fix unverified."}, {"q": "What micro-retrieval prompt will you use right after the next chunk — and why not reread and assume mastery?", "rubric": "correct: Look away and rebuild/use without peeking. mostly_correct: Self-test vaguely. incorrect: Reread once; highlight; watch summary instead of producing.", "exemplar": "I'll look away and rebuild or use the chunk without peeking — test to the max. Rereading and assuming mastery skips the feedback. Producing immediately after learning is the practical iteration move."}]}, {"focus": "Embrace the Confusion", "review": "First laying out a big topic feels overwhelming. That discomfort is cognitive load doing its job — confusion as fuel. Work through it by simplifying and organizing, not by writing more undigested notes.", "task": {"do": "Choose a topic that currently feels confusing. For 8 minutes, only simplify and organize (skeleton + placements). Ban adding new copied notes. End by rating confusion 1–10 before vs after.", "capture": "Before/after confusion ratings; simplified structure; what you refused to copy.", "minutes": 8}, "check": [{"q": "When confusion was high, did you start copying more paragraphs? How does that conflict with using confusion as fuel?", "rubric": "correct: Fix is simplify/organize, not write more undigested notes. mostly_correct: Organize instead vaguely. incorrect: More copying is the cure; stop structuring.", "exemplar": "Copying more paragraphs conflicts with the lesson — writing more isn't the fix. Confusion is cognitive load to channel by simplifying and organizing. Overwhelm doesn't prove encoding is impossible."}, {"q": "If your confusion rating dropped after scaffolding, how do you read that change?", "rubric": "correct: Load channeled into useful structure. mostly_correct: Felt clearer vaguely. incorrect: Drop means cheated; confusion should never decrease.", "exemplar": "A drop after scaffolding means cognitive load was channeled into useful structure. Confusion as fuel worked. The rating change tracks encoding progress when the response is simplify/organize."}, {"q": "A new map looks messy at first. What mindset keeps you encoding instead of quitting or dumping more detail?", "rubric": "correct: Expected; stay with simplify/organize until stable. mostly_correct: Keep going vaguely. incorrect: Quit higher-order encoding; dump more detail to hide mess.", "exemplar": "Messy first layouts are expected — I'll stay with simplify/organize until it stabilizes. Quitting or dumping more undigested detail hides the mess without encoding. Overwhelm at first big-picture work is normal."}]}, {"focus": "Full Application: Big-Picture Pass", "review": "Encoding is mostly how you think, not which fancy tool you use. Pull it together on one real topic: relate, simplify, layer once, organize on entry, micro-retrieve.", "task": {"do": "One topic, ~10 minutes: build a simple big picture, place 5–8 ideas with purpose/fit, add one detail layer, then closed-book reproduce the skeleton. No passive-only reread.", "capture": "Big picture; placements; layer-1 adds; reproduction result.", "minutes": 10}, "check": [{"q": "Beautiful notes with a failed closed-book skeleton — what does that say about tools/output versus encoding?", "rubric": "correct: Pretty output ≠ encoding; reproduction still weak. mostly_correct: Need recall vaguely. incorrect: Pretty notes guarantee flattened forgetting.", "exemplar": "Failed skeleton recall means tool/output isn't encoding — the thinking and reproduction are still weak. You can encode well from a plain book by relating and simplifying. Pretty notes don't flatten forgetting by themselves."}, {"q": "Which part of your capture best shows real encoding rather than busywork — and why?", "rubric": "correct: Purpose/fit placements + successful skeleton retrieval. mostly_correct: Mentions structure vaguely. incorrect: Word count, colors, or hours without recall.", "exemplar": "Purpose/fit placements plus a successful skeleton retrieval show encoding. Word count, pastel colors, or hours without checking recall are busywork. Connected placement plus immediate reproduce is the loop."}, {"q": "If layer-1 details wouldn't attach, what will you do before forcing more detail — and why not isolate them on flashcards only?", "rubric": "correct: Simplify skeleton until attachments clear; then retry. mostly_correct: Fix structure vaguely. incorrect: Force isolated flashcards; abandon big picture.", "exemplar": "I'll simplify the skeleton until attachments are clear, then retry the layer. Forcing unattached details onto isolated flashcards abandons the big picture. Unattached detail means the scaffold needs work first."}]}, {"focus": "Checkpoint: Encode Under Pressure", "review": "Checkpoint: big-picture fit, simplify-first, on-entry organization, and micro-retrieval — fresh scenarios on your own material.", "task": {"do": "New dense page/section: (1) 60-second simplified skeleton, (2) place 4 ideas with fit, (3) one hypothesis-check on a connection, (4) immediate closed-book reproduce.", "capture": "Skeleton; four fits; hypothesis outcome; reproduce result.", "minutes": 10}, "check": [{"q": "If you jumped to memorizing details before any skeleton, what encoding rule did you violate — and what order will you use instead?", "rubric": "correct: Violates simplify-first; simplest whole then layers. mostly_correct: Big picture first vaguely. incorrect: Details always precede big picture.", "exemplar": "That violates simplify-first scaffolding. I'll build a 60-second simple skeleton first, then place ideas, then layer details. Details before relevance recreates orphans."}, {"q": "Walk through your hypothesis outcome and reproduce result. How does that pattern show healthy (or unhealthy) iteration?", "rubric": "correct: Wrong→caught→refine→improved reproduce = healthy cheap error loop. mostly_correct: Learned from mistake vaguely. incorrect: Wrong hypotheses forbid further encoding; wait weeks to reproduce.", "exemplar": "Hypothesis wrong, caught same session, then reproduce improved — healthy iteration: cheap error, fast refine, test again. Only perfect first guesses aren't required. Waiting weeks to reproduce makes errors expensive."}, {"q": "Fresh overwhelm mid-map: what response treats confusion as fuel, and what responses make encoding worse?", "rubric": "correct: Simplify/organize; don't copy more, only highlight, or quit structuring. mostly_correct: Calm down by organizing vaguely. incorrect: Longer undigested notes until calm.", "exemplar": "I'll simplify and organize — confusion as fuel. Adding longer undigested notes, only highlighting, or quitting structure makes encoding worse. Hard subjects still need big-picture placement."}]}]}, {"id": "notes-on-paper", "title": "Thinking on Paper", "order": 7, "lesson": "notes-on-paper.html", "days": [{"focus": "Notes as a thinking tool", "review": "Good notes do two jobs: document information, and — more importantly — *facilitate the right thinking*. Your brain has limited capacity; notes should *offload* the busywork of holding everything in your head so that freed capacity goes to deep, higher-order work. Test every habit with one question: does this help my brain think, or help it avoid thinking?", "task": {"do": "Open one page of notes from a recent lecture or reading. For each chunk, mark T (it made you group, connect, or judge) or A (you mostly transcribed or copied). Count both marks — about 8 minutes.", "capture": "Paste your T/A counts and one example of each mark from your own notes.", "minutes": 8}, "check": [{"q": "Looking at your T/A counts from today's page, what do they tell you about whether those notes helped you think or helped you avoid thinking? Use your own examples.", "rubric": "correct: Interprets T as thinking (group/connect/judge) and A as passive transcription; links their counts to whether the page facilitated learning. mostly_correct: Names T vs A meaning but weak link to their actual page. incorrect: Treats volume/neatness as proof of learning, or cannot distinguish T from A.", "exemplar": "Most of my marks were A — I copied slide sentences. That means the page mostly helped me avoid thinking. The one T chunk was where I grouped causes under one heading, which is the kind of work notes should force more often."}, {"q": "Pick one chunk you marked A. In your own words, what is the strongest next move to turn it into thinking work — and why is polishing or adding more transcription a weaker move?", "rubric": "correct: Proposes regrouping into keywords/relationships/judgments; rejects prettier rewrite or denser dump as still passive. mostly_correct: Suggests some active rewrite but vague on why polish/dump fails. incorrect: Recommends more copying, neatness-only, or deleting all notes.", "exemplar": "I would rebuild that A chunk as keywords with arrows between ideas so I have to choose groups and links. Rewriting it neatly or adding more sentences still skips the thinking the lesson wants."}, {"q": "You may have felt productive while writing the A-heavy parts. What does that feeling usually mean, given what you just marked?", "rubric": "correct: Explains that visible effort/volume can mask little deep processing; ties to their A marks. mostly_correct: Mentions false productivity but not tied to their audit. incorrect: Equates filled pages with encoding success.", "exemplar": "Feeling productive while filling pages was misleading — my A marks show I was transcribing, not grouping or judging. Passive note mountains can feel like work while learning is skipped."}]}, {"focus": "Failure mode: no notes", "review": "Taking *no notes at all* burns capacity just holding information in your head, leaving little room to think. When material is dense, you need somewhere to park the puzzle pieces so working memory can compare, group, and connect them. Offloading is not optional busywork — it is what frees capacity for higher-order thinking.", "task": {"do": "Pick a dense paragraph from your current subject (textbook, slides, or handout). First try to hold it in mind only and list the relationships you notice. Then put keywords on paper/canvas and list relationships again. Compare — about 8 minutes.", "capture": "Write what you could notice with memory alone vs with keywords on the page (2–4 bullets each).", "minutes": 8}, "check": [{"q": "Compare your memory-only list with your keywords-on-page list. What does the difference show about why notes matter for thinking?", "rubric": "correct: States offloading frees capacity so more groups/links appear; cites their comparison. mostly_correct: Says notes help but vague on capacity/offloading. incorrect: Claims memory-only is always deeper, or that only full sentences help.", "exemplar": "With keywords on the page I spotted more links because I was not using capacity just to hold the pieces. Memory-only stayed thin — that is why offloading matters for higher-order work."}, {"q": "If your memory-only relationship list was thin, what does that diagnose about working memory during dense study?", "rubric": "correct: Diagnoses overload from holding pieces, leaving little room to think/compare. mostly_correct: Says it was hard without naming capacity overload. incorrect: Blames neatness, flashcards-only, or topic easiness.", "exemplar": "A thin memory-only list means working memory was busy holding details, so little capacity remained to compare and connect them — the no-notes failure mode."}, {"q": "What in today's capture is the strongest evidence you used notes as a thinking tool rather than as a transcript?", "rubric": "correct: Points to new groupings/arrows/relationships that appeared after offloading. mostly_correct: Mentions keywords but not new thinking. incorrect: Cites verbatim copy, word count, or a photo of the source.", "exemplar": "The strongest evidence is the new groupings and arrows I only saw after parking keywords on the page — not a longer transcript of the paragraph."}]}, {"focus": "Failure mode: passive volume", "review": "Too many notes written *passively* is even worse than none. Transcription lets the brain do none of the lifting, bypasses learning in the moment, and creates a mountain to re-process later. Volume feels productive; it is not evidence of learning. Cut the dump and force selection.", "task": {"do": "Take one dense section of your own notes (or a lecture dump). Cut it to at most one-third the length using only keywords — no full sentences. Cross out anything that is pure transcription without a role in a group or link — about 8 minutes.", "capture": "Paste before/after word counts (or line counts) and list 3 things you cut and why.", "minutes": 8}, "check": [{"q": "You just cut a dump to keywords. What was the real win in that process — not the shorter page itself, but what your brain had to do?", "rubric": "correct: Names forced selection/summarizing/meaning-making that passive transcription skips. mostly_correct: Says shorter is better without naming selection as thinking. incorrect: Treats keeping every sentence or making a longer dump as the win.", "exemplar": "The win was having to choose what mattered and compress it into keywords. That selection is the thinking passive transcription skips — not merely having fewer lines on the page."}, {"q": "A classmate keeps twelve pages per lecture and feels ahead. Using what you learned by cutting your own dump, how should you interpret that volume?", "rubric": "correct: Frames high passive volume as likely future re-processing debt / bypassed learning. mostly_correct: Skeptical of volume but vague why. incorrect: Treats more pages as more learning or urges matching page count.", "exemplar": "That volume is likely a re-processing mountain if it was mostly transcription. After cutting my own dump, I see page count is not proof of learning — passive notes skip thinking now and create work later."}, {"q": "Look at the three cuts you listed. Which cut best matches the lesson's standard, and which kind of cut would have been a mistake?", "rubric": "correct: Values cutting copied sentences with no grouping/judgment role; would not cut useful keywords/arrows/labels that carry relationships. mostly_correct: Discusses cuts but unclear on keep vs cut criteria. incorrect: Celebrates cutting relationship structure or keeping pure dumps.", "exemplar": "Cutting a copied sentence that added no group or link matched the standard. Cutting an arrow or keyword that held a key relationship would have been a mistake."}]}, {"focus": "Make it wrong", "review": "When new information overwhelms you, put puzzle pieces on the page and *guess* connections — it does not have to be right. Perfectionism causes paralysis. Guessing primes your brain so real learning lands faster. \"If what you write is right, you're doing it wrong.\" Speed and hypotheses beat waiting for perfect notes.", "task": {"do": "Open material you have not fully mastered yet. In 5 minutes, jot keywords and draw guessed groups/arrows on a blank page or canvas — deliberately allow wrong connections. Do not check the source until the timer ends — about 8 minutes total including a quick check.", "capture": "List 3 guessed connections you made, then mark each Correct / Partly / Wrong after checking.", "minutes": 8}, "check": [{"q": "Describe the attempt you just made. Why was a fast keyword map with imperfect guesses stronger than waiting until you were sure or copying the textbook structure?", "rubric": "correct: Explains make-it-wrong primes learning; perfectionism/paralysis and copy-perfect structures avoid the hypothesis work. mostly_correct: Prefers guessing but thin on why. incorrect: Argues only correct-first notes are valid.", "exemplar": "My fast map with several wrong guesses was the right move because hypotheses prime learning. Waiting for certainty or copying the book avoids the thinking and recreates paralysis."}, {"q": "Some of your guesses were Wrong or Partly. What should you do with those guesses now, and what would wasting them look like?", "rubric": "correct: Treat wrong guesses as data to revise groups/arrows; wasting = erase all / never guess again / freeze wrong forever. mostly_correct: Says revise but vague. incorrect: Says erase everything or avoid guessing to stay perfect.", "exemplar": "I should revise the wrong arrows now that I checked — they were useful data. Erasing the whole map or refusing to guess next time would waste the priming effect."}, {"q": "If you felt uneasy writing uncertain arrows, what was that discomfort signaling in this method — and what should you do with it?", "rubric": "correct: Names perfectionism/paralysis pressure; push through with a fast draft rather than stop. mostly_correct: Notes discomfort without linking to perfectionism. incorrect: Treats unease as proof to stop or switch to full-sentence outlines only.", "exemplar": "The unease was perfectionism pushing me to wait. In this method I should push through a fast imperfect draft — discomfort is part of priming, not a stop signal."}]}, {"focus": "Make it shorter", "review": "No full sentences — get as close to single keywords as possible, and do not make it pretty. Higher word count links to lower retention: compressing into a keyword takes more thinking than copying a sentence, and fewer words make patterns easier to see. Short, ugly, and thoughtful beats long, neat, and empty.", "task": {"do": "Take one concept from your notes that is written in sentences. Rebuild it as a non-linear keyword map (handwritten or stylus if you can). Cap yourself at roughly one keyword per idea — no polishing — about 8 minutes.", "capture": "Paste the original sentence count vs keyword count, and name one pattern that became easier to see when shorter.", "minutes": 8}, "check": [{"q": "You compressed sentences into keywords. Which change in that rebuild most improves encoding, and why?", "rubric": "correct: Credits forcing each idea into a keyword/summary as the thinking; rejects adding prose/keeping all sentences/prettifying first. mostly_correct: Prefers shorter notes without naming compression-as-thinking. incorrect: Values polish or leftover full sentences over compression.", "exemplar": "Forcing each idea into a single keyword improved encoding because summarizing is the thinking. Keeping the old sentences under the map or polishing prose would undo make-it-shorter."}, {"q": "Name the pattern that became easier to see on your shorter map. What does that illustrate about word count and relationships?", "rubric": "correct: Ties a real newly visible grouping/link to fewer words making relationships easier to spot. mostly_correct: Mentions a pattern but weak link to brevity. incorrect: Argues longer notes always reveal more or that patterns need full sentences.", "exemplar": "I suddenly saw a cause/effect cluster I missed in the prose. Fewer words made the relationships easier to spot — that is why shorter maps help."}, {"q": "Which version of your capture best matches \"make it shorter,\" and what would a fake win look like?", "rubric": "correct: Ugly/shorter keyword map is the win; fake wins = polished same-length paragraph, highlights-only, photo of textbook. mostly_correct: Prefers shorter but unclear on fake wins. incorrect: Celebrates polish or transcript volume.", "exemplar": "My uglier keyword map with a much lower count matches make-it-shorter. A polished paragraph with the same word count or a highlighted transcript would be a fake win."}]}, {"focus": "Make it again", "review": "Most of the power is in reorganization. As you learn more, the map gets messy and early guesses go wrong — so regroup, rearrange, and reconnect. Cleaning the map up *even with no new information* strengthens memory. Iteration is not busywork; it is the encoding.", "task": {"do": "Take an existing map or notes page for one topic you already studied. Without adding new source material, redraw or rearrange it: new groups, new arrow directions, clearer layout — about 8 minutes.", "capture": "Describe 2–3 changes you made (what moved, what connected differently) and why.", "minutes": 8}, "check": [{"q": "You reorganized with no new input. In your own words, why is that still valuable encoding work?", "rubric": "correct: States reorganization/reconnecting itself strengthens memory even without new facts. mostly_correct: Says redrawing helps but vague mechanism. incorrect: Calls no-new-info redraws wasted time or says maps must never change.", "exemplar": "Cleaning and reconnecting without new material still strengthens the memory — make-it-again says much of the power is in reorganization itself, not only in adding facts."}, {"q": "Looking at the changes you captured, which one was highest-value and why? Contrast it with a cosmetic change that would not count.", "rubric": "correct: Prioritizes structural regrouping/fixing wrong guesses; contrasts with neatness-only or decorative copies. mostly_correct: Names a change but weak contrast. incorrect: Treats handwriting polish as the main win.", "exemplar": "Regrouping to fix an early wrong cluster was highest-value. Neater handwriting with the same structure would have been cosmetic, not encoding."}, {"q": "Your first map may have felt \"done.\" After redrawing, what stance should you take toward maps going forward?", "rubric": "correct: Treats maps as living drafts revised as understanding grows. mostly_correct: Accepts some revision but still wants to lock early. incorrect: Freeze first draft, wait for teacher master map only, or abandon maps for sentence outlines.", "exemplar": "I should treat maps as living drafts I revise as understanding grows. Locking the first version would block the strongest principle — make it again."}]}, {"focus": "Decide the relationships", "review": "Knowledge is not linear, so linear notes struggle to show groups and relationships. Non-linear maps work *only if you* decide the links — auto-generated connections are too passive, and showing every link is overwhelming. The thinking is choosing whether to draw an arrow, how thick, which direction, and where ideas sit.", "task": {"do": "On a blank canvas/page, place 6–10 keywords from one of your topics. Draw only the relationships *you* judge matter (max ~8 arrows). Label 2 arrows with why that link matters — about 8 minutes.", "capture": "List the arrows you drew (from → to) and one link you *chose not* to draw, with a one-line reason.", "minutes": 8}, "check": [{"q": "You limited your arrows on purpose. Why is deciding which relationships matter better than linking everything or letting an app auto-connect?", "rubric": "correct: Judgment about links is the thinking; all-links/auto-links are overwhelming/passive. mostly_correct: Prefers fewer links without clear why. incorrect: Wants every possible link or full auto-generation.", "exemplar": "Choosing which arrows matter is the thinking. Showing every connection or accepting auto-links is passive and overwhelming — the map only works if I decide."}, {"q": "Using your capture, what proves you used non-linear notes actively rather than passively?", "rubric": "correct: Cites spatial keywords + chosen arrows + a deliberately rejected link. mostly_correct: Mentions a map but not selective linking. incorrect: Linear outline, copied bullets, or unedited auto-graph.", "exemplar": "I placed keywords in space, drew only chosen arrows, and rejected one link with a reason. That selective linking is active non-linear work — not a slide bullet list."}, {"q": "If you hesitated on arrow direction between two ideas, what should you do — and why is avoiding the choice a weaker move?", "rubric": "correct: Pick a directional hypothesis then revise after a check; avoiding choice skips relationship practice. mostly_correct: Says decide somehow but vague. incorrect: Skip both ideas, always draw both ways, or retreat to linear notes to avoid choosing.", "exemplar": "I should pick a direction as a hypothesis and revise after a quick check. Skipping the ideas or switching to linear notes avoids the relationship decision the map is for."}]}, {"focus": "Intuitive and logical groups", "review": "Groupings must be both *logical* (they fit the subject) and *intuitive* (obvious enough that you do not burn effort memorizing the scheme). \"Cause vs effect\" or \"before vs after\" help; arbitrary schemes you must memorize do not. Exam traps often exploit groups that felt intuitive but were not truly logical.", "task": {"do": "Take one topic map from your materials. Rewrite the groups two ways: (1) the most intuitive split you can think of, (2) a split you can defend as logically accurate to the subject. Note where they disagree — about 8 minutes.", "capture": "Name both groupings and one place where intuitive ≠ logical, plus which you will keep for study.", "minutes": 8}, "check": [{"q": "Where did your intuitive grouping disagree with the logical one? What exam risk does that disagreement highlight?", "rubric": "correct: Uses their disagreement; explains intuitive-but-illogical groups feel easy yet fail on tricky questions. mostly_correct: Notes disagreement without exam-trap risk. incorrect: Says intuition alone is enough or to avoid logical groups.", "exemplar": "My intuitive split lumped two mechanisms that are logically distinct. That feels easy to remember but is exactly the kind of false group exams exploit."}, {"q": "Which grouping will you keep for study, and what dual standard should a good scheme meet?", "rubric": "correct: Chooses a scheme that is logical for the subject and still easy to hold; rejects arbitrary memorize-only schemes. mostly_correct: Picks one grouping without stating both criteria. incorrect: Prefers random color codes, unexamined slide order, or alphabet-only.", "exemplar": "I will keep the logical split that I can still hold intuitively. Good groups must fit the subject and stay easy to use — not an arbitrary color code I have to memorize."}, {"q": "Before locking your chosen grouping, what check should you run — and why does visual balance or matching a classmate's colors fail that check?", "rubric": "correct: Stress-tests against hard exam questions that could exploit a false intuitive split. mostly_correct: Mentions some review but not exam stress-test. incorrect: Relies on looks, classmate colors, or long labels.", "exemplar": "I should ask whether a hard exam question could break this split. Looking balanced or matching someone's colors does not test whether the group is truly logical."}]}, {"focus": "Full map: wrong, short, again", "review": "Today combine the three principles on real material: make a fast wrong draft, compress to keywords, then reorganize once. Prefer freehand on an infinite canvas when you can — slower writing forces less text and more thought. The goal is a living map that offloads busywork and forces relationship thinking.", "task": {"do": "Choose one upcoming exam topic from your own course. Spend ~3 minutes on a messy keyword draft (make it wrong), ~3 minutes cutting to essentials (make it shorter), ~3 minutes redrawing groups/arrows (make it again).", "capture": "Paste a brief before→after description (or keyword list) and note which principle changed your map most.", "minutes": 9}, "check": [{"q": "Walk through the sequence you just ran. How does it match make-it-wrong → shorter → again, and how does that differ from perfect-outline-first or transcript-and-highlight?", "rubric": "correct: Describes fast imperfect draft, compress, reorganize; contrasts with perfect-first freeze or passive dump/highlight. mostly_correct: Names principles but weak contrast. incorrect: Describes perfect-first or reread-only as the method.", "exemplar": "I drafted messy guesses, cut to keywords, then redraw groups. That is wrong → shorter → again — not a perfect outline frozen forever, and not a transcript with highlights."}, {"q": "If your final map still has uncertain arrows, what is the best next move — and what would abandoning or \"perfecting by copying the chapter structure\" get wrong?", "rubric": "correct: Keep as hypotheses and revise after next exposure; abandoning/copying chapter to hide uncertainty blocks living-map practice. mostly_correct: Says revise later without contrasting bad moves. incorrect: Delete until perfect or replace arrows with paragraphs only.", "exemplar": "I should keep uncertain arrows as hypotheses and revise after the next exposure. Deleting the map until perfect or copying the chapter to hide uncertainty abandons the living-map approach."}, {"q": "Using today's session, how do you know you avoided both failure modes (no offloading, and passive volume)?", "rubric": "correct: Cites offloaded keywords plus forced grouping/linking rather than no notes or a passive dump. mostly_correct: Mentions one failure mode only. incorrect: Cites more pages, avoiding paper, or rereading-only as success.", "exemplar": "I parked keywords on the page and forced groups and links instead of holding everything in my head or making a passive sentence dump — that avoids both failure modes."}]}, {"focus": "Checkpoint: thinking on paper", "review": "Checkpoint day: re-test the hardest moves — diagnosing T vs A notes, make-it-wrong drafts, keyword compression, deliberate relationship choices, and intuitive-vs-logical groups. Use fresh material from your own course. Aim for maps that help you think, not transcripts that help you avoid thinking.", "task": {"do": "Pick a *different* topic than yesterday. In 8 minutes: blank-page keyword map with guessed links, cut fluff, fix one grouping so it is both intuitive and logical, and mark one arrow you almost drew but rejected.", "capture": "Summarize the map's groups, one revised link, and the rejected link with reasons.", "minutes": 8}, "check": [{"q": "You rejected a link on today's fresh map. What skill does that habit train, and why does showing every possible link undermine it?", "rubric": "correct: Selective relationship judgment; all-links skips deciding what matters. mostly_correct: Mentions choosing links without clear why-not-all. incorrect: Maximizing links, memorizing textbook order, or letting software choose.", "exemplar": "Rejecting a link trains deciding which relationships matter. Showing everything removes that judgment and turns the map passive and overwhelming."}, {"q": "A friend says your messy draft means you failed. Using this subject's practice, how should you respond — and what still remains unfinished if you never revise?", "rubric": "correct: Messy wrong draft is the correct first move; then shorten and reorganize; mess without revision is incomplete. mostly_correct: Defends messiness without naming next steps. incorrect: Agrees to switch to passive transcription or keep mess forever with no revision.", "exemplar": "The messy wrong draft was the right first move. I still need to shorten and reorganize — mess without revision is incomplete, but mess as a draft is required."}, {"q": "If a practice question breaks a grouping that felt obvious, what does that mean about intuitive vs logical structure — and what should you do?", "rubric": "correct: Grouping was intuitive but not logical enough; revise it. mostly_correct: Says revise without naming intuitive≠logical. incorrect: Blame the question, stop grouping, or keep unbroken \"obvious\" groups unchecked.", "exemplar": "It means the grouping felt intuitive but was not logical enough. I should reorganize the groups so they survive tricky questions, not keep a false split because it felt obvious."}]}]}, {"id": "active-recall", "title": "Active Recall, Done Right", "order": 8, "lesson": "active-recall.html", "days": [{"focus": "Retrieval over review", "review": "*Retrieval* pulls knowledge *out* of memory; encoding puts it in. Techniques built around retrieval — active recall — give beginners the most bang for buck: the learning curve is low and results show up in hours to days. Today you contrast producing an answer with merely reviewing it on your own material.", "task": {"do": "Pick one concept from your current course. Spend 3 minutes rereading your notes on it, then close them and spend 3 minutes writing everything you can produce from memory on a blank page. Compare gaps — about 8 minutes.", "capture": "List 3 ideas that appeared in notes but not in your blank-page recall (or note if recall was complete).", "minutes": 8}, "check": [{"q": "You compared rereading with blank-page production. What outcome from your attempt shows retrieval doing real work that review was hiding?", "rubric": "correct: Points to gaps that appeared only under closed production / recognition vs production contrast from their attempt. mostly_correct: Prefers retrieval but weak tie to their gaps. incorrect: Treats easier rereading or highlighting as proof of mastery.", "exemplar": "Gaps showed up only when I had to produce without looking — ideas that felt familiar while rereading were missing on the blank page. That is retrieval revealing what recognition hid."}, {"q": "Looking at your gap list, what is the strongest next step — and why is another comforting reread a weaker response?", "rubric": "correct: Target gaps with later closed-book production; reread-for-comfort avoids retrieval. mostly_correct: Mentions practicing gaps vaguely. incorrect: Ignore gaps if notes looked familiar, or highlight-only.", "exemplar": "I should target those gaps with another closed-book production attempt later. Rereading the whole chapter for comfort would hide the gaps again instead of training retrieval."}, {"q": "If rereading felt easier than blank-page recall, what does that ease usually mean about how memory gets strengthened?", "rubric": "correct: Ease means review skipped reconstructive work that strengthens pathways. mostly_correct: Says hard is better without naming reconstruction. incorrect: Ease proves mastery; harder methods always worse.", "exemplar": "Rereading felt easier because it skipped effortful reconstruction. That reconstructive work is what strengthens the memory — ease was not mastery."}]}, {"focus": "Free recall on a blank page", "review": "*Free recall* means retrieving with no prompt — \"tell me everything about this topic.\" It is the most powerful form because you can recall in an *integrated*, elaborate way, not card by card. A blank page (or blank screen) is the simplest free-recall gym.", "task": {"do": "Choose one lecture or chapter section. Close all materials. On a blank page, brain-dump the topic for 6–7 minutes: structure, examples, and links — no peeking. Then open notes for 1–2 minutes and star missing pieces only.", "capture": "Paste a short outline of what you produced, plus the starred gaps.", "minutes": 8}, "check": [{"q": "Looking at how you produced today's dump, what made it free recall rather than cued recall?", "rubric": "correct: No prompt/question stem — generated structure themselves. mostly_correct: Says \"from memory\" without contrasting cues. incorrect: Describes flashcards, peeking first, or fill-in-the-blanks as free recall.", "exemplar": "It was free recall because I generated the structure myself with no question stem — not answering a flashcard cue or filling printed blanks."}, {"q": "If your dump listed facts but almost no links, what upgrade should you make on a second closed pass — and why?", "rubric": "correct: Add relationships/why-it-matters from memory; free recall's power is integrated retrieval. mostly_correct: Mentions improving dump without naming links. incorrect: Copy more isolated facts or switch only to MCQ.", "exemplar": "On a second closed pass I should add arrows and \"why this matters\" lines. Free recall's power is integrated, elaborate retrieval — not a longer list of isolated facts."}, {"q": "If you peeked halfway because it felt hard, how should you classify that attempt, and what will you change next time?", "rubric": "correct: Weakened free-recall; stay closed until timer ends, check only after. mostly_correct: Admits peeking was suboptimal without clear fix. incorrect: Calls peeking a success or more efficient than closed-book.", "exemplar": "Peeking weakened the free-recall attempt by turning production into recognition. Next time I stay closed until the timer ends and check only afterward."}]}, {"focus": "Cued recall without cheating", "review": "*Cued recall* retrieves from a prompt (a flashcard question). It is effective, but only if you genuinely generate the answer before flipping. Today you practice honest cued recall on your own cards or self-made prompts — speak or write the full answer first.", "task": {"do": "Make or open 5–8 prompts from your own material. For each: cover the answer, write/speak a full response, then check. Mark R (true recall) or N (you only recognized it after seeing the answer) — about 8 minutes.", "capture": "List each prompt in short form with R or N, and rewrite one N item as a fuller answer from memory now.", "minutes": 8}, "check": [{"q": "For items you marked N, what does N mean you must do differently next time — and why does \"it made sense when I saw it\" not count?", "rubric": "correct: Treat as wrong; force full generation before checking; recognition ≠ recall. mostly_correct: Says try harder without marking wrong. incorrect: Count recognition as success or only study easy R items.", "exemplar": "N means I only recognized the answer, so I mark it wrong and must generate fully before checking next time. \"It made sense\" is recognition, not recall."}, {"q": "Which of today's attempts was your strongest cued-recall rep? Describe what you did while the answer was still covered.", "rubric": "correct: Wrote/spoke a complete answer with the back covered. mostly_correct: Mentions trying before flipping vaguely. incorrect: Glancing first, reading Q+A together, or skipping hard cards.", "exemplar": "My strongest rep was writing a full answer while the back was still covered. Glancing first and nodding would have been recognition, not cued recall."}, {"q": "If your R/N list is mostly N, how should you interpret that — as failure of the subject, or as useful diagnosis?", "rubric": "correct: Useful diagnosis — those cues need closed generation practice, not softer checking or retreat to rereading. mostly_correct: Sees problem but vague next step. incorrect: Stop testing / only reread / conclude subject impossible.", "exemplar": "Mostly N is useful diagnosis: those cues need honest closed generation, not softer checking or a retreat into rereading."}]}, {"focus": "Escape the recognition trap", "review": "Recognition is far easier than recall — you can recognize a coin but maybe not draw it. Reading a question, glancing at the answer, and thinking \"yeah, I knew that\" proves nothing about production. Many wasted hours hide here. Fix: generate fully before checking; if you only recognized it, mark it wrong.", "task": {"do": "Pick 3 facts/diagrams from your subject you usually \"know when you see them.\" Without looking, draw or write each from scratch. Then compare to the source and score production vs recognition — about 8 minutes.", "capture": "For each item: what you produced, what was missing, and whether past study was mostly recognition.", "minutes": 8}, "check": [{"q": "If you could recognize an item yesterday but failed to produce it today, what does that prove about familiarity while looking?", "rubric": "correct: Recognition was masquerading as mastery; familiarity ≠ production. mostly_correct: Admits a gap without naming recognition trap. incorrect: Drawing unrelated to knowing; familiarity is the exam skill.", "exemplar": "It proves recognition was masquerading as mastery. Familiarity while looking did not mean I could produce the diagram — that is the recognition trap."}, {"q": "Based on your reflection, which study habit should you cut first, and which production-first habits should you keep?", "rubric": "correct: Cut glance-and-nod / recognition checking; keep closed production and marking recognition failures wrong. mostly_correct: Mentions cutting something passive vaguely. incorrect: Cut closed-book practice or marking failures wrong.", "exemplar": "I should cut glancing at answers and deciding they make sense. I keep closed-book drawing/writing before checking and marking recognition-only as wrong."}, {"q": "You found gaps in a \"familiar\" topic. What is the strongest response, and why do highlighting or waiting for familiarity-while-checking fail?", "rubric": "correct: Schedule another closed production on those gaps; highlighting/soothing familiarity avoids retrieval. mostly_correct: Practice gaps vaguely. incorrect: Assume exam only tests recognition; stop because checking felt familiar.", "exemplar": "I should schedule another closed production attempt on those gaps. Highlighting until it feels familiar again only restores recognition comfort — it does not train production."}]}, {"focus": "Break cue saturation", "review": "Repeat the same flashcard enough and you answer from the *first few words* of the question, not the knowledge. Then the exam phrases it differently and you blank. Fix: keep switching cues and prompts so you are authentically retrieving, not pattern-matching the card.", "task": {"do": "Take 3 ideas you usually study with the same flashcard wording. For each, invent 3 new prompts (different angle, diagram blank, \"why/when,\" or teach-it cue). Answer all 9 from memory — about 8–10 minutes.", "capture": "Paste the 3 ideas with their 3 new prompts each, and note which prompt was hardest.", "minutes": 9}, "check": [{"q": "If you answered an old card easily but failed a rephrased prompt, what happened — and what does that say about the easy success?", "rubric": "correct: Cue saturation / pattern-matching the familiar stem; easy success was not authentic retrieval. mostly_correct: Notes phrasing mattered without naming saturation. incorrect: Varied cues unfair; only one wording forever.", "exemplar": "That was cue saturation — I was pattern-matching the familiar stem, not retrieving the idea. The easy old-card success was not trustworthy."}, {"q": "Which of your new prompts best fights saturation, and what made it a different retrieval path rather than a tiny reword?", "rubric": "correct: Identifies a prompt with a truly different path (why/when, blank diagram, teach-it) vs synonym swap. mostly_correct: Picks a new prompt without explaining path difference. incorrect: Same stem with synonym, answer on front, or highlighted MCQ.", "exemplar": "My \"when would you use this?\" prompt fought saturation best because it forced a different path than the usual definition stem — not just one synonym swapped."}, {"q": "After today's varied cues, what should you do with old single-wording cards that you always ace?", "rubric": "correct: Retire or rewrite so exams cannot catch unfamiliar phrasing. mostly_correct: Mentions changing cards vaguely. incorrect: Keep as only practice; clone identical stems; stop retrieval.", "exemplar": "I should retire or rewrite those saturated cards so one familiar stem is not my only practice. Exams will not use that exact wording."}]}, {"focus": "Teach it simply", "review": "Teaching the topic to a 10-year-old (Feynman-style) is strong free recall: you must structure it, compare and order ideas, and *simplify* — which means judging what matters. That builds an integrated schema. A plain brain dump is good; teaching forces deeper evaluation.", "task": {"do": "Pick one concept from your course. Without notes, explain it aloud or in writing as if to a smart 10-year-old for ~6 minutes: simple words, clear order, one analogy. Then check notes and mark where you hand-waved — about 8 minutes.", "capture": "Paste your simple explanation (or outline) and list the hand-wavy spots you found.", "minutes": 8}, "check": [{"q": "Where did you get stuck simplifying? What does that usually mean about your schema there?", "rubric": "correct: Fuzzy spot — cannot yet judge what matters / weak integration. mostly_correct: Admits confusion without schema diagnosis. incorrect: Simplifying is fluff; add more jargon; topic cannot be taught.", "exemplar": "Getting stuck simplifying a step flagged a fuzzy place in my schema — I cannot yet judge what matters there. That is why teaching exposes weak integration."}, {"q": "Compared with isolated flashcard answers, what extra demand did teaching place on you today?", "rubric": "correct: Structure, order, integrate, evaluate importance — not only retrieve isolated answers. mostly_correct: Says teaching is deeper vaguely. incorrect: All retrieval identical; teaching is only entertainment.", "exemplar": "Teaching forced me to structure, order, and integrate ideas and judge what matters — not only spit back isolated card answers."}, {"q": "How will you use your hand-wavy list next — and why is highlighting the chapter a weaker follow-up?", "rubric": "correct: Closed-book re-teach focusing on weak links; highlighting soothes without production. mostly_correct: Review weak spots vaguely. incorrect: Ignore if story sounded fine; recognition quiz only.", "exemplar": "I will re-teach those hand-wavy links closed-book. Highlighting the chapter would make it feel familiar again without forcing me to produce the missing structure."}]}, {"focus": "Practice how you play", "review": "Match retrieval to how you will *use* the knowledge. Train declarative (what/why), procedural (how to execute), and conditional (when/why to choose an approach). If the exam makes you solve problems, practice solving — not only comfortable definition cards. In many procedural subjects, under-trained *declarative* understanding is high-yield.", "task": {"do": "Name how your next assessment uses this topic (solve / write / code / explain). Run 3 short retrievals from memory: one declarative, one procedural, one conditional (\"when would you use…?\") on your own material — about 8–10 minutes.", "capture": "State the assessment format, then briefly record your three attempts and which was weakest.", "minutes": 9}, "check": [{"q": "If your weakest attempt was procedural but your usual cards are mostly definitions, what should change in your practice — and why?", "rubric": "correct: Add closed-book practice matching exam execution; definitions alone do not train performance. mostly_correct: Mentions more practice vaguely. incorrect: Keep only safe definitions; drop all declarative; watch solutions only.", "exemplar": "I need closed-book problem/execution practice that matches the exam. Definition cards feel safer but do not train the procedural performance I am tested on."}, {"q": "If you nailed procedures but failed \"when would you use this?\", what kind of knowledge is missing?", "rubric": "correct: Conditional knowledge — choosing when/why approaches. mostly_correct: Says something about timing/choice vaguely. incorrect: Just more identical drills; recognition-only; timing never matters.", "exemplar": "Conditional knowledge is missing — knowing when and why to choose an approach, not only how to execute steps."}, {"q": "For a maths-heavy or highly procedural course, what high-yield warning from this lesson should shape your mix of declarative and procedural retrieval?", "rubric": "correct: Strengthen under-trained declarative why/when alongside procedures — not recognition-only formula sheets or dropping explanations. mostly_correct: Mentions balancing types vaguely. incorrect: Only memorize formulas by recognition; avoid problems; drop explanations.", "exemplar": "I should strengthen under-trained declarative why/when alongside procedures. Recognition-only formula sheets leave the high-yield understanding gap the lesson warns about."}]}, {"focus": "The retrieval loop", "review": "The loop: (1) learn a small chunk and encode it well, (2) close everything and *produce* it (free or varied-cue), (3) check, correct, note gaps, (4) revisit gaps later at spaced intervals. Today you run one full loop on a small piece of your own coursework.", "task": {"do": "Select a small chunk you studied in the last 48 hours. Encode/refresh 2 minutes, closed produce 4 minutes, check and list gaps 2 minutes. Write a date for the next gap revisit (tomorrow or as fits your schedule).", "capture": "Chunk name, gap list, and the next revisit date you committed to.", "minutes": 8}, "check": [{"q": "After producing from memory, which loop step did you complete next — and why does skipping it leave the loop unfinished?", "rubric": "correct: Check, correct, note gaps; without that errors persist and spaced revisit has no targets. mostly_correct: Mentions checking vaguely. incorrect: Skip checking; only add unrelated cards; reread whole textbook as the step.", "exemplar": "I checked, corrected, and noted gaps. Skipping that leaves errors uncorrected and gives the next spaced revisit nothing specific to aim at."}, {"q": "You scheduled a revisit for your gaps. What must that revisit emphasize, and what should it avoid?", "rubric": "correct: Active recall on gaps with varied cues; avoid passive reread/highlight/recognition-first. mostly_correct: Says review gaps vaguely. incorrect: Whole-chapter reread only; answers visible first.", "exemplar": "The revisit must use active recall aimed at the gaps, ideally with varied cues — not a passive reread of the whole chapter or recognition with answers visible first."}, {"q": "If you wanted to learn a huge chapter in one loop, how should you adjust chunk size — and why?", "rubric": "correct: Keep chunk small enough to encode and produce well; oversized chunks break production quality. mostly_correct: Says go smaller without why. incorrect: Skip production to cover more; check before producing to go faster.", "exemplar": "I should keep the chunk small enough to encode and produce well in one sitting. A huge chapter in one loop breaks production quality — covering more pages by skipping production is not the loop."}]}, {"focus": "Full retrieval workout", "review": "Combine the subject's tools on one real topic: free recall, honest cued prompts, at least one rephrased cue to beat saturation, and a quick teach-it pass. Stay production-first. Match at least one attempt to how you will be assessed.", "task": {"do": "On one exam topic from your course (~10 minutes): blank-page free recall → 3 varied cues → 2-minute teach-it simplification → star gaps. No answer-peeking until each attempt is finished.", "capture": "Outline of free recall, the 3 cue wordings, one teach-it sentence, and starred gaps.", "minutes": 10}, "check": [{"q": "In the workout you just finished, where did the recognition trap still show up — if it did — and how should you score that moment?", "rubric": "correct: Any early glance + \"I knew that\" is recognition; mark wrong and regenerate. Writing before flipping / varied cues / teach-it are not the trap. mostly_correct: Mentions peeking without scoring rule. incorrect: Calls early glancing success.", "exemplar": "If I glanced early and thought \"I knew that,\" that was the recognition trap — I mark it wrong and regenerate. Writing before flipping was the correct move."}, {"q": "If free recall was rich but an exam-style procedural attempt was weak, how should your next session bias practice?", "rubric": "correct: Bias toward how you will play (problems/procedures) while keeping declarative links; do not drop free recall or switch to recognition-only. mostly_correct: Mentions more problems vaguely. incorrect: Ignore exam format; only MCQ recognition; drop free recall permanently.", "exemplar": "Next session should bias toward exam-like problems/procedures while keeping declarative links. I should not ignore the exam format or abandon free recall for recognition-only drills."}, {"q": "What detail in your capture best proves you challenged cue saturation today?", "rubric": "correct: Three differently angled prompts for the same idea. mostly_correct: Mentions \"varied practice\" without citing prompts. incorrect: One familiar stem repeated; reading answers then questions.", "exemplar": "Having three differently angled prompts for the same idea proves I challenged cue saturation — not repeating one saturated stem ten times."}]}, {"focus": "Checkpoint: retrieval done right", "review": "Checkpoint: re-test the hardest practice moves with fresh material — blank-page free recall, marking recognition as wrong, varied cues against saturation, teach-it simplification, and matching retrieval to assessment type. No definition trivia — judge the attempts you make today.", "task": {"do": "Choose a topic you have *not* used this week. Closed free recall 4 minutes; create 2 brand-new cues and answer them; teach one sticky point in simple language; note gaps and when you will revisit.", "capture": "Topic, gap list, revisit time, and which attempt was hardest (free / cued / teach).", "minutes": 9}, "check": [{"q": "Today's hardest attempt failed while an old familiar flashcard still feels easy. What is the best diagnosis, and which signal should you trust?", "rubric": "correct: Cue saturation or recognition comfort; trust harder production evidence. mostly_correct: Prefers hard attempt without naming saturation. incorrect: Hard attempt invalid because it felt bad; familiar cards are true measure.", "exemplar": "The easy familiar card is likely cue saturation or recognition comfort. I should trust the harder production failure as the honest signal."}, {"q": "You recognized an answer as soon as you uncovered it. How do you score that card, and why?", "rubric": "correct: Wrong — recognition without prior generation does not count. mostly_correct: Says partial credit vaguely. incorrect: Correct because it made sense; skip scoring.", "exemplar": "I score it wrong. Recognition without generating first does not count as recall, even if the answer made sense immediately."}, {"q": "What next move best closes today's checkpoint loop, given your gap list and revisit time?", "rubric": "correct: Revisit starred gaps with production later; not whole-book reread, recognition piles, or stopping because notes looked familiar. mostly_correct: Mentions revisiting vaguely. incorrect: Familiarity while looking ends the loop.", "exemplar": "I revisit the starred gaps with production at the time I scheduled. Looking familiar in notes does not close the loop — later retrieval on the gaps does."}]}]}, {"id": "spacing", "title": "Spacing & the Forgetting Curve", "order": 9, "lesson": "spacing.html", "days": [{"focus": "See your forgetting curve", "review": "After learning something once, memory can drop steeply — Ebbinghaus showed you might fall from high retention toward very little within a day. That decay eventually hits everything. Today you measure what survived from your own recent study so spacing has a personal baseline, not an abstract graph.", "task": {"do": "Pick material you studied 1–2 days ago and have not reviewed. Closed-book, write what you still remember (5 min). Check notes and estimate % retained. Note what vanished first — about 8 minutes.", "capture": "Topic, rough % retained, and 3 items that disappeared.", "minutes": 8}, "check": [{"q": "Using your retention estimate after a delay, how should you read that drop in light of the forgetting curve — as a personal failure, or as expected data?", "rubric": "correct: Sharp drop after one exposure is normal baseline; spacing exists to slow later fades — not a verdict on ability. mostly_correct: Accepts some forgetting without linking to spacing. incorrect: Any drop means abandon subject; perfect memory should be default.", "exemplar": "My modest retention is expected decay after one exposure, not proof I cannot learn. It is baseline data spacing is meant to fight by slowing the next fade."}, {"q": "Looking at the three items that vanished first, what is the best immediate use of that list?", "rubric": "correct: Target them with active recall in the next spaced review. mostly_correct: Study them again vaguely. incorrect: Ignore and reread everything equally; highlight-only; recognition glances only.", "exemplar": "Those three items should be the targets for active recall in my next spaced review — not buried in an undifferentiated full-chapter reread."}, {"q": "If low retention felt demoralizing, what is a productive framing that still leads to action?", "rubric": "correct: Expected decay data to fight with spaced, high-quality retrieval — not quit testing or only cram forever. mostly_correct: Stay hopeful without naming spacing action. incorrect: Spacing useless because forgetting happened; stop testing to avoid seeing losses.", "exemplar": "Low retention is expected decay data I can fight with well-timed, high-quality retrieval. Stopping tests so I never see losses would only hide the problem."}]}, {"focus": "Spacing slows the fade", "review": "Each well-timed review makes the memory fade *more slowly* next time — the spacing effect, one of the most valuable tools in learning. Massing everything in one sitting feels productive; spreading retrieval over time changes the slope of forgetting. Today you schedule real reviews on your own calendar.", "task": {"do": "Choose 2 topics you need long-term. On your calendar/planner, place a short active-recall review for each at three future times (e.g., +1 day, +1 week, +1 month — adjust to your term). Keep each block 10–15 minutes — about 8 minutes to plan.", "capture": "Paste the two topics with their three dated review slots.", "minutes": 8}, "check": [{"q": "Look at the schedule you just made. What about it actually uses the spacing effect rather than massed study?", "rubric": "correct: Multiple retrieval sessions spread over days/weeks for the same topics. mostly_correct: Mentions reviewing later vaguely. incorrect: One marathon tonight; anxiety rereads; infinite new material with no revisits.", "exemplar": "I have three retrieval sessions for each topic spread across days and weeks. That distributed retrieval is spacing — not one 3-hour marathon tonight."}, {"q": "A friend crams the same topic for four hours today instead of using spaced slots. What trade-off should you expect between their plan and yours?", "rubric": "correct: Cramming may feel strong now but fades faster; spaced reviews slow later forgetting. mostly_correct: Prefers spacing without fade trade-off. incorrect: Cramming always beats spacing long-term; spaced plan weaker because less intense today.", "exemplar": "Their cram may feel stronger today, but it should fade faster. My spaced retrievals should make the memory fade more slowly next time even if today feels less intense."}, {"q": "Which calendar entry from today is strongest, and how would you rewrite a vague \"study more\" entry to match that standard?", "rubric": "correct: Dated blocks with topic + active recall; vague intentions need topic + retrieval method + date. mostly_correct: Wants dates without retrieval specificity. incorrect: Only exam-eve cram; \"look at notes\" with no retrieval.", "exemplar": "My dated blocks labeled with topic and active recall are strongest. \"Study more\" should become a specific date, topic, and closed retrieval method."}]}, {"focus": "A simple default schedule", "review": "You do not need fancy software. A solid default: review after **1 day, then 1 week, then 1 month.** Exact intervals are not critical — 3 hours vs a day, or 3 weeks vs 6 weeks, can all work. Consistency matters, and *what you do* in each review matters more than the algorithm.", "task": {"do": "Pick one concept you learned today (or yesterday). Write a mini plan on paper: Review A tomorrow (free recall), Review B in ~1 week (varied cues), Review C in ~1 month (exam-style use). Put the first reminder in your phone now — about 8 minutes.", "capture": "Concept name + the three review dates/actions you chose.", "minutes": 8}, "check": [{"q": "If you agonized over 6 vs 8 days for Review B, what does the lesson say you should prioritize instead?", "rubric": "correct: Consistency and quality of spaced retrieval over exact interval tuning. mostly_correct: Says don't stress dates vaguely. incorrect: Only perfect algorithms work; must review every hour.", "exemplar": "Exact tuning matters little compared with consistently doing quality spaced retrieval. Obsessing over 6 vs 8 days is the wrong lever."}, {"q": "How do your three reviews reflect the day / week / month default spirit rather than massing or a single pass?", "rubric": "correct: Expanding gaps across day/week/month scales with retrieval actions. mostly_correct: Lists three reviews without naming expanding gaps. incorrect: All three tonight; only one review ever; passive rereads only.", "exemplar": "I spread retrieval across tomorrow, about a week, and about a month with different retrieval modes. That expanding-gap default is not massing all three into tonight."}, {"q": "If your phone reminder only says \"study,\" how should you improve it after today's task?", "rubric": "correct: Specify concept + closed-book retrieve how. mostly_correct: Make it more specific vaguely. incorrect: Delete reminders; replace with reread everything; fifty same-night alarms.", "exemplar": "I should name the concept and that I will retrieve closed-book. A vague \"study\" reminder does not make the spacing action concrete."}]}, {"focus": "Quality beats the algorithm", "review": "The research does *not* show that a perfectly tuned interval matters much. The quality of the retrieval session matters far more: active recall that hits an integrated schema and \"practices how you play.\" A mediocre app interval with weak recognition flipping loses to a simple schedule with strong production.", "task": {"do": "Run one scheduled (or overdue) review on your own material for ~8 minutes: closed integrated recall or exam-style use — no answer-peeking first. Avoid isolated recognition glances. End by noting whether the session trained how you will be tested.", "capture": "What you retrieved, how (free/cued/problem), and one upgrade to make next review more exam-real.", "minutes": 8}, "check": [{"q": "Describe the review session you just ran. What made it higher or lower quality by this lesson's standard?", "rubric": "correct: Judges by production before checking / integrated or exam-like use vs recognition nodding or interval tinkering only. mostly_correct: Calls it good/bad without quality criteria. incorrect: Perfect app timing alone = high quality.", "exemplar": "Mine was higher quality because I produced an integrated answer before checking. Flipping cards and nodding at familiar answers — even at a \"perfect\" interval — would have been low quality."}, {"q": "If an app buzzed at the \"perfect\" time but you only recognized answers, what should you prioritize fixing?", "rubric": "correct: Generation-before-check and exam-real tasks — timing cannot rescue recognition-only. mostly_correct: Mentions trying harder vaguely. incorrect: Buy a better algorithm; ignore quality because timing was perfect.", "exemplar": "I should fix generation-before-check and make tasks more exam-real. Perfect timing does not rescue recognition-only reviews."}, {"q": "Which upgrade in your capture best aligns with \"practice how you play,\" and why?", "rubric": "correct: Swap definition glances for problem/explain-as-tested retrieval. mostly_correct: Mentions an upgrade without exam-real link. incorrect: More identical easy stems; shorten intervals to minutes today; remove production.", "exemplar": "Swapping pure definition glances for problem or explain-as-tested retrieval aligns with practice how you play — it trains the performance I need, not only comfortable recognition."}]}, {"focus": "Spot learning debt", "review": "Each new flashcard commits your future self to many repetitions. One lecture might spawn 30–50 cards → ~150 reviews; several lectures a day → hundreds stacking next week while new cards arrive. That compounding pile is *learning debt*, and motivated students often drown by week two. Today you audit your own backlog.", "task": {"do": "If you use cards (or a to-review list), count new items from the last 3–5 study days and estimate pending reviews this week. If you do not use cards, count \"things I meant to restudy\" instead. Mark whether the pile is growing — about 8 minutes.", "capture": "Numbers: new items, estimated pending reviews, and one sentence on whether debt is rising.", "minutes": 8}, "check": [{"q": "If your pending reviews are rising while you keep adding cards (or restudy items), what pattern is that — and why is high motivation not a fix by itself?", "rubric": "correct: Learning debt compounding toward collapse; motivation can accelerate adding debt. mostly_correct: Sees backlog problem vaguely. incorrect: Proof spacing scales forever; add cards faster; debt irrelevant if motivated.", "exemplar": "That is learning debt compounding toward collapse. High motivation can make it worse if I keep adding items faster than I repay reviews."}, {"q": "You estimated a large future-rep load from one dense lecture's cards. What is the best response?", "rubric": "correct: Shrink what becomes a card; invest more in encoding so fewer reps needed. mostly_correct: Make fewer cards vaguely. incorrect: Keep generating that volume; ignore math; stop all review forever.", "exemplar": "I should shrink what becomes a card and invest more in encoding so I need fewer spaced reps — not celebrate a huge deck from every lecture."}, {"q": "Which detail in your capture is the clearest early warning of unsustainable spacing, and what would a healthier pattern look like?", "rubric": "correct: Pending reviews growing week over week vs a small stable finishable list. mostly_correct: Mentions numbers without growth warning. incorrect: Rising backlog is fine; only rereading with no list is healthier.", "exemplar": "Pending reviews growing week over week is the clearest warning. A healthier pattern is a small stable deck or list I actually finish daily."}]}, {"focus": "Isolated cards, shallow mastery", "review": "Spacing alone has a second problem: answering isolated cards keeps you at low, isolated mastery, so complex integrated problems still wreck you no matter how many reps you log. Flashcards can support memory; they do not replace building connected understanding. Today you stress-test a \"known\" card cluster with an integrated task.", "task": {"do": "Take 5–8 cards/facts you can answer in isolation from your subject. Put them away. On a blank page, write an integrated explanation or solve a mixed problem that requires using several together — 7–8 minutes, then check.", "capture": "Which isolated items you \"knew,\" and where the integrated attempt broke.", "minutes": 8}, "check": [{"q": "If you hit every card but failed the integrated task, what does that mean about isolated mastery?", "rubric": "correct: Isolated mastery is not enough for complex performance. mostly_correct: Admits a gap without naming isolation limit. incorrect: More identical card reps auto-fix integration; integrated tasks unfair.", "exemplar": "It means isolated mastery is not enough. I can ace atomic cards and still fail when complex performance needs the ideas connected."}, {"q": "What adjustment should your review plan make after today's break — without abandoning spacing?", "rubric": "correct: Add periodic closed integrated retrieval, not only atomic cards. mostly_correct: Mentions synthesis vaguely. incorrect: Only easier cards; stop spacing; replace checks with highlighting.", "exemplar": "I should keep spacing but add periodic closed integrated explain/problem sessions on the same cluster — not only atomic flips."}, {"q": "Write a healthy study-log line for a session like today's, and contrast it with a misleading \"40 cards correct\" line.", "rubric": "correct: Combines modest cards + closed integrated work; contrasts with cards-only or peeking recognition. mostly_correct: Wants integration mentioned vaguely. incorrect: Celebrates card count with skipped synthesis as healthy.", "exemplar": "A healthy line is \"15 cards + one closed integrated explain on the same cluster.\" \"40 cards correct; skipped synthesis\" would hide the shallow-mastery problem I just saw."}]}, {"focus": "Spacing needs encoding", "review": "Relying only on active recall + spaced repetition is a *rate-limiting step*: like a short plank in a barrel, learning leaks from the weakest part. Pair spacing with strong encoding. Encode well and the forgetting curve flattens, so you need far fewer repetitions — Justin's example: a heavy master's topic needing only ~10–15 cards after good encoding.", "task": {"do": "Choose a topic whose card count or review load feels heavy. Spend ~8 minutes building/improving a one-page big-picture keyword map (relationships, not a transcript). Then list cards you could delete or never make because the map already holds them.", "capture": "Map summary (groups/links) and a prune list of cards/items you no longer need as isolates.", "minutes": 8}, "check": [{"q": "You pruned cards after mapping. What principle about encoding and spaced reps did you apply?", "rubric": "correct: Better encoding reduces how many spaced reps you need; spacing supports encoding rather than replacing it. mostly_correct: Says maps help reduce cards vaguely. incorrect: More cards always beat encoding; maps replace all retrieval forever.", "exemplar": "Stronger encoding flattens forgetting so I need fewer spaced reps. Spacing supports that encoding — it does not replace building the big picture."}, {"q": "If your deck is huge and integrated questions still fail, what is the highest-leverage move?", "rubric": "correct: Invest in encoding/big picture, not only more reps. mostly_correct: Mentions understanding vaguely. incorrect: Double daily cards; shorten every interval to minutes; avoid maps to save time.", "exemplar": "Highest leverage is investing in encoding and the big picture. Doubling card count keeps leaning on the short plank instead of fixing it."}, {"q": "Which kind of item on your prune list is safest to cut, and which kinds should you keep?", "rubric": "correct: Cut isolates the map already explains; keep items that still fail in exam-style/conditional/integrated use. mostly_correct: Cuts something redundant vaguely. incorrect: Cut core failing procedures/gaps; keep only saturated wording clones.", "exemplar": "Safest cuts are isolated wordings I can already explain through the map's relationships. I keep procedures or conditional distinctions I still fail in real use."}]}, {"focus": "Use flashcards as a supplement", "review": "Flashcards are great when aligned with your goal — best for Reference and some Evidence information (PACER). Keep decks small, keep cards spaced, vary cues, and always retrieve before flipping. Overwhelm or stuck low mastery is a signal to invest in encoding, not more cards. Later study and professional life rarely run on flashcards alone.", "task": {"do": "Audit 10 of your own cards (or 10 facts you might card). Label each Keep (true reference/evidence worth spaced reps) or Map/Encode instead. Rewrite 2 Keep prompts to vary the cue — about 8–10 minutes.", "capture": "Keep vs Map counts, plus the two rewritten prompts.", "minutes": 9}, "check": [{"q": "If most items were better as Map/Encode, what should change in your study this week?", "rubric": "correct: Stop carding everything; encode relationships; card sparingly for suitable targets. mostly_correct: Fewer cards vaguely. incorrect: Card every syllabus sentence; ignore PACER; increase new cards.", "exemplar": "I should stop turning everything into cards, encode relationships on a map, and card only the keep-worthy reference/evidence items."}, {"q": "If you feel overwhelmed by reviews, what does that signal mean according to this lesson?", "rubric": "correct: Invest in encoding and shrink the deck — not add more cards or trust recognition flipping. mostly_correct: Reduce load vaguely. incorrect: Add more cards until better; delete all retrieval.", "exemplar": "Overwhelm signals I should encode better and shrink the deck — not create more cards or catch up by recognition flipping."}, {"q": "Looking at your two rewritten prompts, what features make a rewritten Keep card match good card use?", "rubric": "correct: Varied cue, answer-before-flip, keep-worthy reference/evidence target; not answer-on-front, multi-idea paragraphs, or saturated clones. mostly_correct: Mentions varying cue only. incorrect: Celebrates answer-visible or saturated identical stems.", "exemplar": "A strong rewrite uses a varied cue I answer before flipping on a true keep-worthy fact — not the answer on the front or another clone of a saturated stem."}]}, {"focus": "Build a sustainable spacing system", "review": "Put it together on your real workload: a simple day/week/month-style schedule, high-quality retrieval in each slot, a debt check so the deck cannot explode, and encoding support so spacing stays a beginning — not the whole system. Sustainability beats heroic card counts.", "task": {"do": "For one active course: (1) list topics due for review in the next week, (2) assign each a retrieval method (free / varied-cue / exam-style), (3) cap new cards for the next 3 days at a number you can actually finish, (4) schedule one encoding/map session for the heaviest topic — about 10 minutes.", "capture": "Weekly review list with methods, your new-card cap, and the encoding session time.", "minutes": 10}, "check": [{"q": "Why does capping new cards align with this subject, given what you planned?", "rubric": "correct: Unbounded new cards create learning debt that collapses the system. mostly_correct: Caps help workload vaguely. incorrect: Caps always reduce learning; software makes caps unnecessary; never card reference facts.", "exemplar": "Capping new cards prevents committing future reps faster than I can repay them. Unbounded additions create learning debt that collapses the system."}, {"q": "Which weekly slot in your plan best reflects \"quality > algorithm,\" and what would a low-quality slot look like instead?", "rubric": "correct: Dated exam-style/integrated retrieval; contrasts with interval fiddling, passive rereads, or adding without reviewing. mostly_correct: Points to a review without quality contrast. incorrect: Opening app only to tweak settings as the quality win.", "exemplar": "My exam-style retrieval on a dated topic reflects quality over algorithm. Opening the app only to change interval settings or rereading while scrolling would be low quality."}, {"q": "You scheduled an encoding session beside reviews. What role does that session play relative to spacing?", "rubric": "correct: Flattens forgetting so spacing needs fewer reps — spacing supports encoding rather than replacing it. mostly_correct: Says encoding helps vaguely. incorrect: Proves flashcards are the entire system; means skip all future retrieval.", "exemplar": "Encoding flattens forgetting so I need fewer spaced reps. Spacing supports that encoding — it does not replace it or make flashcards the whole system."}]}, {"focus": "Checkpoint: spacing that lasts", "review": "Checkpoint with fresh material: measure decay, schedule spaced retrieval, demand session quality, detect learning debt, and prefer encoding when decks bloat. Judge the plans and attempts you produce today — not definitions of Ebbinghaus.", "task": {"do": "Pick a topic unused in this subject's tasks. Closed recall to estimate retention; book the next 1-day and 1-week retrievals; run a 5-minute high-quality review now; note one card/list item to prune or not create.", "capture": "% estimate, two future dates, what you produced in the 5-minute review, and the prune decision.", "minutes": 9}, "check": [{"q": "Your retention estimate may have been modest, yet you booked future retrievals. Why is that the right move?", "rubric": "correct: Well-timed reviews slow the next fade — decay is data, not a stop sign. mostly_correct: Says keep going vaguely. incorrect: Low retention means spacing never works; only schedule when memory is perfect.", "exemplar": "Modest retention is decay data, not a stop sign. Booking well-timed retrievals is how I slow the next fade."}, {"q": "Justify your prune-or-not-create decision using encoding and learning debt.", "rubric": "correct: If encoding/map/explain already carries it, extra card debt is unnecessary; keep items still failing in use. mostly_correct: Mentions pruning without encoding/debt link. incorrect: Pruning always wrong; only delete failing cards; apps forbid pruning.", "exemplar": "I pruned an item my map already explains so I do not add unnecessary card debt. Encoding that carries the idea means I do not need another isolate in the queue."}, {"q": "What about your 5-minute review shows you avoided the isolated-card trap?", "rubric": "correct: Connected production or exam-like use, not only atomic recognition nods. mostly_correct: Mentions retrieval without integration. incorrect: Faster saturated stems; adding many new isolates; only optimizing interval slider.", "exemplar": "I had to produce a connected explanation/use of the topic, not just nod at atomic cards. That is what avoids shallow spaced mastery."}]}]}, {"id": "interleaving", "title": "Interleaving", "order": 10, "lesson": "interleaving.html", "days": [{"focus": "Blocking vs interleaving", "review": "The intuitive revision habit is *blocking*: all of topic A, then B, then C. It feels smooth and you seem to improve fast within a block. *Interleaving* mixes them — A, C, B, A… Like kicks to a pad held at changing distances, mixed practice is harder but trains adjustment that repetition never does. Today you contrast both on your own material.", "task": {"do": "Pick 2 related topics/problem types from your course. Spend 4 minutes blocked on A only, then 4 minutes alternating A↔B every 1–2 minutes (questions, prompts, or recall cues you create). Note which felt smoother and which forced more decisions.", "capture": "Topics A/B, what you practiced in each half, and which required more \"which approach?\" decisions.", "minutes": 8}, "check": [{"q": "Which half of today's practice trained exam-like choosing, and what about it forced those decisions?", "rubric": "correct: Interleaved half — had to keep deciding which approach applied; blocked allows autopilot. mostly_correct: Prefers mixing without naming choice skill. incorrect: Blocked half trained choosing better; mixing never affects decisions.", "exemplar": "The interleaved half trained exam-like choosing because I had to keep deciding which approach applied. The blocked half let me run on autopilot within one method."}, {"q": "Blocked practice felt smoother. What should you conclude about that feeling versus revision quality?", "rubric": "correct: Smoothness often means less decision training — not automatically better revision. mostly_correct: Suspicious of ease vaguely. incorrect: Smoothness proves blocking always superior; difficulty always means wrong method.", "exemplar": "Feeling smoother usually means less decision training, not better revision. Interleaving's messiness is where the transferable choice skill is built."}, {"q": "What detail in your capture best shows you actually interleaved rather than finished one block then the other?", "rubric": "correct: Rotated A and B before either felt done. mostly_correct: Mentions both topics vaguely. incorrect: Finished all of A before B; only reviewed A; watched solutions only.", "exemplar": "I rotated A and B before either felt finished. Completing all of A before touching B would have been blocking, not interleaving."}]}, {"focus": "Train the choice skill", "review": "When you block, you already know which method every problem needs. When you interleave, you must first *decide which approach a problem calls for* — exactly what exams and real life test. Mixing also helps memory, test performance, unfamiliar variants, and naturally spaces practice. Today you build a mini set that forces that choice.", "task": {"do": "From your notes/problem sets, gather 6 short items that could be confused (3 from type A, 3 from type B). Shuffle them so types are mixed. Solve or answer from memory in shuffled order — about 8–10 minutes. Mark each: right approach chosen? yes/no.", "capture": "The shuffled order (A/B labels), and yes/no for approach choice on each.", "minutes": 9}, "check": [{"q": "If you missed an item because you used the previous item's method on autopilot, what skill failed?", "rubric": "correct: Selecting which approach the item called for. mostly_correct: Says concentration vaguely. incorrect: Neatness, reading speed only, or page-number memory.", "exemplar": "The skill that failed was selecting which approach the item called for. Autopilot from the previous item is exactly what interleaving is meant to disrupt."}, {"q": "Looking at your yes/no marks, where should tomorrow's mix focus, and why?", "rubric": "correct: On pairs you mis-classified — highest payoff discrimination practice. mostly_correct: Practice more vaguely. incorrect: Only types already perfect; unrelated subjects; passive solution rereads.", "exemplar": "Tomorrow's mix should focus on the pairs I marked no — mis-chosen approaches show where discrimination practice pays off most."}, {"q": "Why did shuffling matter for this task compared with AAA then BBB?", "rubric": "correct: Shuffling removes the giveaway that \"we are in type A now\" so you must choose. mostly_correct: Says mixing helps vaguely. incorrect: Order never matters; blocking forces choice equally.", "exemplar": "Shuffling hid the type label so I had to choose the approach. AAA then BBB advertises the method and removes that decision."}]}, {"focus": "Learn the basics first", "review": "Interleaving is a *revision* tool. You need a foundational understanding of each topic before mixing, or you are just confused. If you cannot yet do a simple blocked example of A or B, mix practice will thrash. Today you gate interleaving behind a quick readiness check on your own material.", "task": {"do": "List 3 candidate topics to interleave. For each, try one easy closed-book example. Label Ready (can do basics) or Not yet (still encoding). Build a mix only from Ready topics; schedule encoding for Not-yet — about 8 minutes.", "capture": "The three labels and the mix set you are allowed to use (Ready only).", "minutes": 8}, "check": [{"q": "If one topic failed its easy example, what is the correct move regarding your mix — and why?", "rubric": "correct: Keep it out until basics exist; mix Ready only — early interleaving thrash/confusion. mostly_correct: Delay vaguely. incorrect: Force into mix to catch up; drop all interleaving forever.", "exemplar": "I keep that topic out of the mix until basics exist and only interleave Ready topics. Mixing without foundations produces confusion, not discrimination skill."}, {"q": "If all three were Ready, what is the best next step from today's gate check?", "rubric": "correct: Build a mixed set from those related Ready topics. mostly_correct: Practice them somehow. incorrect: Wait until finals; block another month with no mix; interleave with unrelated hobby topics.", "exemplar": "Next I build a mixed set from those related Ready topics. The readiness gate exists so I can interleave now — not wait until finals."}, {"q": "A classmate mixes brand-new lecture topics nightly and feels lost. What is the diagnosis?", "rubric": "correct: Interleaving before foundations — revise after basics, do not thrash. mostly_correct: Too early vaguely. incorrect: Needs more unrelated subjects; confusion always means it is working; never use active recall.", "exemplar": "They are interleaving before foundations. Interleaving is a revision tool — mixing brand-new topics creates thrash, not useful difficulty."}]}, {"focus": "Mix related things", "review": "Interleave topics or problem types that could genuinely be confused or combined — not random unrelated subjects. The value is learning to *tell them apart* and choose between them. Mixing chemistry with unrelated history may space time, but it misses discrimination training.", "task": {"do": "From your syllabus, pick two pairs: (1) Related — easy to confuse/combine, (2) Unrelated — little overlap. Create a 6-item mix for the Related pair only and run it. Write one sentence on what distinction the mix forced — about 8 minutes.", "capture": "Related pair, Unrelated pair (not practiced), and the distinction your Related mix trained.", "minutes": 8}, "check": [{"q": "Why did today's task tell you not to practice the Unrelated pair?", "rubric": "correct: Interleaving payoff is discrimination among confusable/combinable types. mostly_correct: Related is better vaguely. incorrect: Unrelated mixes illegal; only identical items; related topics should never mix.", "exemplar": "The payoff is learning to tell confusable or combinable types apart and choose between them. An unrelated mix may space time but misses that discrimination training."}, {"q": "If your Related mix still felt too easy to tell apart, how should you upgrade the pair?", "rubric": "correct: Choose closer cousins / types you actually mix up on exams. mostly_correct: Make it harder vaguely. incorrect: Switch to unrelated; pure blocking forever; remove decision points.", "exemplar": "I should pick closer cousins or problem types I actually confuse on exams. If discrimination is trivial, the mix is not training the choice skill."}, {"q": "Give an example from your course of a strong interleaving pair versus a weak one, using today's relatedness rule.", "rubric": "correct: Strong = confusable Ready procedures/types; weak = unrelated courses, identical repeats, or unencoded topics. mostly_correct: Names a pair without contrast. incorrect: Prefers unrelated or unencoded mixes.", "exemplar": "A strong pair is two procedures I often apply to the wrong problem type. A weak pair is a maths drill mixed with unrelated vocabulary from another course."}]}, {"focus": "Switch before you're done", "review": "Do not finish a topic to completion before rotating. Switch while there is still a little struggle — the switching is the point. Completing every A item \"for closure\" recreates blocking. Today you practice leaving a thread unfinished on purpose.", "task": {"do": "Set a timer for 8 minutes with topics A and B (Ready + related). Work A for ~2 minutes, switch to B at mid-struggle, back to A, back to B. Do not \"finish the set\" of either. Stop mid-item if the timer says switch.", "capture": "When you switched (what you left unfinished) and how the mid-struggle switches felt.", "minutes": 8}, "check": [{"q": "If you wanted to finish A's worksheet before touching B, what rule were you about to break — and why does that rule exist?", "rubric": "correct: Switch before you're done — rotation matters more than closure; finishing recreates blocking. mostly_correct: Mentions switching vaguely. incorrect: Always complete blocks for interleaving; only switch when easy.", "exemplar": "I was about to break \"switch before you're done.\" Finishing A for closure recreates blocking; the switching itself is the training."}, {"q": "What in your capture best shows you followed the rule, and what pattern would show you broke it?", "rubric": "correct: Left items unfinished when switching vs completing all of A then all of B. mostly_correct: Mentions switching without unfinished evidence. incorrect: Only easier topic; avoided struggle by quitting.", "exemplar": "Leaving items unfinished when I switched shows rule-following. Completing all of A, then all of B, would show I broke it."}, {"q": "Mid-switch frustration spiked. How should you read that feeling during interleaved revision?", "rubric": "correct: Expected desirable difficulty — keep structured switches. mostly_correct: Hard is okay vaguely. incorrect: Proof to return to pure blocking; stop revision; Ready topics were a mistake.", "exemplar": "That frustration is expected desirable difficulty. I should keep structured switches rather than treat discomfort as a stop sign or a reason to return to blocking."}]}, {"focus": "Expect it to feel worse", "review": "Like other effective methods, interleaving feels harder and messier than blocking. That discomfort is desirable difficulty doing its job — not proof the method failed. Today you track performance and feeling separately so ease does not hijack your revision choices.", "task": {"do": "Run a 6–8 item interleaved set on related Ready material. After each item, jot F (felt easy/hard) and P (process correct: yes/no). Compare whether \"felt hard\" lined up with \"process wrong\" — about 8 minutes.", "capture": "Your F/P marks and one sentence on whether hard feelings matched actual errors.", "minutes": 8}, "check": [{"q": "If several items felt hard but your process was correct, how should you interpret that?", "rubric": "correct: Desirable difficulty — hard feelings ≠ failure of interleaving. mostly_correct: Hard can be okay vaguely. incorrect: Hard feelings always mean stop mixing; only do easy problems.", "exemplar": "Hard feelings with correct process are desirable difficulty. Feeling hard does not mean interleaving failed."}, {"q": "You nearly switched back to blocking because the session felt messy. What is the better move?", "rubric": "correct: Keep mixing related Ready items; judge by approach accuracy over comfort. mostly_correct: Persist vaguely. incorrect: Abandon when mood dips; only reread examples; mix unrelated for novelty.", "exemplar": "I should keep mixing related Ready items and judge by approach accuracy, not comfort. Messy feel is expected — comfort would recreate blocking."}, {"q": "Which metric from today's F/P log should drive adjustments, and which should not?", "rubric": "correct: Wrong approach choices (P=no) drive adjustments; F=hard alone should not. mostly_correct: Mentions accuracy vaguely. incorrect: Only pleasant feelings; handwriting; similarity to yesterday's block.", "exemplar": "I should adjust based on wrong approach choices (P = no), not merely on F = hard. Ease ratings are not the training target."}]}, {"focus": "Build mixed review sets", "review": "Once you have encoded a few related topics, build mixed review sets: alternate problem types, shuffle subjects within a session, and mix the kinds of questions you ask yourself. Prepare the set *before* you start so you do not drift back into blocks mid-session.", "task": {"do": "Create a 9-item mixed review set from your own materials (3 topics or problem types, Ready + related). Write prompts/problem numbers on a single shuffled list. Complete the set without re-sorting by type — about 9–10 minutes.", "capture": "Paste the shuffled list (short labels) and score approach choice + answer quality briefly.", "minutes": 10}, "check": [{"q": "If halfway through you regrouped all type-2 items together \"to go faster,\" what did that do to the practice?", "rubric": "correct: Collapsed back toward blocking and removed choice practice. mostly_correct: Hurt interleaving vaguely. incorrect: Improved interleaving; required by the method.", "exemplar": "Regrouping by type collapsed the set back toward blocking and removed the approach-choice practice. I needed to keep the shuffled order."}, {"q": "What features of your pre-built list best match how interleaving should be used in a session?", "rubric": "correct: Shuffled related types and varied question kinds on one sheet prepared in advance. mostly_correct: Mentions a mix vaguely. incorrect: Separated A then B then C blocks; unencoded new lectures; single stem only.", "exemplar": "My list shuffled related types and varied question kinds on one sheet before I started. Separated blocks labeled A then B then C would not match."}, {"q": "If two of your three topics were unrelated to the third, how should you fix the set?", "rubric": "correct: Rebuild so every type could be confused or combined with the others. mostly_correct: Change topics vaguely. incorrect: Add more unrelated courses; remove all variety.", "exemplar": "I should rebuild so every type could be confused or combined with the others. Relatedness among mixed items preserves discrimination value."}]}, {"focus": "Pair with strong retrieval", "review": "Interleaving pairs best with active recall at higher-order levels — not recognition glances in a mixed order. Mixing weak review still yields weak learning. Today every interleaved item must be produced or solved before you check, with at least one compare/choose/explain prompt.", "task": {"do": "Run a short interleaved set (6 items, related Ready topics). For each: closed production/solution first; include at least two higher-order prompts (compare, choose approach, explain why not the other method). Check only after each attempt — about 8–10 minutes.", "capture": "List items with type tags, note which were higher-order, and where approach choice failed.", "minutes": 9}, "check": [{"q": "If you interleaved but peeked at solutions early, what broke — and why can't mixing fix that alone?", "rubric": "correct: Active recall broke; mixing cannot fix recognition-first checking. mostly_correct: Peeking bad vaguely. incorrect: Peeking required for interleaving; only the timer broke.", "exemplar": "Active recall broke. Interleaving amplifies good retrieval — it cannot fix recognition-first peeking."}, {"q": "Which item in your set best combined interleaving with higher-order thinking? Describe the prompt.", "rubric": "correct: Compare/choose/why-not-the-other on a shuffled confusable pair. mostly_correct: Names a hard item without higher-order feature. incorrect: Recognize highlighted definition; reread summary; copy worked example.", "exemplar": "My best item asked why this method instead of the other on a shuffled confusable pair. That hits both mixing and higher-order choice."}, {"q": "Where approach choice failed on a higher-order item, what is the best follow-up for future mixes?", "rubric": "correct: Keep that pair in future mixes with which-method/why prompts. mostly_correct: Practice it again vaguely. incorrect: Avoid higher-order prompts; only block forever; drop active recall.", "exemplar": "I should keep that pair in future mixes and re-ask which method and why. Failed discriminations are exactly what to re-interleave."}]}, {"focus": "Full interleaved revision session", "review": "Run a complete mini revision: Ready related topics only, pre-shuffled set, switches before closure, expect messiness, retrieve first, include approach-choice questions. This is how interleaving should look in a real study block for your course.", "task": {"do": "Prepare and complete a 10–12 minute interleaved session on 2–3 related Ready topics from your exam list: shuffled items, forced switches every ~2 minutes, no peeking first, end with a 1-minute note on which discriminations are still shaky.", "capture": "Session plan (topics + shuffle), shaky discriminations, and one adjustment for next time.", "minutes": 10}, "check": [{"q": "Which feature of the session you just ran is non-negotiable for real interleaving?", "rubric": "correct: Mixing related Ready material so approach choice stays in play. mostly_correct: Mentions mixing without Ready/related. incorrect: Finish every topic to 100% before switching; only unrelated subjects; must feel smoother than blocking.", "exemplar": "Mixing related Ready material so I still had to choose approaches was non-negotiable. Finishing each topic to completion before switching would have broken it."}, {"q": "Your shaky-discrimination note lists a pair. How should you design the next session around it?", "rubric": "correct: Heavier mix of that pair with which/why prompts. mostly_correct: Practice the pair vaguely. incorrect: Avoid the pair; long blocks without mixing; recognition highlights.", "exemplar": "Next session should mix that pair more heavily with \"which method / why\" prompts — not avoid it or bury it in pure blocking."}, {"q": "The session felt worse than yesterday's blocked review. What does this subject predict about that feeling versus exam-relevant training?", "rubric": "correct: Worse feel can still mean better exam-relevant choice training (desirable difficulty). mostly_correct: Hard can be good vaguely. incorrect: Felt bad means done wrong; blocking always predicts higher scores; feelings are only metric.", "exemplar": "This subject predicts that a worse feel can still mean better exam-relevant training. Desirable difficulty trains the choice skill exams use even when blocking felt nicer."}]}, {"focus": "Checkpoint: mix on purpose", "review": "Checkpoint with fresh related topics: readiness gate, related-only mix, switch before done, tolerate worse feel, retrieve before checking, and judge approach choice. New scenarios — same hard moves.", "task": {"do": "Pick two related Ready topics not used yesterday. Build a 6-item shuffle; mid-struggle switches; mark approach choice yes/no; write one \"why not the other method?\" answer from memory for a miss.", "capture": "Shuffle labels, yes/no marks, and the why-not-the-other explanation.", "minutes": 9}, "check": [{"q": "You switched topics while still struggling. Which rule did that practice, and why leave work unfinished on purpose?", "rubric": "correct: Switch before you're done — switching is the point; unfinished struggle preserves interleaving. mostly_correct: Mentions switching vaguely. incorrect: Always finish blocks; mix only unrelated; avoid struggle.", "exemplar": "That practiced \"switch before you're done.\" Leaving unfinished struggle on purpose keeps the rotation — finishing for closure would recreate blocking."}, {"q": "A miss happened because you treated item 4 like item 3's type. What is the best fix in future sets?", "rubric": "correct: More interleaved reps that hide the type label until you choose. mostly_correct: Be more careful vaguely. incorrect: Longer blocked drills only; stop checking approach; recognition-only reviews.", "exemplar": "I need more interleaved reps that hide the type until I choose. Autopilot from the previous item is exactly what interleaving disrupts — longer blocked drills would reinforce it."}, {"q": "If your why-not-the-other explanation was vague, what should you train next inside mixed sets?", "rubric": "correct: Conditional discrimination — when/why each approach wins. mostly_correct: Better explanations vaguely. incorrect: Only memorize definitions in order; avoid explanations; block until explanations feel unnecessary.", "exemplar": "I should train conditional discrimination inside mixed sets — when and why each approach wins. Vague why-not answers mean that choice knowledge is still weak."}]}]}, {"id": "theory-overload", "title": "Learning Skills & Mental Models", "order": 11, "lesson": "theory-overload.html", "days": [{"focus": "The experiential cycle", "review": "You cannot improve a skill by blindly repeating it. Improvement is a loop: *experience → observe the result → decide what to change → experiment.* Random arrows never teach you how to aim; a bad result must tell you what to adjust. Same with studying: a bad exam means little unless you learn what to change.", "task": {"do": "Pick one study skill you used this week on your own coursework (e.g., mapping, free recall, flashcards). Write one recent attempt (experience), what happened (observe), one concrete change (decide), and when you will try it (experiment) — about 8 minutes.", "capture": "Fill the four steps with specifics from your real study, not generics.", "minutes": 8}, "check": [{"q": "If your \"observe\" line only said \"it went badly,\" what is missing — and why does that break the cycle?", "rubric": "correct: Needs a result specific enough to suggest what to adjust; without it decide/experiment stay aimless. mostly_correct: Wants more detail vaguely. incorrect: Observation optional; more quotes/theory replace specific observation.", "exemplar": "What's missing is a specific result that suggests what to change — e.g., \"missed 3 links on free recall.\" \"Went badly\" cannot drive a useful experiment, so blind repetition continues."}, {"q": "Does your capture form a real experiential cycle? Point to each step, or say what is still generic.", "rubric": "correct: Shows experience → specific observe → concrete decide → timed experiment on real study. mostly_correct: Partial cycle with one vague step. incorrect: \"Study harder,\" theory-only, or identical repeat with hope.", "exemplar": "Yes: tried free recall → missed 3 links → map first 5 minutes next time → Thursday 7pm. That is experience, observation, decision, and a scheduled experiment."}, {"q": "Why is an exam score alone usually not enough observation to improve a study skill?", "rubric": "correct: Scores rarely say what process to change; need process-level observation. mostly_correct: Scores incomplete vaguely. incorrect: Observation wastes time; experiments should be random; only theory improves skills.", "exemplar": "A score says little about what to change in the process. Without observing how I studied, I cannot decide a useful experiment — that is why the cycle needs process detail."}]}, {"focus": "Spot cognitive overload", "review": "Working capacity is limited. Every new technique adds things to think about, and an unfamiliar skill already burns capacity just to perform. Pile on many new techniques at once and you overflow — *cognitive overload* — and learn almost nothing. Going \"fast\" through content while overloaded can make you worse.", "task": {"do": "List every new study technique or tool you tried to use in the last 7 days during real study. Star any session where you felt flooded, slower, or less accurate. Circle how many techniques were active in your worst session — about 8 minutes.", "capture": "Technique list, starred overloaded sessions, and the count from the worst one.", "minutes": 8}, "check": [{"q": "Looking at your worst session's technique count, what is the best reading if you felt flooded and less accurate?", "rubric": "correct: Likely cognitive overload — capacity spent performing unfamiliar methods, little left to learn. mostly_correct: Too much at once vaguely. incorrect: Add more techniques; overload = motivation only; speed never risks overload.", "exemplar": "Juggling many new techniques at once was likely cognitive overload — capacity went to performing unfamiliar methods, so little was left to learn the material."}, {"q": "A peer covered more syllabus percent than you but got worse results. How does this lesson explain that pattern?", "rubric": "correct: Racing content while overloaded can beat \"slow\" focused practice on outcomes. mostly_correct: Fast coverage can hurt vaguely. incorrect: More percent always equals more skill; copy their pace; outcomes unrelated to overload.", "exemplar": "They may have raced coverage while overloaded. Going \"fast\" through content with no capacity left can produce worse learning than slower, focused practice."}, {"q": "Based on your starred sessions, what is the strongest cut you should make — and what temptation should you resist?", "rubric": "correct: Reduce simultaneous new techniques; resist adding apps/methods or ignoring accuracy drops while going faster. mostly_correct: Do less vaguely. incorrect: Add a new app per weakness; more theory before any narrowing.", "exemplar": "I should reduce how many new techniques I run at once. Adding another app tonight or ignoring accuracy drops while \"going faster\" would deepen the overload."}]}, {"focus": "Learn slower to learn faster", "review": "The counterintuitive rule: to learn a skill fast, learn *slower*. Only work on **one or two** new things at a time. Spreading attention across a dozen methods feels ambitious; it usually stalls all of them. Today you choose a narrow focus for your real study skill practice.", "task": {"do": "From your technique list (or current goals), pick at most two study skills to improve for the next 7 days. Write what you will *not* add until those get easier. Apply one of the two in today's actual coursework for a short block — about 8 minutes planning + doing.", "capture": "Your 1–2 focus skills, the \"not now\" list, and a 3-line note on today's application attempt.", "minutes": 8}, "check": [{"q": "Why is a long \"not now\" list aligned with learning skills faster, not a failure of ambition?", "rubric": "correct: One or two new things at a time prevents overload and speeds real skill gain. mostly_correct: Focus helps vaguely. incorrect: Guilt for not doing everything; not-now reduces ambition permanently; all techniques must start same week.", "exemplar": "Deferring most techniques protects the one-or-two rule. That prevents overload and actually speeds skill gain — it is the method, not a lack of ambition."}, {"q": "After an overloaded week, which focus choice is healthiest — and what would an unhealthy \"catch up\" plan look like?", "rubric": "correct: One familiar-enough skill to stabilize, optionally one new — not seven new methods or theory-only waiting. mostly_correct: Narrow focus vaguely. incorrect: Seven new methods; zero practice until more videos; random daily switching among ten apps.", "exemplar": "Healthiest is stabilizing one familiar-enough skill, maybe adding one new. Trying seven new methods to \"catch up\" would recreate overload."}, {"q": "You are tempted mid-week by a video to add a third new method. What should you do with that idea?", "rubric": "correct: Park on not-now until a current focus becomes habitual. mostly_correct: Wait vaguely. incorrect: Start immediately alongside both; replace sleep; drop focuses to chase novelty.", "exemplar": "I park it on the not-now list until one current focus becomes habitual. Starting it immediately beside both focuses breaks the one-or-two rule."}]}, {"focus": "Theory without practice (and the reverse)", "review": "Practice with no theory is aimless; practice with too much theory overloads you. Skill learning needs both — in balance. Today you diagnose your recent week: were you collecting methods without reps, or grinding reps with no idea what to adjust?", "task": {"do": "For your chosen focus skill, log the last 5 study days: minutes of new theory/videos/articles vs minutes of deliberate practice on your coursework. Circle which side dominated. Plan tomorrow's block to correct the imbalance — about 8 minutes.", "capture": "Rough theory vs practice minutes and tomorrow's corrective plan.", "minutes": 8}, "check": [{"q": "If your log shows lots of method videos and almost no practice on real material, what is the risk?", "rubric": "correct: Theory overload / knowledge about skills without experiential improvement. mostly_correct: Too much theory vaguely. incorrect: Perfect balance; practice unnecessary if theory is good; double theory again.", "exemplar": "The risk is theory overload — collecting methods without experiential improvement on real coursework. High-quality videos do not replace practice."}, {"q": "If your log shows grinding with no idea what to change, what is the risk — and what does \"enough theory\" mean here?", "rubric": "correct: Aimless practice — need enough theory to guide the next experiment, not endless blind reps. mostly_correct: Need guidance vaguely. incorrect: Stop all practice; more identical blind reps; theory never useful.", "exemplar": "That is aimless practice. I need enough theory to guide the decide step of the cycle — not more identical blind reps, and not abandoning practice."}, {"q": "Does tomorrow's plan restore balance? Explain how it weights theory vs deliberate practice on your material.", "rubric": "correct: Short theory check then mostly deliberate practice on own material. mostly_correct: Mentions practice without clear balance. incorrect: Four new courses first; tips-only scrolling; practice forever with zero adjustment review.", "exemplar": "Yes — a short theory check, then mostly deliberate practice on my own material. Another theory binge would not restore balance."}]}, {"focus": "The ~5:1 practice guideline", "review": "As a rule of thumb, aim for about **5 hours of practice per 1 hour of new theory** — but adjust to *how fast you form habits*, not the clock alone. The ratio exists to keep theory from outrunning the experiential cycle. Today you set a personal ratio target for your focus skill.", "task": {"do": "Choose one bit of theory you recently added (a technique rule). Schedule practice blocks on your real coursework totaling ~5× that theory time before allowing another new technique video/chapter. Put the practice blocks on your calendar — about 8 minutes.", "capture": "Theory item + minutes, planned practice minutes/dates, and the \"no new theory until\" rule you set.", "minutes": 8}, "check": [{"q": "Using your theory minutes, roughly how much deliberate practice should you lean toward before more theory — and how flexible is that number?", "rubric": "correct: About 5× theory time as a rule of thumb, adjusted to habit speed. mostly_correct: More practice than theory vaguely. incorrect: Another equal video immediately; zero practice if notes neat; exactly 5 minutes only ever.", "exemplar": "If I took 30 minutes of theory, I lean toward about 2.5 hours of deliberate practice before more theory — adjusting upward if habits form slowly."}, {"q": "You form habits slowly and still feel clumsy. How should you use the 5:1 guideline without treating it as shame?", "rubric": "correct: Stay in practice longer before adding theory — adjust to habit formation. mostly_correct: Need more practice vaguely. incorrect: Binge theory despite clumsiness; quit; treat needing more practice as shame.", "exemplar": "I stay in practice longer before adding theory. Needing more than 5:1 while still clumsy is adjusting to habit speed — not a failure of the guideline."}, {"q": "What about your calendar pattern shows the guideline became real rather than aspirational?", "rubric": "correct: Practice blocks booked before the next new-theory slot / gated new theory. mostly_correct: Mentions practice plans vaguely. incorrect: Theory every day with practice \"sometime\"; only weekend theory; random YouTube with no dates.", "exemplar": "I booked practice blocks and set a no-new-theory-until rule before the next video. Theory-every-day with practice \"sometime\" would leave the guideline aspirational only."}]}, {"focus": "Habits free capacity", "review": "When a skill becomes a *habit*, it frees capacity for the next bit of theory. You know a habit is forming when something gets easier and faster *without* losing accuracy. Then — and only then — add more theory. Today you test a focus skill for habit signals on real work.", "task": {"do": "Run your focus skill on a short piece of coursework (6–7 min). Score ease (1–5), speed vs last week, and accuracy (kept / dropped). Decide: Habit forming (may add a little theory) or Still fragile (practice only) — about 8 minutes.", "capture": "Ease, speed note, accuracy, and Habit forming vs Still fragile with one reason.", "minutes": 8}, "check": [{"q": "If ease and speed rose but accuracy fell, what decision should you make about adding theory — and why?", "rubric": "correct: Still fragile — do not add theory yet; protect accuracy while practicing. mostly_correct: Wait vaguely. incorrect: Habit formed — binge methods; accuracy never matters; stop practicing because speed rose.", "exemplar": "Still fragile — I do not add theory yet. Habit requires easier/faster without losing accuracy; speed alone is not enough."}, {"q": "If ease, speed, and accuracy all look better, what is the best next move — and what stacking mistake should you still avoid?", "rubric": "correct: May add a small next piece of theory; still avoid adding many techniques at once. mostly_correct: Add theory vaguely. incorrect: Add five techniques at once; never add theory again; switch skills hourly.", "exemplar": "I may add a small next piece of theory because capacity is freer — but still only one small addition, not five new techniques at once."}, {"q": "Why wait for habit before stacking methods, in terms of working capacity?", "rubric": "correct: Habit frees capacity; stacking earlier invites overload. mostly_correct: Waiting helps vaguely. incorrect: Habits make theory useless; waiting only about motivation.", "exemplar": "Habit frees working capacity so the next theory can land. Stacking methods earlier overflows capacity again and recreates overload."}]}, {"focus": "Expected value thinking", "review": "Mental models are simplified frameworks for thinking and deciding. A favorite is *expected value*: do not judge a decision as simply good or bad; weigh the range of likely outcomes and choose what wins *on average over many repetitions*, not just once. Use this on a real study decision this week.", "task": {"do": "Take one real study decision (e.g., block vs interleave tonight; add cards vs map; study now vs scroll). List 2–3 plausible outcomes for each option with rough upside/downside. Choose the option that wins on average across repetitions — about 8 minutes.", "capture": "Decision, options, outcome sketches, and your EV-style choice with a one-line why.", "minutes": 8}, "check": [{"q": "You almost chose what feels best once tonight. What does expected value push you to choose instead?", "rubric": "correct: The option that wins on average across many study nights. mostly_correct: Long-term vaguely. incorrect: Whatever reduces next-five-minutes discomfort; ignore outcomes; always novel shiny method.", "exemplar": "Expected value pushes the option that wins on average across many study nights — not the choice that only feels best for tonight."}, {"q": "What in your capture shows you used the model rather than a slogan?", "rubric": "correct: Multiple outcomes sketched per option before choosing. mostly_correct: Mentions weighing options vaguely. incorrect: Good vibes only; copy friend blindly; avoid deciding.", "exemplar": "I sketched multiple plausible outcomes for each option before choosing. That weighing is the model — \"good vibes\" with no outcomes listed is not."}, {"q": "If your EV choice is harder tonight but better across a month of sessions, is that aligned? Why?", "rubric": "correct: Yes — average-over-repetitions can disagree with tonight's comfort. mostly_correct: Hard can be good vaguely. incorrect: Only tonight's mood counts; EV forbids hard options; models cannot apply to study.", "exemplar": "Yes — choosing what wins across many reps often means accepting short-term difficulty tonight. Expected value is not the same as tonight's comfort."}]}, {"focus": "Models need good inputs", "review": "A model is only as good as how you apply it. Wrong context or bad data and it confidently leads you off a cliff (like choosing a \"higher-probability\" campaign from flawed past data and losing money). Pick the right model, question inputs, and check whether the situation fits the model's assumptions.", "task": {"do": "Revisit yesterday's study decision (or a new one). Write: (1) which model/rule you are using, (2) the inputs you assumed, (3) one way those inputs could be wrong, (4) a quick check against your real constraints (time, readiness, exam type) — about 8 minutes.", "capture": "Model, inputs, possible flaw, and whether you keep, adjust, or reject the choice.", "minutes": 8}, "check": [{"q": "If you found an input was wishful (for example, \"I have 4 free hours\") but false, what should happen to the decision?", "rubric": "correct: Adjust or reject — bad inputs make confident wrong answers. mostly_correct: Change something vaguely. incorrect: Keep because model sounded smart; ignore constraints; never question inputs.", "exemplar": "I should adjust or reject the decision. Bad inputs make even a good model confidently wrong — keeping a fantasy schedule because it sounds smart fails the lesson."}, {"q": "What self-check best matches the lesson's warning about applying models?", "rubric": "correct: Does this situation fit the model's assumptions? mostly_correct: Question the plan vaguely. incorrect: Is the model famous?; thumbnail recommended it?; apply without looking at real course.", "exemplar": "I should ask whether this situation actually fits the model's assumptions. Fame or a video thumbnail is not a fit check."}, {"q": "You used expected value but ignored that a topic is not Ready for interleaving. What went wrong in the application?", "rubric": "correct: Wrong context — model applied outside conditions where the option is valid. mostly_correct: Missed a constraint vaguely. incorrect: EV overrides readiness; readiness unrelated; models replace course constraints.", "exemplar": "Wrong context — I applied EV outside conditions where interleaving is valid. Right model, wrong situation still fails when readiness constraints are ignored."}]}, {"focus": "Apply: one skill, balanced reps", "review": "Combine the subject's tools on your real learning skill: run an experiential cycle, keep only one or two focuses, balance theory with practice (~5:1 mindset), wait for habit signals before adding more, and use a mental model carefully with audited inputs.", "task": {"do": "For your focus skill and one coursework task (~10 min): practice the skill, observe result, decide one micro-adjustment, note theory minutes vs practice minutes this week, and confirm you are not adding a new technique today.", "capture": "Cycle notes, weekly theory/practice sketch, and confirmation of the one/two-focus rule.", "minutes": 10}, "check": [{"q": "What from today's session shows you avoided theory overload?", "rubric": "correct: Practiced on real material and refused a new technique pile-on. mostly_correct: Focused practice vaguely. incorrect: Watched many method videos mid-session; started five focuses; skipped observation to go faster.", "exemplar": "I practiced on real material and refused to add a new technique today. That focused practice — not stacking theory — is the anti-overload move."}, {"q": "If your micro-adjustment lacks a next experiment time, what is the fix?", "rubric": "correct: Schedule the experiment — decide without trying changes little. mostly_correct: Try it sometime vaguely. incorrect: Collect more theory instead; abandon the cycle; only adjust yearly.", "exemplar": "I need to put the experiment on the calendar. A decide step without a try time leaves the experiential cycle unfinished."}, {"q": "Accuracy is still shaky but you want a new model video. What do habit rules say?", "rubric": "correct: Wait — keep practicing until easier/faster without accuracy loss. mostly_correct: Wait vaguely. incorrect: Watch now and add two more methods; replace practice with model notes; ignore accuracy.", "exemplar": "Wait — keep practicing until the skill is easier and faster without accuracy loss. Shaky accuracy means capacity is not free for new theory yet."}]}, {"focus": "Checkpoint: skills without overload", "review": "Checkpoint with a fresh study-skill scenario from your week: diagnose overload, enforce one/two focuses, rebalance theory vs practice, test habit signals, and stress-test a model's inputs. Judge your plans and attempts — not trivia about definitions.", "task": {"do": "Write a mini case on a real recent study stumble. Label: overload? focus count? theory/practice skew? habit ready? model/input flaw? Then prescribe a 7-day correction with at most two focuses and scheduled practice — about 9 minutes.", "capture": "Labels + 7-day prescription (focuses, practice times, theory gate).", "minutes": 9}, "check": [{"q": "If your case shows five new techniques and falling accuracy, what should be the first element of the prescription?", "rubric": "correct: Cut to one or two focuses and gate new theory. mostly_correct: Narrow focus vaguely. incorrect: Add more techniques; only read about overload; chase syllabus percent while ignoring accuracy.", "exemplar": "First I cut to one or two focuses and gate new theory. Adding more techniques or chasing syllabus percent while accuracy falls deepens overload."}, {"q": "Your 7-day plan schedules practice before new videos. What guideline does that most directly support?", "rubric": "correct: Practice-to-theory balance / ~5:1 mindset. mostly_correct: Balance vaguely. incorrect: Blind repetition with no observation; maximum theory density; skip experiential cycle.", "exemplar": "Scheduling practice before new videos supports the practice-to-theory balance and ~5:1 mindset — theory stops outrunning the experiential cycle."}, {"q": "You used a model but your prescription ignored a false time input. What is the checkpoint fix?", "rubric": "correct: Rewrite the plan with honest inputs — models fail when data is wrong. mostly_correct: Fix the plan vaguely. incorrect: Keep fantasy schedule; never use models again; assume constraints vanish.", "exemplar": "I rewrite the plan with honest time inputs. A model applied to false data confidently produces a bad schedule — ambition on paper is not a fix."}]}]}, {"id": "motivation-systems", "title": "Motivation & Your Study System", "order": 12, "lesson": "motivation-systems.html", "days": [{"focus": "Motivation-enhanced, not dependent", "review": "Most people are *motivation-dependent*: they wait to feel like working, then burn motivation overcoming every barrier. Motivation fluctuates with sleep, mood, health, and company — so productivity swings, and constant willpower leads to burnout. Aim to be *motivation-enhanced*: use motivation when you have it, but do not need it to start.", "task": {"do": "Review your last 5 study attempts on real coursework. Mark each Started despite low motivation (S) or Waited for motivation (W). Note one barrier you only overcome when \"in the mood.\" Plan a 10-minute start for today that does not require feeling ready — about 8 minutes.", "capture": "S/W marks, the barrier, and today's non-negotiable 10-minute start (topic + time).", "minutes": 8}, "check": [{"q": "Looking at your S/W marks, what system problem do mostly-W patterns reveal?", "rubric": "correct: Motivation-dependence — output tracks feelings instead of process. mostly_correct: Waiting is a problem vaguely. incorrect: Starting without motivation impossible; wait longer for perfect mood; quotes alone fix it.", "exemplar": "Mostly W marks show motivation-dependence — my output tracks whether I feel like working instead of following a process I can start flat."}, {"q": "Which planned start from today best matches motivation-enhanced behavior, and why?", "rubric": "correct: Fixed short block begun on time even if flat; contrasts with inspiration-conditional plans. mostly_correct: Mentions starting anyway vaguely. incorrect: Only if inspired; only high-energy days; cancel when mood dips.", "exemplar": "My fixed 10-minute block at a set time matches motivation-enhanced — I begin even if flat. \"I'll study if I feel inspired after dinner\" would still be dependence."}, {"q": "If you used motivation to smash barriers when hyped and then crashed, how should you read that pattern?", "rubric": "correct: Burning willpower through every barrier fuels burnout — redesign barriers rather than hero them. mostly_correct: Unsustainable vaguely. incorrect: Rely on hype more; systems irrelevant; only sleep when motivated.", "exemplar": "That pattern is burning willpower through every barrier until burnout. I should redesign and defuse barriers — not wait for hype to hero through them again."}]}, {"focus": "D — Distinguish", "review": "DEFUSE builds thought–action defusion: separating what you do from how you feel. **D — Distinguish** feelings, thoughts, and actions. \"I feel tired\" is a sensation; it does not have to trigger \"therefore I must rest.\" Labeling the three strands weakens automatic fusion.", "task": {"do": "Before a real study block (or a 8-minute micro-block now), write three lines: Feeling (body/mood), Thought (story you're telling), Action you will take anyway on your coursework. Start the action for at least 5 minutes — about 8 minutes total.", "capture": "The three lines and what you actually did in the 5 minutes.", "minutes": 8}, "check": [{"q": "If you wrote \"I'm tired, so I can't study\" as one blob, what did Distinguish ask you to do instead?", "rubric": "correct: Split sensation vs story vs chosen action so tired ≠ automatic stop. mostly_correct: Separate feelings vaguely. incorrect: Suppress all feelings; only study when thoughts positive; treat every feeling as a command.", "exemplar": "Distinguish asks me to split the tired sensation, the \"I can't study\" story, and the action I choose anyway. Tired does not have to mean automatic stop."}, {"q": "What in your capture shows defusion starting to work?", "rubric": "correct: Named the feeling/thought and still began the planned coursework action. mostly_correct: Started somehow. incorrect: Waited until tiredness vanished; only journaled; used tiredness as proof of laziness.", "exemplar": "I named tiredness and still began the planned coursework for five minutes. Acting alongside the feeling — not after it disappears — is defusion starting."}, {"q": "A thought said \"this review is pointless.\" What is the best Distinguish move during the timed block?", "rubric": "correct: Label it as a thought, then keep the chosen action for the timed block. mostly_correct: Don't obey vaguely. incorrect: Quit immediately; argue an hour first; merge with boredom into one stop rule.", "exemplar": "I label it as a thought and keep the chosen action until the timer ends. Obeying it immediately would fuse thought and action again."}]}, {"focus": "F — Fake it", "review": "**F — Fake it.** Like an actor playing a non-tired character, do the actions of someone who is not tired. Bonus: acting productive often makes you *feel* more productive — it works both ways. \"Just train tired.\" Today you practice the actor move on real material.", "task": {"do": "Choose a low-motivation moment (now if flat). For 8 minutes, act as a focused student: sit in study posture, open your materials, and do a concrete task (recall, map, or problems). No bargaining for \"full energy\" first.", "capture": "What \"in-character\" actions you used, what work you produced, and whether feeling shifted at all.", "minutes": 8}, "check": [{"q": "If you waited to feel productive before acting, which DEFUSE step did you skip — and what order does it require?", "rubric": "correct: Fake it — actions of a productive student first; feelings may follow. mostly_correct: Should have started vaguely. incorrect: Distinguish already finished the method; Zone/Uptime only answers.", "exemplar": "I skipped Fake it. That step reverses the order: do the productive actions first rather than waiting to feel ready."}, {"q": "If feeling improved after a few minutes in character, what does the lesson allow you to conclude?", "rubric": "correct: Action can feed feeling — productivity cues can raise motivation. mostly_correct: Feeling changed somehow. incorrect: Feelings never change; never act until inspired; acting ruins learning.", "exemplar": "Action can feed feeling — acting productive can make me feel more productive. The lesson says it works both ways."}, {"q": "Which attempt today was strongest Fake-it practice? Describe the behaviors and the work.", "rubric": "correct: Posture + materials + real closed-book work while still flat. mostly_correct: Did some studying. incorrect: Couch visualization only; scrolling tips until mood; canceling for vibe.", "exemplar": "Strongest was study posture, materials open, and real closed-book work while still flat. Visualizing on the couch without acting is not Fake it."}]}, {"focus": "U — Uptime", "review": "**U — Uptime.** Gradually extend how long you can hold the defused, acting-productive state — 10 minutes today, 12 tomorrow, then 20, then 30. Neuroplasticity makes it easier over time. Do not jump from zero to a hero marathon; stretch the window on real coursework.", "task": {"do": "Set a slightly longer focused block than your recent average (e.g., +2–5 minutes). Use Distinguish + Fake it, work your own material until the timer ends. Log duration and whether you held the state — about 8–12 minutes depending on your stretch.", "capture": "Previous typical minutes, today's target, actual minutes held, and one friction point.", "minutes": 10}, "check": [{"q": "If you tried a multi-hour leap after days of short starts, what is the better Uptime approach?", "rubric": "correct: Small extensions — build the window gradually (e.g., 10→12→20→30). mostly_correct: Go slower vaguely. incorrect: Hero sessions only then burnout rest; never extend past 5; skip timers forever.", "exemplar": "Better Uptime is small extensions — stretch from my recent average by a few minutes, not a sudden 3-hour leap that recreates burnout."}, {"q": "You held focus a couple of minutes past your old average. What does that number represent in Uptime training?", "rubric": "correct: The hold length is the skill being stretched — small gains count. mostly_correct: Progress vaguely. incorrect: Meaningless; failure because not a full evening; stop timing.", "exemplar": "That extra couple of minutes is Uptime training — the skill is extending how long I can hold the state. Small gains count; it does not have to be a full evening."}, {"q": "Friction hit before your target ended. What is the best mid-block response using DEFUSE?", "rubric": "correct: Re-Distinguish, stay in character, finish the timer on the task. mostly_correct: Keep going vaguely. incorrect: Quit for motivation; scroll \"as a break\" until timer dies; add three new techniques.", "exemplar": "I re-Distinguish, stay in character, and finish the timer on the task. Quitting or scrolling until the timer dies abandons the Uptime practice."}]}, {"focus": "Z — Zone and distraction sheet", "review": "**Z — Zone.** Engineer a distraction-free environment. Keep a *distraction cheat sheet*: note every distraction as it happens, then later remove those triggers (app blockers, phone away, dedicated workspace). Today you build the sheet from a real session and change one trigger.", "task": {"do": "Run a 8–10 minute study block on your coursework. Each time attention pulls away, jot the trigger on a cheat sheet (do not indulge long). Afterward, pick one trigger and remove or block it for your next session — about 10 minutes.", "capture": "Cheat sheet entries and the one environmental change you will implement next.", "minutes": 10}, "check": [{"q": "If your sheet lists the same trigger repeatedly (for example, phone buzz), what is the strongest Zone move before the next block?", "rubric": "correct: Remove/block the trigger (phone away, DND) — not endless willpower. mostly_correct: Reduce distractions vaguely. incorrect: Rely on willpower forever; keep phone face-up; blame motivation only.", "exemplar": "I remove or block that trigger before the next block — phone away and DND. The cheat sheet exists so I can eliminate triggers, not admire them with more willpower."}, {"q": "Why jot distractions during the block instead of only trying to remember them later?", "rubric": "correct: Capture real triggers as they happen for later removal. mostly_correct: Accuracy vaguely. incorrect: Writing replaces studying permanently; sheets decorative; stop the block at every jot forever.", "exemplar": "Live capture makes the cheat sheet accurate so I can redesign the environment later. Remembering afterward usually misses what actually pulled attention."}, {"q": "How should your next-session setup use today's sheet?", "rubric": "correct: One concrete trigger removed plus the same coursework task ready. mostly_correct: Change environment vaguely. incorrect: Identical distraction-rich setup to \"build tolerance\"; no plan; more tabs for inspiration.", "exemplar": "Next session I implement one concrete trigger removal and start with the coursework task ready. Keeping the same distraction-rich setup to \"build tolerance\" misses Zone."}]}, {"focus": "Session prep that protects focus", "review": "A focused session has phases — do not just dive in. **Prep:** clear workspace, drinks ready, phone and computer on Do Not Disturb, tell people not to disturb you. Pre-eliminate distractions you can predict. Prep is part of the system, not optional nicety.", "task": {"do": "Before studying your own material, run a 5-minute prep checklist: workspace, water/drink, DND, phone placement, one message to housemates/family if needed, materials open to the exact task. Then start a short encode or recall block — about 8–10 minutes total.", "capture": "Checklist what you set, what you forgot last time, and the first study action you took after prep.", "minutes": 9}, "check": [{"q": "If you used to \"just start\" and then hunt for chargers mid-block, what does Prep fix?", "rubric": "correct: Predictable distractions and friction that burn motivation mid-session. mostly_correct: Reduces interruptions vaguely. incorrect: Replaces retrieval practice; fixes sleep; changes curriculum content.", "exemplar": "Prep pre-eliminates predictable friction — like missing chargers — so I am not spending willpower on logistics mid-session."}, {"q": "Which items from your checklist best match the lesson's prep phase, and what would undermine it?", "rubric": "correct: Cleared workspace, DND, drinks, materials ready; undermines = social warm-up, skipping drinks to leave, materials packed until inspiration. mostly_correct: Lists some prep without contrast. incorrect: Opening social feeds as warm-up as a prep win.", "exemplar": "Phone/computer on DND and workspace cleared before the timer match prep. Opening social feeds for a \"quick warm-up\" undermines it."}, {"q": "After prep you still dove into random tabs. How should the next start look?", "rubric": "correct: Materials open to the exact task as the last prep step before timing. mostly_correct: Be more focused vaguely. incorrect: Prep without a defined first action; prep then scroll; skip prep if motivated.", "exemplar": "The last prep step should leave materials open to the exact task before I start the timer. Motivation is not a substitute for that handoff."}]}, {"focus": "Encode then retrieve in one session", "review": "After prep: **Encode** — read actively and build the big picture in a non-linear map; embrace early confusion. Then **Consolidate / retrieve** — active recall, and only a small spaced set for pure facts if needed. Later, revisit at spaced, ideally interleaved intervals. Today you run encode → retrieve on your material.", "task": {"do": "One topic from your course: 4 minutes keyword/relationship mapping (encode), 4 minutes closed-book production (retrieve). Star gaps. Optional: mark at most 2 facts that truly need a card — about 8–9 minutes.", "capture": "Map gist, retrieval gaps, and 0–2 card candidates only.", "minutes": 9}, "check": [{"q": "If you spent a block mostly rereading without a map or closed production, which session phases did you skip?", "rubric": "correct: Encode (active big picture) and consolidate/retrieve. mostly_correct: Skipped active work vaguely. incorrect: Only prep/sleep; rereading is the full system.", "exemplar": "I skipped encode — active big-picture mapping — and consolidate/retrieve. Rereading alone is not the structured session."}, {"q": "You wanted many new cards after one short encode. What is the better call, and why?", "rubric": "correct: Keep cards tiny for pure facts; let the map carry relationships — avoid debt explosion. mostly_correct: Fewer cards vaguely. incorrect: Card every sentence; skip retrieval because cards later; avoid maps.", "exemplar": "I keep at most a couple of cards for pure facts and let the map carry relationships. Turning the whole encode into dozens of cards creates learning debt."}, {"q": "Early mapping felt confusing. What is the lesson-aligned response during encode?", "rubric": "correct: Embrace early confusion and keep building the big picture. mostly_correct: Persist vaguely. incorrect: Quit because confusion = failure; passive highlighting only; wait for perfect clarity before notes.", "exemplar": "I embrace early confusion and keep building the big-picture map. Confusion in encode is expected — quitting or waiting for perfect clarity blocks the phase."}]}, {"focus": "Hard-won system lessons", "review": "From 10,000 hours: cram early (whole syllabus early, then fill gaps calmly), sleep is non-negotiable (hero hours broke down when workload doubled), effort feels bad and is good (misinterpreted-effort trap), and improve by making mistakes faster (try, fail, adjust every hour or two). Today you apply one lesson to your calendar and habits.", "task": {"do": "Pick one hard-won lesson and apply it to your real term: e.g., schedule an early full-syllabus pass date, set a sleep floor, replace a \"this feels too hard so I'll stop\" moment with continued effective method, or plan two short try–fail–adjust loops today on coursework — about 8 minutes.", "capture": "Which lesson you chose, the concrete calendar/habit change, and when you will check it.", "minutes": 8}, "check": [{"q": "If you planned to \"catch up\" with an all-nighter before the exam, which hard-won lesson pushes back hardest — and how?", "rubric": "correct: Sleep is non-negotiable — working harder does not scale like learning better. mostly_correct: Sleep matters vaguely. incorrect: Cram early means only night-before; effort-bad means stop; never adjust methods.", "exemplar": "Sleep is non-negotiable pushes back hardest. Hero hours broke down when workload rose — better process beats unsustainable all-nighters."}, {"q": "An effective method feels awful so you almost quit. How should you reframe that per the course?", "rubric": "correct: Effort feels bad and can still be good — misinterpreted effort lies. mostly_correct: Hard can be okay vaguely. incorrect: Discomfort always means wrong method; only easy methods work.", "exemplar": "Effort feels bad and can still be good — the misinterpreted-effort trap whispers that hard methods are failing when they are working."}, {"q": "Which capture best matches \"mistakes faster,\" and what would the opposite look like?", "rubric": "correct: Short try–fail–adjust loops scheduled soon; opposite = wait weeks for perfect system / avoid failed attempts. mostly_correct: Iterate vaguely. incorrect: One yearly reflection only as the win.", "exemplar": "Two short try–fail–adjust loops today matches mistakes faster. Waiting weeks for a perfect system before trying is the opposite."}]}, {"focus": "Full DEFUSE + structured session", "review": "Combine the system: prep the zone, Distinguish/Fake it/Uptime through a realistic block, encode then retrieve on your material, and keep the plan sustainable. Start small — even 15 focused minutes — with one technique done consistently. Motivation can amplify; process carries the day.", "task": {"do": "Run a ~12–15 minute full session on one course topic: prep + Zone change from your cheat sheet, Distinguish lines, Fake-it start, encode map (~5 min), closed retrieve (~5 min), log uptime minutes and one gap to revisit.", "capture": "Prep/Zone change, feeling/thought/action lines, map+gap notes, minutes held.", "minutes": 12}, "check": [{"q": "Walk through the sequence you just ran. How does it match prep/Zone → defuse start → encode → retrieve?", "rubric": "correct: Describes that sequence on real material. mostly_correct: Partial sequence. incorrect: Motivation videos → all-nighter; card binge with no prep; wait for mood → theory binge.", "exemplar": "I prepped and changed one Zone trigger, Distinguished feeling/thought/action, Fake-it started, mapped, then closed retrieved. That is prep/Zone → defuse → encode → retrieve."}, {"q": "Motivation was low but you completed the block. What does that demonstrate about motivation-enhanced vs dependent?", "rubric": "correct: Motivation-enhanced — process worked without needing the feeling. mostly_correct: Started anyway vaguely. incorrect: DEFUSE failed; must only work when hyped; prep optional next time.", "exemplar": "It demonstrates motivation-enhanced behavior — the process carried the session without needing hype. Dependence would have canceled because mood was flat."}, {"q": "What is the best \"where to go from here\" move after this full session?", "rubric": "correct: Protect a realistic daily block and keep one technique for a week before adding the next. mostly_correct: Stay consistent vaguely. incorrect: Add every technique tomorrow; abandon process; replace sleep with heroics.", "exemplar": "I protect a realistic daily block and keep one technique consistent for a week before adding the next. Consistency beats adding every method tomorrow or sleeping less for heroics."}]}, {"focus": "Checkpoint: systems over mood", "review": "Checkpoint with a fresh study day scenario: diagnose dependence vs enhanced, run Distinguish/Fake it, stretch uptime slightly, use the distraction sheet, prep properly, and encode→retrieve. Judge today's attempts and plans — not slogan recall.", "task": {"do": "Simulate or run a \"flat day\" protocol on unused coursework: Distinguish 3 lines, 10+ minute Fake-it block with prep/Zone, encode 3 min + retrieve 3 min, add one cheat-sheet fix, schedule tomorrow's slightly longer uptime.", "capture": "Protocol notes, work produced, cheat-sheet fix, tomorrow's uptime target.", "minutes": 10}, "check": [{"q": "Flat mood almost canceled the protocol. What is the strongest checkpoint response?", "rubric": "correct: Distinguish and Fake it into the timed block anyway. mostly_correct: Start somehow. incorrect: Wait indefinitely for motivation; drop Zone because mood low; replace block with technique videos.", "exemplar": "I Distinguish and Fake it into the timed block anyway. Waiting indefinitely for motivation is dependence — checkpoint skill is acting on process when flat."}, {"q": "Your cheat-sheet fix and prep were solid but you skipped closed retrieval. What gap remains in the structured session?", "rubric": "correct: Still need consolidate/retrieve after encode — environment alone is not enough. mostly_correct: Need more learning vaguely. incorrect: Prep replaces learning; retrieval optional if DND on; only Zone matters.", "exemplar": "The gap is consolidate/retrieve after encode. Solid prep and Zone help focus, but they do not replace closed production on the material."}, {"q": "If tomorrow's uptime target jumps from about 12 minutes to 3 hours, how should you adjust — and why?", "rubric": "correct: Use a small increment — gradual Uptime, not hero leaps that recreate burnout. mostly_correct: Smaller target vaguely. incorrect: Keep 3-hour leap; remove timers; only study when motivation guarantees 3 hours.", "exemplar": "I use a small increment — maybe a few minutes past today — not a 3-hour leap. Gradual Uptime builds the hold; hero leaps recreate burnout patterns."}]}]}]};
